module fifo_occ_flags (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_wr,
    input  wire       i_rd,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_full,
    output wire       o_empty
);
