    assign o_empty = (wptr == rptr);

    wire do_wr = i_wr && !o_full;
    wire do_rd = i_rd && !o_empty;

    assign o_data = dout;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
            dout  <= 8'd0;
        end else begin
            if (do_wr) begin
                mem[wptr[2:0]] <= i_data;
                wptr <= wptr + 4'd1;
            end
            if (do_rd) begin
                dout <= mem[rptr[2:0]];
                rptr <= rptr + 4'd1;
            end
            if (do_wr && !do_rd)
                count <= count + 4'd1;
            else if (!do_wr && do_rd)
                count <= count - 4'd1;
        end
    end

    // P: the FIFO is never reported full and empty at the same time
    always @(posedge clk)
        assert (!(o_full && o_empty));
