    reg       armed;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
