        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
            total <= 8'h00;
        end else if (i_ce) begin
            if (i_clear) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
                total <= 8'h00;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
                total <= total + i_data;
            end
        end
    end

    assign o_total = acc_s + acc_c;
    assign o_ref   = total;

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);
