module gray_sync_pointer (
    input wire clk,
    input wire i_ce,
    input wire inc,
    output wire [3:0] o_ptr
);
    // source-domain binary pointer and its registered gray encoding
    reg [3:0] bin;
    reg [3:0] gray_r;
    // two-flop synchronizer carrying the gray pointer to the other domain
    reg [3:0] sync1;
    reg [3:0] sync2;

    initial begin
        bin    = 4'd0;
        gray_r = 4'd0;
        sync1  = 4'd0;
        sync2  = 4'd0;
    end

    wire [3:0] bin_nxt  = inc ? (bin + 4'd1) : bin;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            bin    <= bin_nxt;
            gray_r <= gray_nxt;
            sync1  <= gray_r;
            sync2  <= sync1;
        end
    end

    assign o_ptr = sync2;

    // difference between the two consecutive samples held in the chain
    wire [3:0] diff = sync1 ^ sync2;

    // P: whenever the synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (sync1 != sync2)
            assert ((diff & (diff - 4'd1)) == 4'd0);
endmodule

