// Voice-activity frame accumulator with saturating speech-run counter.
// cnt counts consecutive voiced frames and clamps at MAX=12 (a 4-bit reg
// could hold 15).  peak is a shadow register remembering the largest run
// length ever observed, armed is a sticky flag set the first time a run
// reaches the confirmation threshold, and gate is the speech-active output.
module vad_run_accumulator (
    input  wire       clk,
    input  wire       step,      // frame strobe; low => design idles
    input  wire       voice,     // current frame is above energy threshold
    output reg  [3:0] cnt,
    output reg  [3:0] peak,
    output reg        armed,
    output reg        gate
);
    localparam [3:0] MAX     = 4'd12;
    localparam [3:0] CONFIRM = 4'd8;
    localparam [3:0] OPEN    = 4'd4;

    initial cnt   = 4'd0;
    initial peak  = 4'd0;
    initial armed = 1'b0;
    initial gate  = 1'b0;

    // saturating up-counter, cleared on a silent frame
    wire [3:0] cnt_nxt = voice ? ((cnt == MAX) ? MAX : cnt + 4'd1) : 4'd0;

    always @(posedge clk) begin
        if (step) begin
            cnt <= cnt_nxt;

            // shadow register: highest run length seen so far
            if (cnt_nxt > peak)
                peak <= cnt_nxt;

            // sticky arm: a confirmed speech run has happened at least once
            if (cnt_nxt >= CONFIRM)
                armed <= 1'b1;

            // speech-active output
            gate <= (cnt_nxt >= OPEN);
        end
    end

    // Precedence, in the "after armed" scope: once a confirmed run has been
    // observed, any cycle in which the gate is open must be backed by a shadow
    // peak that already reached the confirmation threshold.
    always @(posedge clk)
        if (armed && gate)
            assert (peak >= CONFIRM);
endmodule

