module elastic_buf2 (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       full,
    output wire       empty
);
    // two-entry elastic buffer: one valid flag per slot, head/tail select bits
    reg       v0 = 1'b0;   // slot 0 occupied
    reg       v1 = 1'b0;   // slot 1 occupied
    reg       h  = 1'b0;   // head: slot read next
    reg       t  = 1'b0;   // tail: slot written next
    reg [7:0] m0 = 8'h00;
    reg [7:0] m1 = 8'h00;
    reg [2:0] count = 3'd0; // redundant occupancy counter

    assign full  = v0 & v1;
    assign empty = (~v0) & (~v1);
    assign dout  = h ? m1 : m0;

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            h     <= 1'b0;
            t     <= 1'b0;
            m0    <= 8'h00;
            m1    <= 8'h00;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (t == 1'b0) begin
                    v0 <= 1'b1;
                    m0 <= din;
                end else begin
                    v1 <= 1'b1;
                    m1 <= din;
                end
                t <= ~t;
            end
            if (do_pop) begin
                if (h == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                h <= ~h;
            end
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
        end
    end

    // P: the buffer never holds more than two entries, although count is 3 bits wide
    always @(posedge clk)
        assert (count <= 3'd2);
endmodule

