module triage_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant,
    output reg        locked,
    output reg  [1:0] owner
);
    // Fixed-priority select: channel 0 (escalate) highest, 3 (archive) lowest.
    reg [1:0] sel_idx;
    reg [3:0] sel_oh;

    always @(*) begin
        casez (req)
            4'b???1: begin sel_idx = 2'd0; sel_oh = 4'b0001; end
            4'b??10: begin sel_idx = 2'd1; sel_oh = 4'b0010; end
            4'b?100: begin sel_idx = 2'd2; sel_oh = 4'b0100; end
            4'b1000: begin sel_idx = 2'd3; sel_oh = 4'b1000; end
            default: begin sel_idx = 2'd0; sel_oh = 4'b0000; end
        endcase
    end

    initial begin
        grant  = 4'b0000;
        locked = 1'b0;
        owner  = 2'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            grant  <= 4'b0000;
            locked <= 1'b0;
            owner  <= 2'd0;
        end else if (ce) begin
            if (!locked) begin
                // idle: hand the bus to the highest-priority requester and lock
                if (|req) begin
                    grant  <= sel_oh;
                    owner  <= sel_idx;
                    locked <= 1'b1;
                end
            end else begin
                // locked: grant bits survive only while their request persists,
                // and the lock is released when the owner drops its request
                grant  <= grant & req;
                locked <= req[owner];
            end
        end
    end

    // P: whenever the arbiter is locked, somebody actually holds the bus.
    always @(*) assert (!locked || grant != 4'b0000);
endmodule

