module window_rate_limiter (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes all state
    input  wire req,
    input  wire flush,   // the scope event R: first flush clears the chain flags
    output wire grant
);
    localparam LIMIT = 4;

    // sliding window of recent grants plus a mirroring count of ones
    reg [7:0] win;
    reg [3:0] ones;

    // three-step chain: arm -> start -> finish
    reg saw_arm, saw_start, saw_finish;

    // scope register: high until the first flush ever happens
    reg before_flush;

    initial begin
        win          = 8'b0;
        ones         = 4'd0;
        saw_arm      = 1'b0;
        saw_start    = 1'b0;
        saw_finish   = 1'b0;
        before_flush = 1'b1;
    end

    // rate limiter: a grant is only issued while the window is not saturated
    assign grant = req && (ones < LIMIT);

    // the count of ones moves by at most one per sample
    wire [3:0] ones_next = ones + {3'b000, grant} - {3'b000, win[7]};

    // chain milestones, keyed on the occupancy of the window
    wire arm_evt    = ce && (ones_next == 4'd1);
    wire start_evt  = ce && (ones_next == 4'd2);
    wire finish_evt = ce && (ones_next == 4'd4);

    always @(posedge clk) begin
        if (ce) begin
            win  <= {win[6:0], grant};
            ones <= ones_next;
            if (flush) begin
                before_flush <= 1'b0;
                saw_arm      <= 1'b0;
                saw_start    <= 1'b0;
                saw_finish   <= 1'b0;
            end else begin
                if (arm_evt)    saw_arm    <= 1'b1;
                if (start_evt)  saw_start  <= 1'b1;
                if (finish_evt) saw_finish <= 1'b1;
            end
        end
    end

    // Chain precedence, in the scope before the first flush:
    // finish can never be observed unless start and arm already happened.
    assert property (!before_flush || !saw_finish || (saw_start && saw_arm));

endmodule

