module dma_burst_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       start,
    input  wire [3:0] req_len,
    output reg        busy,
    output reg        beat_valid
);
    // beats remaining in the current burst
    reg [3:0] beats;
    // beats already pushed out in the current burst
    reg [3:0] done_cnt;
    // sticky: set the first time a burst is ever launched
    reg       armed;

    // the engine never accepts a burst longer than 5 beats
    wire [3:0] clamped = (req_len > 4'd5) ? 4'd5 : req_len;

    initial begin
        beats      = 4'd0;
        done_cnt   = 4'd0;
        busy       = 1'b0;
        armed      = 1'b0;
        beat_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            beats      <= 4'd0;
            done_cnt   <= 4'd0;
            busy       <= 1'b0;
            armed      <= 1'b0;
            beat_valid <= 1'b0;
        end else if (ce) begin
            beat_valid <= 1'b0;
            if (busy) begin
                // one beat of the burst leaves the engine
                beats      <= beats - 4'd1;
                done_cnt   <= done_cnt + 4'd1;
                busy       <= (beats > 4'd1);
                beat_valid <= 1'b1;
            end else if (start && clamped != 4'd0) begin
                beats    <= clamped;
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end
        end
    end

    // P: once the engine has ever started a burst, no burst ever delivers
    // more than 5 beats, even though done_cnt is 4 bits wide.
    always @(posedge clk)
        if (armed)
            assert (done_cnt <= 4'd5);
endmodule

