// Input-pin debouncer for a core's external interrupt/reset pin.
// A change on the raw pin must be seen on K=4 consecutive enabled samples
// before the clean output flips.  A countdown register tracks the deadline
// of the outstanding change request.
module pin_debounce_deadline (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // sample enable; low => full idle
    input  wire       raw,     // raw asynchronous pin value (already synced)
    output reg        clean,   // debounced value
    output reg        req      // a pin change is currently outstanding
);
    localparam [2:0] K = 3'd4;

    reg [2:0] stab;  // number of consecutive samples disagreeing with clean
    reg [2:0] cnt;   // countdown to the guaranteed flip deadline

    initial begin
        clean = 1'b0;
        stab  = 3'd0;
        cnt   = K;
        req   = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            clean <= 1'b0;
            stab  <= 3'd0;
            cnt   <= K;
            req   <= 1'b0;
        end else if (ce) begin
            if (raw != clean) begin
                if (stab == K - 3'd1) begin
                    // final identical sample: commit the flip, retire request
                    clean <= ~clean;
                    stab  <= 3'd0;
                    cnt   <= K;
                    req   <= 1'b0;
                end else begin
                    stab  <= stab + 3'd1;
                    cnt   <= cnt - 3'd1;
                    req   <= 1'b1;
                end
            end else begin
                // sample agrees with the clean value: abandon the request
                stab  <= 3'd0;
                cnt   <= K;
                req   <= 1'b0;
            end
        end
    end

    // Bounded response (safety form): the deadline countdown must never reach
    // zero while a pin-change request is still outstanding.
    always @(posedge clk)
        assert (!req || cnt != 3'd0);
endmodule

