module pwm_duty_tracker (
    input  wire       clk,
    input  wire       ce,
    input  wire [3:0] duty_in,
    output reg  [2:0] count,
    output reg  [3:0] duty,
    output reg  [3:0] high_cnt,
    output reg        out
);
    // clamped duty request, latched only at the period boundary
    wire [3:0] duty_c = (duty_in > 4'd8) ? 4'd8 : duty_in;

    initial count    = 3'd0;
    initial duty     = 4'd4;
    initial high_cnt = 4'd0;
    initial out      = 1'b1;   // 0 < 4

    always @(posedge clk) begin
        if (ce) begin
            if (count == 3'd7) begin
                // end of period: restart, adopt new duty
                count    <= 3'd0;
                duty     <= duty_c;
                high_cnt <= 4'd0;
                out      <= (4'd0 < duty_c);
            end else begin
                count    <= count + 3'd1;
                // accumulate one high cycle whenever the output is asserted
                high_cnt <= high_cnt + (out ? 4'd1 : 4'd0);
                out      <= (({1'b0, count} + 4'd1) < duty);
            end
        end
    end

    // P (part 1): while the output is high, every elapsed cycle of this
    // period was a high cycle
    always @(posedge clk)
        if (out) assert (high_cnt == {1'b0, count});

    // P (part 2): once the output has dropped, exactly duty high cycles
    // have been accumulated in this period
    always @(posedge clk)
        if (!out) assert (high_cnt == duty);
endmodule

