module trace_fifo (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire       full,
    output wire       empty
);
    // depth 8 trace queue: 3 address bits + 1 wrap bit per pointer
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];

    integer k;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        for (k = 0; k < 8; k = k + 1)
            mem[k] = 8'h00;
    end

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);
    assign rdata = mem[rptr[2:0]];

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
        end else begin
            if (do_push) begin
                mem[wptr[2:0]] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;

            if (do_push && !do_pop)
                count <= count + 4'd1;
            else if (do_pop && !do_push)
                count <= count - 4'd1;
        end
    end

    // P: two universal pointer/occupancy agreements, checked in every state
    always @(*) begin
        assert (count != 4'd0 || wptr == rptr);
        assert (count != 4'd8 || wptr[2:0] == rptr[2:0]);
    end
endmodule

