module json_watchdog (
    input  wire clk,
    input  wire i_ce,      // parser step enable; low = idle, no state changes
    input  wire kick,      // parser signals progress on the document stream
    output reg  expired,   // watchdog fired: no kick within LIMIT steps
    output reg  halted     // parse session shut down after the strike cap
);
    localparam [3:0] LIMIT = 4'd6;

    // stall counter: steps since the last kick
    reg [3:0] timer;
    // registered "timer is one tick short of LIMIT" marker
    reg       pre;
    // how many times the watchdog has fired during this session
    reg [2:0] strikes;

    reg pv; // past-valid

    initial begin
        timer   = 4'd0;
        pre     = 1'b0;
        expired = 1'b0;
        halted  = 1'b0;
        strikes = 3'd0;
        pv      = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce && !halted) begin
            if (kick) begin
                // parser made progress: rearm the watchdog
                timer   <= 4'd0;
                pre     <= 1'b0;
                expired <= 1'b0;
            end else if (!expired) begin
                if (pre) begin
                    // stall counter reaches the limit: fire, record a strike
                    timer   <= LIMIT;
                    pre     <= 1'b0;
                    expired <= 1'b1;
                    strikes <= strikes + 3'd1;
                    halted  <= ((strikes + 3'd1) == 3'd2);
                end else begin
                    timer <= timer + 4'd1;
                    pre   <= ((timer + 4'd1) == (LIMIT - 4'd1));
                end
            end
            // expired and not kicked: everything frozen until a kick arrives
        end
    end

    // P: the strike counter may only move on the cycle the stall counter moves,
    //    and it never climbs past its cap of two.
    always @(posedge clk)
        if (pv && $stable(timer))
            assert ($stable(strikes) && strikes <= 3'd2);

endmodule

