module gray_profile_bucket (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [3:0] o_gray,
    output wire       o_hi_bucket,
    output wire       o_lo_bucket,
    output wire       o_armed
);
