// Sliding-window grant rate limiter for an accelerator DMA port.
// A shift register of the last 8 cycles of grants, plus a running
// count of the ones in that window used to throttle new requests.
module dma_rate_limiter (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // idle condition: low leaves all state unchanged
    input  wire i_req,
    output wire o_grant
);
    localparam [3:0] MAXG = 4'd3;   // at most 3 grants per 8-cycle window

    reg [7:0] win;    // recent grant history, win[7] is the oldest entry
    reg [3:0] ones;   // mirrors the number of ones in win
    reg       armed;  // sticky: set the first time a grant is issued

    initial begin
        win   = 8'd0;
        ones  = 4'd0;
        armed = 1'b0;
    end

    wire grant = i_ce && i_req && (ones < MAXG);
    assign o_grant = grant;

    wire [3:0] inc = grant  ? 4'd1 : 4'd0;
    wire [3:0] dec = win[7] ? 4'd1 : 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            win   <= 8'd0;
            ones  <= 4'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            win  <= {win[6:0], grant};
            ones <= ones + inc - dec;
            if (grant)
                armed <= 1'b1;
        end
    end

    // Two status conditions exported to the scheduler
    wire sat       = (ones == MAXG);   // window quota exhausted
    wire win_empty = (win == 8'd0);    // no grants anywhere in the window

    // Absence: once the port has issued its first grant, the limiter can
    // never report a saturated quota and an empty window at the same time.
    assert property (!armed || !(sat && win_empty));

endmodule

