module dma_slice_parity (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] word_in,
    output reg        done
);
    // words remaining in the block transfer
    reg [3:0] count;
    // register slice protected by a parity bit
    reg [7:0] data;
    reg       par;
    // shadow slice: the previously transferred word and its parity bit
    reg [7:0] sdata;
    reg       spar;
    // integrity flags, loaded from the slices at the moment they are rotated
    reg       cur_ok;
    reg       shd_ok;

    initial begin
        count  = 4'd8;
        data   = 8'h00;
        par    = 1'b0;
        sdata  = 8'h00;
        spar   = 1'b0;
        cur_ok = 1'b1;
        shd_ok = 1'b1;
        done   = 1'b0;
    end

    wire xfer = ce && (count != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            count  <= 4'd8;
            data   <= 8'h00;
            par    <= 1'b0;
            sdata  <= 8'h00;
            spar   <= 1'b0;
            cur_ok <= 1'b1;
            shd_ok <= 1'b1;
            done   <= 1'b0;
        end else if (xfer) begin
            // check both slices against their parity bits before rotating them
            cur_ok <= (par  == ^data);
            shd_ok <= (spar == ^sdata);
            // rotate: current slice becomes the shadow, new word enters the slice
            sdata  <= data;
            spar   <= par;
            data   <= word_in;
            par    <= ^word_in;
            count  <= count - 4'd1;
            done   <= (count == 4'd1);
        end
    end

    // P1: once any word has moved through the slice, the word that was there
    //     earlier must have been parity-clean when it was displaced
    always @(posedge clk)
        if (count != 4'd8)
            assert (cur_ok);

    // P2: likewise for the shadow copy of the earlier word
    always @(posedge clk)
        if (count != 4'd8)
            assert (shd_ok);
endmodule

