            sp  <= sp - 4'd1;          // mark never falls back
        end else if (push && !full) begin
            sp  <= sp_next;
            if (sp_next > hwm)
                hwm <= sp_next;        // mark only ratchets upward
        end
    end

    // P, part 1: occupancy never exceeds 10 though 4 bits allow 15
    always @(posedge clk)
        assert (sp <= LIMIT);

    // P, part 2: the high-water mark never exceeds 10 either
    always @(posedge clk)
        assert (hwm <= LIMIT);
