module dma_burst_engine (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [3:0]  i_len,
    input  wire [27:0] i_addr,
    output wire        o_busy,
    output wire        o_last,
    output wire [27:0] o_addr,
    output wire [3:0]  o_sent
);

    // ---- burst engine state -------------------------------------------
    reg        busy       = 1'b0;   // up exactly while beats remain
    reg [3:0]  beats      = 4'd0;   // beats remaining in current burst
    reg [3:0]  words_sent = 4'd0;   // beats already issued this burst
    reg [3:0]  len_reg    = 4'd0;   // latched burst length
    reg [27:0] addr       = 28'd0;  // running beat address

    wire start_ok = start && (i_len != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy       <= 1'b0;
            beats      <= 4'd0;
            words_sent <= 4'd0;
            len_reg    <= 4'd0;
            addr       <= 28'd0;
        end else if (ce) begin
            if (busy) begin
                // issue one beat
                beats      <= beats - 4'd1;
                words_sent <= words_sent + 4'd1;
                addr       <= addr + 28'd4;
                if (beats == 4'd1)
                    busy <= 1'b0;
            end else if (start_ok) begin
                // accept a new burst descriptor
                busy       <= 1'b1;
                beats      <= i_len;
                words_sent <= 4'd0;
                len_reg    <= i_len;
                addr       <= i_addr;
            end
        end
        // ce low: engine stalls, every register holds its value
    end

    assign o_busy = busy;
    assign o_last = busy && (beats == 4'd1);
    assign o_addr = addr;
    assign o_sent = words_sent;

    // ---- property: while the engine is busy it has strictly fewer beats
    // ---- issued than the latched burst length -------------------------
    always @(posedge clk)
        if (busy)
            assert (words_sent < len_reg);

endmodule

