// Gray-coded write pointer crossing into a second clock domain through a
// two-flop synchronizer, with a shadow register that records the first
// nonzero sample observed on the first synchronizer stage.
module gray_cdc_first_sample (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    output wire [3:0] sync_ptr
);
    reg [3:0] wbin;         // binary write pointer (saturating)
    reg [3:0] wgray;        // gray-coded write pointer
    reg [3:0] s1, s2;       // two-flop synchronizer stages
    reg       sh_valid;     // shadow: a nonzero stage-1 sample was seen
    reg [3:0] sh_val;       // shadow: value of that first nonzero sample
    reg       before_first; // scope: high until s2 has ever been nonzero
    reg       pv;           // past-valid

    initial begin
        wbin         = 4'd0;
        wgray        = 4'b0000;
        s1           = 4'b0000;
        s2           = 4'b0000;
        sh_valid     = 1'b0;
        sh_val       = 4'b0000;
        before_first = 1'b1;
        pv           = 1'b0;
    end

    wire [3:0] wbin_nxt = (wbin == 4'hF) ? wbin : (wbin + 4'd1);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            wbin  <= wbin_nxt;
            wgray <= wbin_nxt ^ (wbin_nxt >> 1);
            s1    <= wgray;
            s2    <= s1;
            if (!sh_valid && (s1 != 4'b0000)) begin
                sh_valid <= 1'b1;
                sh_val   <= s1;
            end
            before_first <= before_first && (s2 == 4'b0000);
        end
    end

    assign sync_ptr = s2;

    wire s2_nz = (s2 != 4'b0000);

    // Precedence, in the scope before the pointer has ever been seen on the
    // far side: when the synchronized pointer first becomes nonzero, that
    // very value must already have been recorded in the shadow register.
    always @(posedge clk)
        if (pv && before_first && $rose(s2_nz))
            assert (sh_valid && (sh_val == s2));
endmodule

