module arb_lock_green (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,
    input  wire req_a,
    input  wire req_b,
    input  wire rel,
    output wire grant_a,
    output wire grant_b,
    output wire all_red
);
    // Green phase length limit: a locked winner keeps the road for at most
    // GMAX ticks, then must hand over through an all-red interval.
    localparam [3:0] GMAX = 4'd9;

    reg       lock;   // freezes the current winner until it releases
    reg       owner;  // 0 = road A, 1 = road B
    reg [3:0] gcnt;   // green-phase tick counter
    reg [1:0] ar;     // all-red interval countdown

    initial lock  = 1'b0;
    initial owner = 1'b0;
    initial gcnt  = 4'd0;
    initial ar    = 2'd0;

    wire any_req = req_a | req_b;

    always @(posedge clk) begin
        if (rst) begin
            lock  <= 1'b0;
            owner <= 1'b0;
            gcnt  <= 4'd0;
            ar    <= 2'd0;
        end else if (i_ce) begin
            if (lock) begin
                // locked winner runs its green phase
                if (rel || gcnt == GMAX) begin
                    lock <= 1'b0;
                    gcnt <= 4'd0;
                    ar   <= 2'd2;   // enter all-red handover
                end else begin
                    gcnt <= gcnt + 4'd1;
                end
            end else if (ar != 2'd0) begin
                ar <= ar - 2'd1;
            end else if (any_req) begin
                // fixed priority: road A beats road B
                lock  <= 1'b1;
                owner <= ~req_a;
            end
        end
    end

    assign grant_a = lock && (owner == 1'b0);
    assign grant_b = lock && (owner == 1'b1);
    assign all_red = !lock;

    // P: while a road holds the locked green, its phase timer never exceeds
    // GMAX = 9, even though the register could hold up to 15.
    always @(posedge clk)
        if (lock)
            assert (gcnt <= GMAX);
endmodule

