module credit_pool (
    input  wire clk,
    input  wire cfg,      // one-shot: install the configured credit total
    input  wire send,     // producer spends a credit
    input  wire ret,      // consumer returns a credit
    output wire ok_to_send,
    output wire [3:0] o_credits,
    output wire [3:0] o_outstanding
);
    parameter [3:0] TOTAL = 4'd8;

    // sticky arm register: set the first time the pool is configured, never cleared
    reg       armed = 1'b0;
    // credits held by the producer
    reg [3:0] credits = 4'd0;
    // credits spent and not yet returned
    reg [3:0] outstanding = 4'd0;

    wire do_cfg  = cfg && !armed;
    wire do_send = armed && send && (credits != 4'd0);
    wire do_ret  = armed && ret  && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (do_cfg) begin
            armed       <= 1'b1;
            credits     <= TOTAL;
            outstanding <= 4'd0;
        end else begin
            credits     <= credits     - {3'b000, do_send} + {3'b000, do_ret};
            outstanding <= outstanding + {3'b000, do_send} - {3'b000, do_ret};
        end
    end

    assign ok_to_send    = armed && (credits != 4'd0);
    assign o_credits     = credits;
    assign o_outstanding = outstanding;

    // P: once the pool has been armed, an idle link (nothing outstanding)
    // means every credit is back in the producer's hands.
    always @(posedge clk)
        if (armed && (outstanding == 4'd0))
            assert (credits == TOTAL);
endmodule

