module strsearch_match_queue (
    input  wire       clk,
    input  wire       ce,        // global enable / idle when low
    input  wire       start,     // opens the search window (Q)
    input  wire       finish,    // closes the search window (R)
    input  wire       load,      // report a fresh batch of character matches
    input  wire [7:0] load_mask, // positions in the string that matched
    input  wire       pop,       // consume the currently encoded position
    output reg        busy,      // window register
    output reg        idx_valid, // registered valid flag of the priority encoder
    output reg  [2:0] idx        // encoded position, meaningful only while valid
);

