module dma_burst_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // global enable / idle condition
    input  wire       start,
    input  wire [3:0] len,
    output wire       beat_stb,
    output wire       busy_o,
    output wire [3:0] done_o
);
    // burst engine state
    reg        busy       = 1'b0;  // up exactly while beats remain
    reg [3:0]  beats      = 4'd0;  // beats remaining in current burst
    reg [3:0]  beats_done = 4'd0;  // beats already transferred
    reg [3:0]  shadow_len = 4'd0;  // shadow of the length programmed at start

    assign beat_stb = ce && busy;
    assign busy_o   = busy;
    assign done_o   = beats_done;

    always @(posedge clk) begin
        if (rst) begin
            busy       <= 1'b0;
            beats      <= 4'd0;
            beats_done <= 4'd0;
            shadow_len <= 4'd0;
        end else if (ce) begin
            if (busy) begin
                beats      <= beats - 4'd1;
                beats_done <= beats_done + 4'd1;
                busy       <= (beats != 4'd1);
            end else if (start && (len != 4'd0)) begin
                busy       <= 1'b1;
                beats      <= len;
                shadow_len <= len;   // record the earlier programming event
                beats_done <= 4'd0;
            end
        end
    end

    // P (two assertions, both about the shadow of the earlier start):
    // while a beat can still be observed, strictly fewer beats have been done
    // than were programmed earlier; and once idle, exactly the programmed
    // number of beats has been done.
    always @(posedge clk)
        assert (!busy || (beats_done < shadow_len));

    always @(posedge clk)
        assert (busy || (beats_done == shadow_len));
