module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       issue,
    output wire       done,
    output wire [2:0] occupancy
);
    // fixed-latency (4 stage) in-flight shift register
    reg [3:0] pipe       = 4'b0000;
    // occupancy counter: issue increments, stage-3 drain decrements
    reg [2:0] occ        = 3'd0;
    // shadow register: records that an issue has already happened
    reg       seen_issue = 1'b0;
    reg       pv         = 1'b0;

    assign done      = ce && pipe[3];
    assign occupancy = occ;

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 4'b0000;
            occ        <= 3'd0;
            seen_issue <= 1'b0;
        end else if (ce) begin
            pipe <= {pipe[2:0], issue};
            occ  <= occ + (issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
            if (issue)
                seen_issue <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: a retire observed last cycle must have been preceded by an issue
    always @(posedge clk)
        if (pv)
            assert (!($past(ce) && $past(pipe[3])) || $past(seen_issue));
endmodule

