module fifo_burst_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] wdata,
    output wire       full,
    output wire       empty,
    output reg  [7:0] rdata
);
    // ---------------- state ----------------
    reg [2:0] wptr  = 3'd0;   // write pointer
    reg [2:0] rptr  = 3'd0;   // read pointer
    reg [3:0] count = 4'd0;   // occupancy
    reg       armed = 1'b0;   // window: set when the FIFO fills, cleared when it drains
    reg [7:0] mem [0:7];

    initial rdata = 8'h00;

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    wire [3:0] nxt_count = count + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 4'd0;
            armed <= 1'b0;
            rdata <= 8'h00;
        end else begin
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr      <= wptr + 3'd1;
            end
            if (do_pop) begin
                rdata <= mem[rptr];
                rptr  <= rptr + 3'd1;
            end
            count <= nxt_count;
            // window register: opened by a full condition, closed by a drain to empty
            if (nxt_count == 4'd0)
                armed <= 1'b0;
            else if (nxt_count == 4'd8)
                armed <= 1'b1;
        end
    end

    // ---------------- properties ----------------
    // Inside the burst window (armed), the pointers must agree with the occupancy.
    always @(posedge clk) begin
        if (armed && count == 4'd1)
            assert (wptr == ((rptr + 3'd1) & 3'd7));
        if (armed && count == 4'd8)
            assert (wptr == rptr);
    end
endmodule

