    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;
    initial grace   = 2'd0;

    always @(posedge clk) begin
        if (i_ce) begin
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    grace   <= 2'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt < WARN) begin
                    // pre-warning part of the interval is held in cnt
                    cnt     <= cnt + 4'd1;
                    safe    <= ((cnt + 4'd1) < WARN);
                end else if (grace < GRACE) begin
