            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
