        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
if (fill_main && !drain_main)
                occ <= occ + 2'd1;
else if (drain_main && !fill_main)
                occ <= occ - 2'd1;
        end
    end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
