    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
   initial stg     = 2'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;

   // total window occupancy: committed entries plus staged entries
   wire [4:0] occ = {1'b0, out_r} + {3'b0, stg};
   wire acc_iss = i_ce && i_issue  && (occ < {1'b0, WINDOW});
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);
   // one staged entry is absorbed into the window counter per enabled cycle
   wire cmt = i_ce && (stg != 2'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
           stg   <= 2'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
           if (cmt && !acc_ret)
               out_r <= out_r + 4'd1;
           else if (!cmt && acc_ret)
               out_r <= out_r - 4'd1;
           if (acc_iss && !cmt)
               stg <= stg + 2'd1;
           else if (!acc_iss && cmt)
               stg <= stg - 2'd1;
        end

