    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

