        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
