// back from the pipe tail to the issue-side credit counter
reg       rq0;
reg       rq1;
reg       rq2;
reg       rq3;
// returned credits wait here until the credit counter's write port is free
reg [2:0] rtn;

initial pipe     = 6'b000000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial cred     = 3'd4;
initial lim      = 3'd4;
initial thr      = 1'b0;
initial rq0      = 1'b0;
initial rq1      = 1'b0;
initial rq2      = 1'b0;
initial rq3      = 1'b0;
initial rtn      = 3'd0;

wire retire  = pipe[5];
// credit gate on the issue path
wire accept  = issue && (cred != 3'd0);
// nothing still travelling back down the credit-return path
wire rq_empty = !(rq0 || rq1 || rq2 || rq3);
// at most one parked credit is merged back per cycle, and only on cycles
// where the issue side is not already updating the credit counter
wire drain = (rtn != 3'd0) && !accept;
// true quiesce: pipe drained, returns landed, nothing arriving this cycle
wire quiesce = (pipe == 6'b000000) && rq_empty && !issue;

    always @(posedge clk) begin
        if (rst) begin
pipe     <= 6'b000000;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
        end
    end
