  initial owner = 1'b0;
  initial icnt  = 4'd0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
   wire adv       = ce && active && !owner && (startb || datab); // count only the ticks this engine owns
    wire done      = ce && stopb  && take;
