    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
