    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
   // retires are committed to `ret` in groups of four; `ret_p` holds the
   // retires of the group that has not been folded in yet
   reg [1:0] ret_p;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

   // the issue count feeds the status comparator through four retiming
   // registers; the raw counter is too far from the compare logic to make
   // timing in one cycle, so the compare now sees a 4-cycle-old copy
   reg [4:0] iss_d1;
   reg [4:0] iss_d2;
   reg [4:0] iss_d3;
   reg [4:0] iss_d4;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
   initial ret_p   = 2'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
   initial iss_d1  = 5'd0;
   initial iss_d2  = 5'd0;
   initial iss_d3  = 5'd0;
   initial iss_d4  = 5'd0;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);
   // closing the monitoring window forces a partial group to commit so the
   // retire count is exact at the window boundary
   wire ret_flush = i_ce && i_close;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
           ret_p <= 2'd0;
            out_r <= 4'd0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
           if (ret_flush) begin
               ret   <= ret + {3'b0, ret_p} + (acc_ret ? 5'd1 : 5'd0);
               ret_p <= 2'd0;
           end else if (acc_ret) begin
               if (ret_p == 2'd3) begin
                   ret   <= ret + 5'd4;
                   ret_p <= 2'd0;
               end else begin
                   ret_p <= ret_p + 2'd1;
               end
           end
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
           iss_d1  <= 5'd0;
           iss_d2  <= 5'd0;
           iss_d3  <= 5'd0;
           iss_d4  <= 5'd0;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
           empty_q <= (iss_d4 == ret);
           iss_d1  <= iss;
           iss_d2  <= iss_d1;
           iss_d3  <= iss_d2;
           iss_d4  <= iss_d3;
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

