  // self-terminates one cycle after the data phase
  always @(posedge clk) begin
      if (rst)
          txph <= 2'b00;
      else if (step && !b_busy) begin
          if (tx_start)
              txph <= 2'b01;
          else
              txph <= {txph[0], 1'b0};
