            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
               steps <= steps + 3'd1;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       steps   <= steps + 3'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                       steps     <= steps + 3'd1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
                       steps <= steps + 3'd1;
