module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

   // Margin monitor: low-water mark of the grace window since the
   // watchdog was last armed.  Zero means the window has fully closed.
   reg [3:0] slack;

   // Update stage: the tick arithmetic is registered for one cycle before
   // it commits, so an update issued on a ce cycle lands on the cycle
   // after it was issued.
   reg [3:0] cnt_stg;
   reg [3:0] rem_stg;
   reg       stg_vld;

   // Forwarding: a pending stage value is newer than the committed
   // register, so back-to-back ticks are computed from the stage.
   wire [3:0] cnt_eff = stg_vld ? cnt_stg : cnt;
   wire [3:0] rem_eff = stg_vld ? rem_stg : rem;

  // A kick arriving after the window has already closed is ignored: the
  // reset request stands until software acknowledges it.
  wire kick_ok = i_kick && (slack != 4'd0);

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;
   initial cnt_stg = 4'd0;
   initial rem_stg = TIMEOUT;
   initial stg_vld = 1'b0;
  initial slack   = TIMEOUT;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
           cnt_stg <= 4'd0;
           rem_stg <= TIMEOUT;
           stg_vld <= 1'b0;
          slack   <= TIMEOUT;
       end else begin
           // Drain the stage: the in-flight update commits one cycle after
           // it was issued, whether or not a new tick arrives.
           if (stg_vld) begin
               cnt <= cnt_stg;
               rem <= rem_stg;
              slack <= (rem_stg == TIMEOUT) ? TIMEOUT :
                       (rem_stg < slack)    ? rem_stg : slack;
           end
           stg_vld <= 1'b0;

           if (i_ce) begin
           stg_vld <= 1'b1;
          if (kick_ok) begin
               cnt_stg <= 4'd0;
               rem_stg <= TIMEOUT;
           end else begin
               cnt_stg <= (cnt_eff < TIMEOUT) ? cnt_eff + 4'd1 : cnt_eff;
               rem_stg <= (rem_eff != 4'd0) ? rem_eff - 4'd1 : rem_eff;
           end

           if (i_ack) begin
               latched <= 1'b0;
               // The acknowledge also re-arms the window, issued through
               // the same stage so the commit stays single-sourced.
               cnt_stg <= 4'd0;
               rem_stg <= TIMEOUT;
           end
          else if (!kick_ok && (rem_eff == 4'd1))
                latched <= 1'b1;
        end
       end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);

   // Margin report consistency: the ticks already burned plus the deepest
   // margin the monitor has recorded cannot exceed the whole window.
   always @(posedge i_clk)
       assert ((cnt + slack) <= 5'd12);
endmodule

