            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid_word;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid      <= i_data[3:0];
                if (i_data[7:4] != 4'h0) begin
                    skid_hi   <= i_data[7:4];
                    skid_wide <= 1'b1;
                end else begin
                    skid_wide <= 1'b0;
                end
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

