                if (win) begin
                    acc_data <= acc_data ^ skid_word;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid_word;
                    acc_par  <= skid_par;
                end
            end
if (i_ce) begin
    o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

endmodule

