// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

   // ---------------- stage 2 grant accounting --------------------------
   // Per-band grant counters plus a counter of cycles in which any band
   // reported energy.  Firmware samples their low bits on the index bus
   // while the pipe is idle (o_idx carries no index when o_vld is low).
   reg [3:0] cnt_lo;
   reg [3:0] cnt_hi;
   reg [3:0] cnt_tot;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
       cnt_lo     = 4'd0;
       cnt_hi     = 4'd0;
       cnt_tot    = 4'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
            s1_vld    <= req_lo | req_hi;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
