        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
         if (tick3) begin
             cnt3 <= nxt3;
             g3   <= nxt_gray3;
         end
          if (swap)
             own <= {own[1:0], own[2]};
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
