   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
