module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
output wire o_mon,
output reg [3:0] o_act
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
   // retires are committed to `ret` in groups of four; `ret_p` holds the
   // retires of the group that has not been folded in yet
   reg [1:0] ret_p;
    reg [3:0] out_r;

   // speculative class: a second scoreboard of the same shape that shares the
   // WINDOW budget and the issue/retire port with the primary class. Issues
   // are steered round-robin between the two classes; retires drain the
   // speculative class first so primary entries stay ordered behind them.
   reg [4:0] sec_iss;
   reg [4:0] sec_ret;
   reg [3:0] out_s;
   reg       rr;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

   // the issue count feeds the status comparator through four retiming
   // registers; the raw counter is too far from the compare logic to make
   // timing in one cycle, so the compare now sees a 4-cycle-old copy
   reg [4:0] iss_d1;
   reg [4:0] iss_d2;
   reg [4:0] iss_d3;
   reg [4:0] iss_d4;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
   initial ret_p   = 2'd0;
    initial out_r   = 4'd0;
   initial sec_iss = 5'd0;
   initial sec_ret = 5'd0;
   initial out_s   = 4'd0;
   initial rr      = 1'b0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
   initial iss_d1  = 5'd0;
   initial iss_d2  = 5'd0;
   initial iss_d3  = 5'd0;
   initial iss_d4  = 5'd0;
    initial mon     = 1'b0;
    initial pv      = 1'b0;
initial o_act   = 4'd0;

   // the window budget is shared by both classes
   wire [4:0] occ  = {1'b0, out_r} + {1'b0, out_s};
   wire       room = (occ < {1'b0, WINDOW});
   wire iss_any   = i_ce && i_issue && room;
   wire acc_iss   = iss_any && !rr;
   wire acc_iss_s = iss_any &&  rr;
   wire acc_ret_s = i_ce && i_retire && (out_s != 4'd0);
   wire acc_ret   = i_ce && i_retire && (out_s == 4'd0) && (out_r != 4'd0);
   // closing the monitoring window forces a partial group to commit so the
   // retire count is exact at the window boundary
   wire ret_flush = i_ce && i_close;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
           ret_p <= 2'd0;
            out_r <= 4'd0;
           sec_iss <= 5'd0;
           sec_ret <= 5'd0;
           out_s   <= 4'd0;
           rr      <= 1'b0;
o_act <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
           if (acc_iss_s) sec_iss <= sec_iss + 5'd1;
           if (acc_ret_s) sec_ret <= sec_ret + 5'd1;
           if (iss_any)   rr <= ~rr;
           if (ret_flush) begin
               ret   <= ret + {3'b0, ret_p} + (acc_ret ? 5'd1 : 5'd0);
               ret_p <= 2'd0;
           end else if (acc_ret) begin
               if (ret_p == 2'd3) begin
                   ret   <= ret + 5'd4;
                   ret_p <= 2'd0;
               end else begin
                   ret_p <= ret_p + 2'd1;
               end
           end
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
           if (acc_iss_s && !acc_ret_s)
               out_s <= out_s + 4'd1;
           else if (!acc_iss_s && acc_ret_s)
               out_s <= out_s - 4'd1;
if (i_ce && (i_open || i_close))
    o_act <= o_act + 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
           iss_d1  <= 5'd0;
           iss_d2  <= 5'd0;
           iss_d3  <= 5'd0;
           iss_d4  <= 5'd0;
        end else if (i_ce) begin
           full_q  <= (occ == {1'b0, WINDOW});
           empty_q <= (iss_d4 == ret) && (sec_iss == sec_ret);
           iss_d1  <= iss;
           iss_d2  <= iss_d1;
           iss_d3  <= iss_d2;
           iss_d4  <= iss_d3;
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

