module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag
   reg [4:0]  pend;    // retire credits posted but not yet counted
  reg [4:0]  stg;     // staging slot: this word's credit, before merge
  // Credit ledger for occupancy audit: every post and every release is
  // logged.  Free-running, wraps at 5 bits; the queue depth reported to the
  // saturation accounting is the difference of the two logs.
  reg [4:0]  n_post;  // credits posted  (enqueue side of the ledger)
  reg [4:0]  n_rel;   // credits released (dequeue side of the ledger)

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;
   initial pend    = 5'd0;
  initial stg     = 5'd0;
  initial n_post  = 5'd0;
  initial n_rel   = 5'd0;

   // Retirement is credited through a small pending-credit queue: a completed
   // word posts one credit, and the retire counter's write port (shared with
   // word capture) releases one credit on any enabled cycle that is not a
   // word boundary.  Saturation is declared on the total, posted + counted.
  // The credit queue is split across two registers so the post side and the
  // release side never contend for the same write port: a credit posted at a
  // word boundary lands in the staging slot stg, merges into pend on the next
  // enabled non-boundary cycle, and releases are taken from pend only.

    wire word_last = (sh == 5'd31);

  wire [4:0] outstanding  = n_post - n_rel;
  wire [5:0] retire_total = {1'b0, retired} + {1'b0, outstanding};
   wire       credit_enq   = word_last && !done;
   wire       credit_deq   = (pend != 5'd0) && !word_last;
  wire       stg_move    = (stg != 5'd0) && !word_last;

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
           pend    <= 5'd0;
          stg     <= 5'd0;
          n_post  <= 5'd0;
          n_rel   <= 5'd0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
          if (credit_enq)
              stg <= stg + 5'd1;
          else if (stg_move)
              stg <= stg - 5'd1;
          if (stg_move && !credit_deq)
              pend <= pend + 5'd1;
          else if (credit_deq && !stg_move)
              pend <= pend - 5'd1;
           if (credit_deq)
               retired <= retired + 5'd1;
          if (credit_enq)
              n_post <= n_post + 5'd1;
          if (credit_deq)
              n_rel <= n_rel + 5'd1;
           if (credit_enq)
               done <= (retire_total == {1'b0, (MAX_RETIRE - 5'd1)});
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

