   // transaction always fits strictly inside the widest window the
   // arbiter can hand out, and an outstanding grant never carries more
   // credits than that window either.
   always @(posedge clk)
       assert ((last_lat < BUDGET_MAX) && (!gnt_valid || (timer <= BUDGET_MAX)));
endmodule

