        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
       stage_b    = 2'd0;
       start_tok  = 1'b0;
     tok_acq    = 4'd0;
     tok_rel    = 4'd0;
      upd_p0     = 2'd0;
      upd_p1     = 2'd0;
      upd_p2     = 2'd0;
      upd_p3     = 2'd0;
