module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
// up counter and the credit pool stepped by the same enable; the pool is
// split into a reserve tranche and a main balance, and up + pool == 20
    reg [4:0] up;
    reg [4:0] dn;
// reserve tranche of the batch: returning credits are charged here first
reg [3:0] resv;

   // the main-balance subtractor is registered: a debit against dn is
   // computed on one enabled cycle and committed on the next
   reg       dn_v;
   reg [4:0] dn_s;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;
    // ledger counters: one tick per credit handed out, one per credit back
    reg [4:0] n_iss;
    reg [4:0] n_ret;

    initial up          = 5'd0;
initial dn          = 5'd12;
initial resv        = 4'd8;
    initial mark        = 1'b0;
    initial before_done = 1'b1;
    initial n_iss       = 5'd0;
    initial n_ret       = 5'd0;
   initial dn_v        = 1'b0;
   initial dn_s        = 5'd11;

    always @(posedge clk) begin
        if (i_ce) begin
if (dn_v) begin
               // commit the registered debit against the main balance
               dn   <= dn_s;
               dn_v <= 1'b0;
           end else if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
                up          <= 5'd0;   // recharge with a fresh batch of 20
dn          <= 5'd12;
resv        <= 4'd8;   // fresh batch: reserve tranche refilled
                mark        <= 1'b0;   // new batch: halfway not passed yet
            end else if (n_iss == n_ret) begin
                // nothing outstanding: hand a credit to the consumer
                up    <= up + 5'd1;
                mark  <= mark | (up == 5'd9);
                n_iss <= n_iss + 5'd1;
            end else begin
// the outstanding credit returns: charge the reserve tranche first and
// only fall back on the main balance once the tranche is dry
if (resv != 4'd0) begin
                   resv <= resv - 4'd1;
               end else begin
                   // stage the debit; it lands on dn next enabled cycle
                   dn_s <= dn - 5'd1;
                   dn_v <= 1'b1;
               end
                n_ret <= n_ret + 5'd1;
            end
        end
    end

    // gray view of the issue pointer (clock-domain-crossing flavour)
    assign o_gray    = n_iss ^ (n_iss >> 1);
assign o_drained = (dn == 5'd0) && (resv == 4'd0) && (n_iss == n_ret);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

