module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
output wire [3:0] o_rows,
output reg  [3:0] o_ce_beats
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
   reg       fin_pend;
    reg [3:0] rows;
   reg       abort_pend;
   reg [3:0] row_max;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
   initial fin_pend = 1'b0;
    initial rows    = 4'd0;
   initial abort_pend = 1'b0;
   initial row_max    = 4'd4;
initial o_ce_beats = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
           fin_pend <= 1'b0;
            rows    <= 4'd0;
           abort_pend <= 1'b0;
           row_max    <= 4'd4;
o_ce_beats <= 4'd0;
        end else if (i_ce) begin
o_ce_beats <= o_ce_beats + {3'd0, i_start};
           // completion is committed one beat after the FSM posts it
           ready <= fin_pend || abort_pend;
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                       fin_pend <= 1'b1;
                   end else if (rows == row_max) begin
                       // row budget exhausted: truncate this sheet and close out
                       st         <= S_DONE;
                       loading    <= 1'b0;
                       abort_pend <= 1'b1;
                   end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                   fin_pend <= 1'b0;
                   abort_pend <= 1'b0;
                   // adapt the burst budget: grow it when the sheet overran,
                   // shrink it back toward the floor when it fit
                   if (abort_pend) begin
                       if (row_max != 4'd12)
                           row_max <= row_max + 4'd1;
                   end else if (row_max != 4'd4) begin
                       row_max <= row_max - 4'd1;
                   end
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                   fin_pend <= 1'b1;
                  abort_pend <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

