    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack
    reg [3:0] slack;    // remaining scan budget exported to the prefetch stride
    // The timeout flag sits on the report bus, four scan steps downstream of
    // the counter, so a saturation event is registered through this pipe
    // before it is visible to the host.
    reg       exp_s0;   // expiry report, stage 0
    reg       exp_s1;   // expiry report, stage 1
    reg       exp_s2;   // expiry report, stage 2
    reg       exp_s3;   // expiry report, stage 3

