// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

  // The owner tag is not written straight from the launch path: the launch
  // cycle is already busy driving req and bumping the credit ledger, so the
  // selected client is parked in a one-deep staging latch and copied into
  // the ownership bits on the following enabled cycle. Progress out of
  // phase 1 stalls until the staged tag has been committed.
  reg       tag_v;
  reg       tag_sel;

   // Credit ledger: one credit exists for the channel. Every acquire is
   // logged in n_acq, every retire in n_rel; both wrap at four bits. The
   // channel may only be taken when all logged acquires have been retired.
   reg [3:0] n_acq;
   reg [3:0] n_rel;

   wire ledger_free = (n_acq == n_rel);

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;
  initial tag_v   = 1'b0;
  initial tag_sel = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;

    always @(posedge clk) begin
        if (i_ce) begin
           if (ledger_free) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                   n_acq <= n_acq + 4'd1;
                   tag_v   <= 1'b1;
                   tag_sel <= i_sel;
                end
            end else begin
                case (phase)
                   2'd1: if (tag_v) begin
                             // drain the staging latch into the tag bits
                             tag_v <= 1'b0;
                             if (tag_sel)
                                 own_b <= 1'b1;
                             else
                                 own_a <= 1'b1;
                         end else if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                             n_rel  <= n_rel + 4'd1;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

