// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;
// snapshot defer buffer: a bin-1 sample that arrives while the readout
// pipeline is still busy parks its bin-0 reading here and replays it when
// the pipeline frees up, so back-to-back bin-1 samples are not lost
reg [3:0] hold;
reg       hold_v;
// snapshot ledger: requests issued vs. snapshots delivered to the shadow
reg [3:0] n_iss, n_ret;
// posted-write buffer for bin 0: the bin-0 counter shares its single array
// port with the snapshot readout, so bin-0 samples that are committed while
// the port is busy are parked here and written back on a free cycle
reg [1:0] b0_pend;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;
initial hold    = 4'd0;
initial hold_v  = 1'b0;
initial n_iss   = 4'd0;
initial n_ret   = 4'd0;
initial b0_pend = 2'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
wire [3:0] inflight  = n_iss - n_ret;
wire       pipe_free = !(v1 | v2 | v3 | v4);
// the ledger can carry two outstanding snapshots (one in the readout
// pipeline, one in the defer buffer); a bin-1 sample that would overflow it
// is held off at the input until a slot frees up
wire       snap_full = (inflight == 4'd2);
// bin-0 population as seen by the outside world: committed count plus the
// samples still sitting in the posted-write buffer
wire [4:0] b0_pop    = {1'b0, b0} + {3'd0, b0_pend};
wire       bin0_full = (b0_pop == 5'd15) || (b0_pend == 2'd3);
wire incr = i_ce && !((i_bin == 2'd0) ? bin0_full : (sel_val == 4'd15))
                 && !((i_bin == 2'd1) && snap_full);
wire req  = incr && (i_bin == 2'd1);
// the array port is available for a posted bin-0 write-back only on cycles
// where the snapshot logic is not reading the bin-0 population
wire       wb_free = pipe_free && !hold_v && !req;
wire       b0_push = incr && (i_bin == 2'd0);
wire       b0_wb   = i_ce && wb_free && (b0_pend != 2'd0) && (b0 != 4'd15);

    always @(posedge clk) begin
if (b0_wb)
    b0 <= b0 + 4'd1;
if (i_ce)
    b0_pend <= b0_pend + {1'b0, b0_push} - {1'b0, b0_wb};
        if (incr) begin
            case (i_bin)
2'd0: ; // bin-0 sample is posted into b0_pend above
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
          // stage-1 arbitration: a parked request replays ahead of a new
          // one so the shadow register sees bin-1 samples in order
          if (pipe_free && hold_v) begin
              sn1    <= hold;
              v1     <= 1'b1;
              hold_v <= req;
              if (req)
hold <= b0_pop[3:0];
          end else if (pipe_free && req) begin
sn1 <= b0_pop[3:0];
              v1  <= 1'b1;
          end else begin
              v1 <= 1'b0;
              if (req) begin
hold   <= b0_pop[3:0];
                  hold_v <= 1'b1;
              end
          end
          // ledger: one tick per request issued, one per snapshot delivered
          n_iss <= n_iss + {3'd0, req};
          n_ret <= n_ret + {3'd0, v4};
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
// plus a status readout multiplexer: the current bin index selects which
// ledger / defer-buffer register is presented on o_act.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          case (i_bin)
              2'd0: o_act <= n_iss;
              2'd1: o_act <= n_ret;
              2'd2: o_act <= hold;
              2'd3: o_act <= {hold_v, ce_hist[2:0]};
          endcase
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});

   // Property (snapshot ledger conservation): every outstanding snapshot
   // request corresponds to a bin-1 sample that has already been counted,
   // and the bin-0 reading parked in the defer buffer was taken from a
   // population already counted, so together they can never exceed the
   // running sample total.
   always @(posedge clk)
       assert (total >= {2'b00, hold} + {2'b00, inflight});
endmodule

