module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
output wire [2:0] o_count,
output reg [3:0] o_push_tally
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;
   // Skid slot behind the tail.  o_full is raised as soon as the tail fills,
   // but one upstream beat may already be in flight, so it is absorbed here
   // and handed to the tail as soon as a pop frees it.
   reg       s_v;
   reg [7:0] s_d;
  // A second skid slot behind the first, so two beats that were already in
  // flight when full was reported can both be absorbed.  Both slots are
  // accounted for by the shared skid occupancy counter below.
  reg       s2_v;
  reg [7:0] s2_d;
  // occupancy contributed by the skid slot, held apart from the core count
  reg [1:0] skid_occ;
 // the occupancy adder is retimed off the push path: a beat that has just
 // been written into a core slot has its unit of occupancy parked in
 // inc_pend for one cycle and is folded into count on the next edge
 reg       inc_pend;
// the skid-to-core hand-off is retimed the same way: the occupancy that
// leaves the skid counter on a drain is parked here for one cycle before it
// is folded into count
reg [1:0] xfer_pend;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial s_v   = 1'b0;
   initial s_d   = 8'h00;
  initial s2_v  = 1'b0;
  initial s2_d  = 8'h00;
  initial skid_occ = 2'd0;
 initial inc_pend = 1'b0;
initial xfer_pend = 2'd0;
initial o_push_tally = 4'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;
   // a beat arriving while full is taken by the skid slot, unless a pop is
   // freeing the tail this cycle, in which case it goes straight to the tail
   wire do_skid = i_push && w_full && !s_v && !do_pop;
  // with the first slot already parked, the next beat queues behind it
  wire do_skid2 = i_push && w_full && s_v && !s2_v && !do_pop;
  // a beat takes a core slot this cycle; its increment is deferred one edge
  wire core_join  = do_push || (do_pop && !s_v && i_push);
  // the head always vacates on a pop; that decrement is taken immediately
  wire core_leave = do_pop;
// on a drain the skid keeps only the slot that slides forward; the
// difference is the occupancy share migrating towards the core count
wire [1:0] skid_drain = (do_pop && s_v) ? (skid_occ - {1'b0, s2_v}) : 2'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
          s2_v  <= 1'b0;
          s2_d  <= 8'h00;
          skid_occ <= 2'd0;
         inc_pend <= 1'b0;
        xfer_pend <= 2'd0;
o_push_tally <= 4'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
        end else if (do_pop) begin
            // tail slides down into the head slot
           v0 <= v1;
           d0 <= d1;
           if (s_v) begin
               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
              s_v   <= s2_v;
              s_d   <= s2_d;
              s2_v  <= 1'b0;
             // the skid loses one unit of occupancy here; it reaches count
             // one edge later through xfer_pend
             skid_occ <= {1'b0, s2_v};
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
          skid_occ <= skid_occ + 2'd1;
      end else if (do_skid2) begin
          s2_v  <= 1'b1;
          s2_d  <= i_data;
         skid_occ <= skid_occ + 2'd1;
      end
        // i_push = i_pop = 0 : the buffer idles, all state held
       if (!i_rst) begin
          count     <= count + {2'b00, inc_pend} - {2'b00, core_leave} + {1'b0, xfer_pend};
           inc_pend <= core_join;
          xfer_pend <= skid_drain;
       end
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
 assign o_count = count + {1'b0, skid_occ} + {2'b00, inc_pend} + {1'b0, xfer_pend};

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
