module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
output wire       o_settled, // no sample in flight
output reg  [3:0] o_act      // beat-activity tally, observation only
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;
  // read-side pointer of the same ring: one data word takes two destination
  // beats, so it advances on alternate enables.  it shares the programmable
  // ring bound with the write pointer.
  reg [3:0] cnt2;
  reg [3:0] g2;
  reg       ph;
 // completion pointer of the same ring: the consumer retires a word on the
 // opposite half beat, so this one steps when the read phase is low.  it uses
 // the same programmable ring bound as the write and read pointers.
 reg [3:0] cnt3;
 reg [3:0] g3;
 // the crossing lane is a single physical 4-bit bundle, so the three pointers
 // take turns on it under a one-hot grant that rotates.  the turn is handed
 // over only at the common origin, where every encoder reads zero and the
 // lane sees no step on the bundle.
 reg [2:0] own;
reg [3:0] act;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
     cnt3 = 4'd0;
     g3   = 4'd0;
     own  = 3'b001;
act   = 4'd0;
o_act = 4'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);
  wire       wrap2      = (cnt2 >= lim);
  wire [3:0] nxt2       = wrap2 ? 4'd0 : cnt2 + 4'd1;
  wire [3:0] nxt_gray2  = nxt2 ^ (nxt2 >> 1);
  wire       tick2      = ph;
 wire       wrap3      = (cnt3 >= lim);
 wire [3:0] nxt3       = wrap3 ? 4'd0 : cnt3 + 4'd1;
 wire [3:0] nxt_gray3  = nxt3 ^ (nxt3 >> 1);
 wire       tick3      = ~ph;
 wire       swap       = (cnt == 4'd0) && (cnt2 == 4'd0) && (cnt3 == 4'd0);
 // one-hot grant onto the shared bundle: each encoder is masked by its grant
 // bit and the three masked copies are or-ed onto the lane
 wire [3:0] lane       = (own[0] ? g : 4'd0) | (own[1] ? g2 : 4'd0) | (own[2] ? g3 : 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
          gq  <= lane;
           s1  <= gq;
            s2  <= s1;
          ph  <= ~ph;
          if (tick2) begin
              cnt2 <= nxt2;
              g2   <= nxt_gray2;
          end
         if (tick3) begin
             cnt3 <= nxt3;
             g3   <= nxt_gray3;
         end
          if (swap)
             own <= {own[1:0], own[2]};
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
act   <= act + 4'd1;
o_act <= act ^ {3'b000, ph};
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

