module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
   reg [4:0] dec_s; // decode stage register, one pipeline step ahead of dec
    reg       win;   // window register: opened by a job start, closed at retire
   reg       tail;  // retire stage: carries the window over the write-back phase
  reg [2:0] age;   // phase age of the job in flight: 1 at launch, 5 at retire
 reg       rjob;   // the job in flight belongs to the refresh channel
 reg [3:0] rtimer; // refresh interval countdown, one tick per enabled cycle

    initial state = S_IDLE;
    initial dec   = 5'b00001;
   initial dec_s = 5'b00001;
    initial win   = 1'b0;
   initial tail  = 1'b0;
  initial age   = 3'd0;
 initial rjob   = 1'b0;
 initial rtimer = 4'd15;

 // the refresh channel asks for the pipe once its interval has expired
 wire rreq = (rtimer == 4'd0);

    reg [2:0] nstate;
    always @(*) begin
        case (state)
           S_IDLE:   nstate = (i_start || rreq) ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
           S_EXEC:   nstate = rjob ? S_IDLE : S_WRITE;  // refresh has no write-back
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

   // phase code shown on o_phase during the last cycle a job owns the pipe:
   // refresh jobs retire out of EXEC, normal jobs out of WRITE
   wire [4:0] retdec = rjob ? 5'b01000 : 5'b10000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
           dec_s <= 5'b00001;
            win   <= 1'b0;
           tail  <= 1'b0;
          age   <= 3'd0;
           rjob   <= 1'b0;
           rtimer <= 4'd15;
        end else if (i_ce) begin
            state <= nstate;
           dec_s <= ndec;      // decode is registered here ...
           dec   <= dec_s;     // ... and presented on o_phase one cycle later
           if ((state == S_IDLE) && (i_start || rreq))
                win <= 1'b1;               // Q: a job is launched
           else if (tail)             // the retire stage owns the window now
                win <= 1'b0;               // R: the job retires

           // hand the window over once DECODE reaches o_phase, so the retire
           // stage covers the final write-back cycle on its own
           if (dec == 5'b00100)
               tail <= 1'b1;
          else if (dec == retdec)
               tail <= 1'b0;

          // age the job one phase per enabled cycle: the launch cycle seeds
          // the counter and the retiring write-back cycle clears it again
         if ((state == S_IDLE) && (i_start || rreq))
              age <= 3'd1;
         else if (dec == retdec)
              age <= 3'd0;
          else if (win || tail)
              age <= age + 3'd1;

         // the refresh engine is a peer client of the same phase pipeline:
         // an explicit start always wins the idle slot, a due refresh takes
         // whatever idle slot is left over
         if ((state == S_IDLE) && i_start)
             rjob <= 1'b0;
         else if ((state == S_IDLE) && rreq)
             rjob <= 1'b1;
         else if (dec == retdec)
             rjob <= 1'b0;

         // restart the interval only when the refresh channel is granted
         if ((state == S_IDLE) && !i_start && rreq)
             rtimer <= 4'd15;
         else if (rtimer != 4'd0)
             rtimer <= rtimer - 4'd1;
        end
