always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
