// so credits lost to a dropped return can be recovered at a drain point
reg [2:0] n_iss;
reg [2:0] n_ret;
// return staging: a slot freed by writeback waits here until the pool's
// single write port is free (an advance that takes no issue) to rejoin credit
reg [2:0] rtn;

initial pipe  = 3'b000;
    initial occ   = 3'd0;
    initial armed = 1'b0;
initial wb    = 1'b0;
initial beat  = 1'b0;
initial credit = 3'd4;
initial n_iss = 3'd0;
initial n_ret = 3'd0;
initial rtn   = 3'd0;
wire adv = i_ce && !beat;
// an issue is only taken when the unit still has a free slot
wire acc = issue && (credit != 3'd0);
// ledger view of the unit: nothing issued is still outstanding
wire drained = (n_iss == n_ret);
// an accepted issue owns the credit write port; returns fold back behind it
wire fold = (rtn != 3'd0) && !acc;

assign o_retire = adv && wb;
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
pipe  <= 3'b000;
            occ   <= 3'd0;
            armed <= 1'b0;
wb    <= 1'b0;
beat  <= 1'b0;
credit <= 3'd4;
n_iss <= 3'd0;
n_ret <= 3'd0;
rtn   <= 3'd0;
end else begin
if (adv) begin
pipe <= {pipe[1:0], acc};
wb   <= pipe[2];
occ    <= occ    + (acc ? 3'd1 : 3'd0) - (wb ? 3'd1 : 3'd0);
