module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist
);
    // Latency budget granted to an accepted request.
localparam [2:0] BUDGET_MAX = 3'd5;
localparam [2:0] BUDGET_MIN = 3'd3;

// Adaptive latency allowance. A slave that times out earns one extra
// credit for the next requester; a slave that answers within a cycle
// gives one back. Only rewritten in the gap between grants.
reg [2:0] budget;
// Latency of the most recently completed transaction, in cycles. Feeds
// the budget hysteresis below: the window is only narrowed after two
// quick responses in a row, so a single lucky slave cannot starve the
// next requester.
reg [2:0] last_lat;
// Contention ceiling. Under sustained backpressure (four consecutive
// cycles with an unserved request) the arbiter advertises a tighter
// maximum window so the request queue can drain; once the history
// clears it relaxes the ceiling again, one credit per idle cycle.
reg [2:0] cap;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
wire retire = gnt_valid && (done || ((elapsed == (budget - 3'd1)) && (timer == 3'd1)));

   // Next advertised window, and the allowance actually handed out once
   // the running budget has been clamped into that window.
   wire [2:0] cap_next = (req_hist == 4'b1111) ? ((cap == BUDGET_MIN) ? BUDGET_MIN : cap - 3'd1) :
                         (req_hist == 4'b0000) ? ((cap == BUDGET_MAX) ? BUDGET_MAX : cap + 3'd1) :
                                                 cap;
   wire [2:0] alloc    = (budget > cap_next) ? cap_next : budget;

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial budget    = BUDGET_MAX;
initial last_lat  = 3'd0;
initial cap       = BUDGET_MAX;
initial req_hist  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
budget    <= BUDGET_MAX;
last_lat  <= 3'd0;
cap       <= BUDGET_MAX;
req_hist  <= 4'd0;
