        if (rst) begin
            stall    <= 1'b0;
            skid      <= 4'h0;
            skid_hi   <= 4'h0;
            skid_wide <= 1'b0;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
pend_lo     <= 4'h0;
pend_hi     <= 4'h0;
pend_wide   <= 1'b0;
pend_par    <= 1'b0;
pend_par_hi <= 1'b0;
o_beat_count <= 4'd0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid_word;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid      <= i_data[3:0];
                if (i_data[7:4] != 4'h0) begin
                    skid_hi   <= i_data[7:4];
                    skid_wide <= 1'b1;
                end else begin
                    skid_wide <= 1'b0;
                end
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid_word;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid_word;
                    acc_par  <= skid_par;
                end
            end

          // pending tracker: a capture folds straight in through a four bit
          // datapath, so the upper nibble sits in its own slot and is only
          // clocked while the residue stays wide; a window close re-primes the
          // tracker with whatever word is still sitting in the skid slot
          if (i_ce && i_close) begin
              if (do_capture) begin
                  pend_lo   <= i_data[3:0];
                  pend_par  <= ^i_data;
                  if (i_data[7:4] != 4'h0) begin
                      pend_hi     <= i_data[7:4];
                      pend_par_hi <= ^i_data[7:4];
                      pend_wide   <= 1'b1;
                  end else begin
                      pend_wide   <= 1'b0;
                  end
              end else if (stall && !do_release) begin
                  pend_lo     <= skid;
                  pend_par    <= skid_par;
                  pend_hi     <= skid_hi;
                  pend_par_hi <= ^skid_hi;
                  pend_wide   <= skid_wide;
              end else begin
                  pend_lo   <= 4'h0;
                  pend_par  <= 1'b0;
                  pend_wide <= 1'b0;
              end
          end else if (do_capture) begin
              pend_lo <= pend_lo ^ i_data[3:0];
              if (i_data[7:4] != 4'h0) begin
                  if (pend_hi_nxt != 4'h0) begin
                      pend_hi     <= pend_hi_nxt;
                      pend_par_hi <= pend_ph_cur ^ (^i_data[7:4]);
                      pend_wide   <= 1'b1;
                      pend_par    <= pend_par ^ (^i_data);
                  end else begin
                      // upper nibble cancels out: retract its tracked parity
                      // instead of re-folding the whole byte
                      pend_wide <= 1'b0;
                      pend_par  <= pend_par ^ pend_par_hi ^ (^i_data[3:0]);
                  end
              end else begin
                  pend_par <= pend_par ^ (^i_data[3:0]);
              end
          end
if (i_ce) begin
   if (i_close && win)
       o_beat_count <= {3'd0, pend_par};   // close restarts the count, flagging leftover residue
   else
       o_beat_count <= o_beat_count + 4'd1;
end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

   // ---- property: inside the window, the residue still owed to the accumulator
   //      (pending tracker xor accumulator) carries a correct shadow parity ----
   always @(posedge clk) begin
       if (win) begin
           assert ((pend_par ^ acc_par) == (^(pend_data ^ acc_data)));
       end
   end

endmodule

