module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
output wire       o_drained,
output reg  [3:0] o_ack_cnt
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    // commit-stage register: the next beat count is held here for one cycle
    // before it is written into the beats-remaining counter
    reg [3:0] stg_beats;
    reg       stg_vld;

   // unpipelined shadow of the beats-remaining count: the issue stage keeps
   // its own copy so downstream flow control does not have to wait a cycle
   // for the commit stage to update beats_left
   reg [3:0] shadow;

  // registered copy of the ack input (status only)
   reg       ack_seen;

  // window ledger: one counter logs every transfer window that opens, the
  // other logs every window that closes.  The pair is exported as the
  // status word so a host can audit descriptor/ack pairing; both wrap.
  reg [1:0] n_win_opn;
  reg [1:0] n_win_cls;

  // window events, shared by the window register and the ledger
  wire win_set = i_start && !busy;
  wire win_clr = !win_set && i_ack;

  // the ledger's view of whether a transfer window is outstanding
  wire ledger_open = (n_win_opn != n_win_cls);

    // forwarded count: the in-flight value whenever a commit is pending
    wire [3:0] beats_cur = stg_vld ? stg_beats : beats_left;


    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;
    initial stg_beats  = 4'd0;
    initial stg_vld    = 1'b0;
   initial shadow     = 4'd0;
   initial ack_seen   = 1'b0;
  initial n_win_opn  = 2'd0;
  initial n_win_cls  = 2'd0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
            stg_beats  <= 4'd0;
            stg_vld    <= 1'b0;
           shadow     <= 4'd0;
           ack_seen   <= 1'b0;
          n_win_opn  <= 2'd0;
          n_win_cls  <= 2'd0;
        end else if (i_ce) begin
            // commit stage: the registered count reaches the counter
            if (stg_vld) begin
                beats_left <= stg_beats;
                stg_vld    <= 1'b0;
            end
            // issue stage: a descriptor load or a beat retire posts the new
            // status flags now and hands the count to the commit stage
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                stg_beats  <= i_len;
                stg_vld    <= 1'b1;
               shadow     <= i_len;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
               // retire one beat off the forwarded count.  A window that
               // has already been closed abandons whatever beats are left:
               // the reported status follows the ledger, the beat counts
               // follow the window register the datapath is wired to.
               stg_beats  <= ledger_open ? (beats_cur - 4'd1) : 4'd0;
               stg_vld    <= 1'b1;
               shadow     <= win ? (beats_cur - 4'd1) : 4'd0;
               busy       <= win && (beats_cur != 4'd1);
               drained    <= !ledger_open || (beats_cur <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
          // ledger: log the window opens and closes as they happen
          if (win_set && !win)
              n_win_opn <= n_win_opn + 2'd1;
          if (win_clr && win)
              n_win_cls <= n_win_cls + 2'd1;
           ack_seen <= i_ack;
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

   // status word: the window ledger, opens in the high half, closes in the low
   always @(*)
       o_ack_cnt = {n_win_opn, n_win_cls};

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

   // Q: the engine reports "drained" only once the issue-stage shadow has
   // counted the burst all the way down to zero beats.
   always @(posedge i_clk)
       assert (!drained || (shadow == 4'd0));

endmodule

