       swp_v1  = 1'b0;
       swp_v2  = 1'b0;
       swp_v3  = 1'b0;
       swp_d0  = 1'b0;
       swp_d1  = 1'b0;
       swp_d2  = 1'b0;
       swp_d3  = 1'b0;
