            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
           credit   <= 4'd0;
retired  <= 4'd0;
step_tally <= 4'd0;
job_count <= 4'd0;
