    initial virgin = 1'b1;
  initial tag_v   = 1'b0;
  initial tag_sel = 1'b0;
   initial n_acq  = 4'd0;
   initial n_rel  = 4'd0;
  initial rel_pend = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
           if (ledger_free) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                   n_acq <= n_acq + 4'd1;
                  n_rel    <= n_rel + {3'b0, rel_pend};
                  rel_pend <= 1'b0;
                   tag_v   <= 1'b1;
                   tag_sel <= i_sel;
                end
            end else begin
                case (phase)
                   2'd1: if (tag_v) begin
                             // drain the staging latch into the tag bits
                             tag_v <= 1'b0;
                             if (tag_sel)
                                 own_b <= 1'b1;
                             else
                                 own_a <= 1'b1;
                         end else if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                            rel_pend <= 1'b1;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

