   // round-robin pointer: whose request is charged next
   reg       turn;
   // registered arbiter grant: the shelf port moves one credit per cycle
   reg       gnt_a;
   reg       gnt_b;
   reg       gnt_take;
   // shelf-port move pipeline: a granted credit needs four more cycles on the
   // shared port before the lane counters and the shelf see it
   reg       p1_a;
   reg       p1_b;
   reg       p1_take;
   reg       p2_a;
   reg       p2_b;
   reg       p2_take;
   reg       p3_a;
   reg       p3_b;
   reg       p3_take;
   reg       p4_a;
   reg       p4_b;
   reg       p4_take;

    initial used  = 4'd0;
    initial avail = CAP;
   initial out_a = 4'd0;
   initial out_b = 4'd0;
  initial rsv_a = 2'd0;
 initial rsv_b = 2'd0;
   initial turn  = 1'b0;
   initial gnt_a = 1'b0;
   initial gnt_b = 1'b0;
   initial gnt_take = 1'b0;
   initial p1_a = 1'b0;
   initial p1_b = 1'b0;
   initial p1_take = 1'b0;
   initial p2_a = 1'b0;
   initial p2_b = 1'b0;
   initial p2_take = 1'b0;
   initial p3_a = 1'b0;
   initial p3_b = 1'b0;
   initial p3_take = 1'b0;
