   reg            tgt;     // latched target level of the outstanding change request
   reg [3:0]      n_req;   // ledger: change requests logged (free-running, wraps)
   reg [3:0]      n_ret;   // ledger: change requests retired (free-running, wraps)

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;
   initial stable = 1'b0;
initial pend   = 1'b0;
   initial tgt    = 1'b0;
   initial n_req  = 4'd0;
   initial n_ret  = 4'd0;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
           stable <= 1'b0;
pend   <= i_raw ^ clean;
           // A retime either opens a new request against the committed level or
           // retires the one already logged; the target level is captured on open.
           if (n_req == n_ret) begin
               tgt   <= i_raw;
               n_req <= n_req + 4'd1;
           end else begin
               n_ret <= n_ret + 4'd1;
           end
        end else if (cnt < KC) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
               if (pend) begin
                   clean <= tgt;
                   n_ret <= n_ret + 4'd1;
               end
pend  <= 1'b0;
                armed <= 1'b1;
               stable <= 1'b1;
            end
        end
    end

    assign o_clean   = clean;
    assign o_armed   = armed;
   assign o_settled = stable;

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));

   // While the filter reports settled, the committed level must still match the
   // newest raw sample: any disagreement would mean a missed retime.
   always @(posedge i_clk)
       assert (!stable || (clean == hist[0]));
