module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;
    // start handshake stage: the start pulse is captured here for the
    // descriptor-fetch cycle and is only then logged into h_start
    reg       s_pend  = 1'b0;

   // descriptor status shadow: while a descriptor is in flight the
   // "start beat seen" record is kept here; it is only folded into the
   // chain log when the descriptor actually retires
   reg       sh_start = 1'b0;

  // descriptor ledger: one log entry per descriptor issued to the burst
  // engine and one per descriptor retired.  Both counters free-run and
  // wrap; their difference is the number of descriptors still in flight.
  reg [3:0] n_iss = 4'd0;
  reg [3:0] n_ret = 4'd0;

  wire [3:0] outstanding = n_iss - n_ret;
  // the engine is single-descriptor: at most one may be outstanding, and
  // it must agree with the in-flight status bits of the slice
  wire ledger_bad = (outstanding != {3'd0, (s_pend || sh_start)});

    // slice checker: stored parity must match stored phase
wire slice_bad = (par != (^phase)) || (phase == PH_IDLE && sh_start) || ledger_bad;

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
                    if (i_arm) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        s_pend  <= 1'b1;
n_iss   <= n_iss + 4'd1;
                    end
                PH_BUSY:
                    if (s_pend) begin
                        // first burst cycle fetches the descriptor word,
                       // no payload word moves and the length is untouched;
                       // the start beat lands in the status shadow, not yet
                       // in the chain log
                        s_pend  <= 1'b0;
                       sh_start <= 1'b1;
                    end else if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                       // retire: commit the in-flight status into the chain
                       // log and release the shadow for the next descriptor
                       h_start  <= sh_start;
                       sh_start <= 1'b0;
n_ret    <= n_ret + 4'd1;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

