    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);

   // Lane coherence: the swap is only half done while lane B holds the
   // shared shadow. Once ownership is back with lane A both lanes have
   // been advanced to the same quantum slot, so the two gray words the
   // CDC side can sample are identical.
   always @(posedge clk)
       if (pv) assert (turn || (gray == gray_b));
endmodule

