    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};
// reference adder is built from two nibble slices so neither carry chain
// spans the whole word; the upper slice is only clocked on cycles where it
// can actually change, which keeps it quiet for small operands
wire [4:0] lo_sum     = {1'b0, total} + {1'b0, i_data[3:0]};
wire       lo_cout    = lo_sum[4];
wire [3:0] hi_sum     = tot_hi + i_data[7:4] + {3'b0, lo_cout};
wire       hi_en      = lo_cout || (i_data[7:4] != 4'h0);
wire [7:0] next_total = {hi_sum, lo_sum[3:0]};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
            hi_flag <= 1'b0;
evt_cnt <= 4'h0;
        end else if (i_ce) begin
evt_cnt <= evt_cnt + {3'b0, (i_data != 8'h00)};
            if (i_clear || hi_flag) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
total  <= 4'h0;
tot_hi <= 4'h0;
                hi_flag <= 1'b0;
