       st_v  <= 1'b1;
       st_ch <= 1'b1;
       st_lo <= 4'd1;
       st_hi <= 4'd0;          // B carries a single byte per step
       timer_b <= timer_b - 4'd1;
       arb   <= 1'b0;
   end else begin
       st_v  <= 1'b0;
       st_ch <= 1'b0;
       st_lo <= 4'd0;
       st_hi <= 4'd0;
   end
