module rr_arb_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    input  wire       arm,
    input  wire       clr,
    output reg  [3:0] gnt
);
    // round-robin arbiter state
    reg [1:0] ptr;       // last granted line index
   reg [1:0] hold;      // line the parked grant is sitting on
   reg [3:0] n_iss;     // grants issued  (free-running, wraps)
   reg [3:0] n_ret;     // grants retired (free-running, wraps)
    // precedence shadow of the previous grant decision
    reg [3:0] prev_gnt;
    reg [1:0] prev_ptr;
    reg [3:0] hist;      // lines the pointer has rested on since arming
    reg       armed;     // window register: set by arm, cleared by clr
   reg [3:0] n_arm;     // observation windows opened (free-running, wraps)
   reg [3:0] n_clr;     // observation windows closed (free-running, wraps)

    initial begin
        gnt      = 4'b0000;
        ptr      = 2'd0;
        prev_gnt = 4'b0000;
        prev_ptr = 2'd0;
        hist     = 4'b0000;
        armed    = 1'b0;
       hold     = 2'd0;
       n_iss    = 4'd0;
       n_ret    = 4'd0;
      n_arm    = 4'd0;
      n_clr    = 4'd0;
    end

    // rotating priority: start just past the last grant
    wire [1:0] c0 = ptr + 2'd1;
    wire [1:0] c1 = ptr + 2'd2;
    wire [1:0] c2 = ptr + 2'd3;
    wire [1:0] c3 = ptr;

    reg       sel_val;
    reg [1:0] sel_idx;
    always @(*) begin
        if (req[c0])      begin sel_val = 1'b1; sel_idx = c0;   end
        else if (req[c1]) begin sel_val = 1'b1; sel_idx = c1;   end
        else if (req[c2]) begin sel_val = 1'b1; sel_idx = c2;   end
        else if (req[c3]) begin sel_val = 1'b1; sel_idx = c3;   end
        else              begin sel_val = 1'b0; sel_idx = 2'd0; end
    end

    // one-hot (or all-zero) next grant, never on a non-requesting line
    wire [3:0] nxt = sel_val ? (4'b0001 << sel_idx) : 4'b0000;

   // a grant is parked on its line until that line drops its request; the
   // issue/retire ledger is what tells the arbiter it may re-arbitrate
   wire outstanding = (n_iss != n_ret);
   wire issue       = ce && !outstanding && sel_val;
   wire retire      = ce &&  outstanding && !req[hold];

  // the arm/clr handshake is logged the same way, and the window ledger --
  // not the flag -- decides whether a fresh window may be opened or closed
  wire win_open = (n_arm != n_clr);
  wire do_open  = arm && !win_open;
  wire do_close = clr &&  win_open;

    always @(posedge clk) begin
        if (rst) begin
            gnt      <= 4'b0000;
            ptr      <= 2'd0;
            prev_gnt <= 4'b0000;
            prev_ptr <= 2'd0;
            hist     <= 4'b0000;
            armed    <= 1'b0;
           hold     <= 2'd0;
           n_iss    <= 4'd0;
           n_ret    <= 4'd0;
          n_arm    <= 4'd0;
          n_clr    <= 4'd0;
        end else begin
            if (ce) begin
               if (outstanding) begin
                   gnt <= req[hold] ? (4'b0001 << hold) : 4'b0000;
               end else begin
                   gnt <= nxt;
                   if (sel_val) begin
                       ptr  <= sel_idx;
                       hold <= sel_idx;
                   end
               end
                prev_gnt <= gnt;
                prev_ptr <= ptr;
               // a line only counts as rested-on while it holds a grant
              // and only while a window is open to record it
              if (win_open && outstanding) hist <= hist | (4'b0001 << ptr);
            end
           n_iss <= n_iss + {3'd0, issue};
           n_ret <= n_ret + {3'd0, retire};
          n_arm <= n_arm + {3'd0, do_open};
          n_clr <= n_clr + {3'd0, do_close};
            // opening the observation window restarts the shadow record
           if (do_open) begin
                armed    <= 1'b1;
                prev_gnt <= 4'b0000;
                prev_ptr <= 2'd0;
                hist     <= 4'b0000;
           end else if (do_close) begin
                armed <= 1'b0;
            end
        end
    end

    // after arm, until clr (which may never come): a recorded grant must have
    // been preceded by the pointer standing on that very line
    always @(posedge clk) begin
        if (armed)
            assert (prev_gnt == 4'b0000 || prev_gnt == (4'b0001 << prev_ptr));
        if (armed)
            assert (prev_gnt == 4'b0000 || (hist & prev_gnt) != 4'b0000);
    end
endmodule

