// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;
reg       ireq;                // port-side launch register (req -> issue)
reg [1:0] pend;                // requests held in the two launch registers
reg       issue;                // request launch register (input -> stage 0)
reg [1:0] bcnt;                 // back-half occupancy (stage 3 only)
reg       hand;                 // request in the stage1 -> stage2 handover
reg [3:0] n_in;                 // ledger: requests entering the shifter
reg [3:0] n_out;                // ledger: requests retired out of stage 3
reg [2:0] credit;                // free holding places left, 6 down to 0

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;
initial ireq     = 1'b0;
initial pend     = 2'd0;
initial issue    = 1'b0;
initial bcnt     = 2'd0;
initial hand     = 1'b0;
initial n_in     = 4'd0;
initial n_out    = 4'd0;
initial credit   = 3'd6;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

// outstanding-request accounting.  The ledger counters are written when a
// request crosses into the shifter and when it retires, so their difference
// only covers the four pipeline stages; the requests still waiting in the
// launch registers are carried by the port's own credit counter.  The port
// sums the two parts and refuses a new request once every holding place is
// taken.
wire [3:0] depth  = n_in - n_out;
wire [3:0] total  = depth + {2'b00, pend};
wire       accept = req && (credit != 3'd0);

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
ireq     <= 1'b0;
pend     <= 2'd0;
issue    <= 1'b0;
bcnt     <= 2'd0;
hand     <= 1'b0;
n_in     <= 4'd0;
n_out    <= 4'd0;
credit   <= 3'd6;
        end else if (step) begin
// the request bus is double-registered at the pipeline input to cut
// the path from req into stage 0: an accepted request waits two
// advances in the launch registers before it occupies stage 0.  The
// front count picks it up on the second of those advances, and the
// port credit counter holds it until then.
ireq     <= accept;
issue    <= ireq;
inflight <= {inflight[2:0], issue};
// each pipeline half maintains its own occupancy count locally.  The
// stage1 -> stage2 crossing is registered to keep the adder chains
// short: the front count drops the request on the advance that moves
// it out of stage 1, the handover latch carries it, and the back
// count picks it up on the following advance.
cnt      <= cnt  + {2'b00, ireq}          - {2'b00, inflight[1]};
pend     <= pend + {1'b0,  accept}        - {1'b0,  issue};
bcnt     <= bcnt + {1'b0,  hand}          - {1'b0,  retire};
hand     <= inflight[1];
n_in     <= n_in  + {3'b000, issue};
n_out    <= n_out + {3'b000, retire};
// the accept path runs off a dedicated free-slot credit counter so the
// request qualifier does not have to wait for the ledger subtraction
// and the pend adder: one credit is spent when a request is taken in
// and returned when a request retires out of stage 3.
credit   <= credit - {2'b00, accept} + {2'b00, retire};
        end
    end

assign f_idle = (cnt == 3'd0) && (bcnt == 2'd0) && !hand && (pend == 2'd0);
// six holding places: the two launch registers plus the four stages.  The
// ledger difference plus the port credit is the authoritative count.
assign f_full = (total == 4'd6);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

   // Q: if the credit counter has handed out every slot, then every slot
   // really is occupied -- both launch registers and all four stages.
   always @(posedge clk)
       assert (!(credit == 3'd0) || (ireq && issue && !f_slot));

endmodule

