pipe     <= {pipe[4:0], accept};
inflight <= inflight + {2'b00, accept} - {2'b00, retire};
act_cnt <= act_cnt + {3'b000, retire};
seen    <= seen | issue;
        end
    end
// credit accounting and outstanding-limit retuning
always @(posedge clk) begin
    if (rst) begin
        cred <= 3'd4;
        lim  <= 3'd4;
        thr  <= 1'b0;
        rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
    end else if (i_ce) begin
        if (quiesce) begin
            lim  <= thr ? 3'd2 : 3'd4;
            cred <= thr ? 3'd2 : 3'd4;
            thr  <= 1'b0;
            rtn  <= 3'd0;
mrg  <= 1'b0;
mg0  <= 1'b0;
mg1  <= 1'b0;
mg2  <= 1'b0;
mg3  <= 1'b0;
        end else begin
cred <= cred - {2'b00, accept} + {2'b00, mg3};
            rtn  <= rtn + {2'b00, rq3} - {2'b00, drain};
mrg  <= drain;
mg0  <= mrg;
mg1  <= mg0;
mg2  <= mg1;
mg3  <= mg2;
        end
    end else if (pipe != 6'b000000) begin
        thr  <= 1'b1;
    end
end

// credit-return path: retire pulses shift back toward the issue side
always @(posedge clk) begin
    if (rst) begin
        rq0 <= 1'b0;
        rq1 <= 1'b0;
        rq2 <= 1'b0;
        rq3 <= 1'b0;
    end else if (i_ce) begin
        rq0 <= retire;
        rq1 <= rq0;
        rq2 <= rq1;
        rq3 <= rq2;
    end
end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

