    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;
    initial n_load    = 4'd0;
    initial n_samp    = 4'd0;
initial n_cap     = 4'd0;
initial n_rel     = 4'd0;
initial cap_pend  = 1'b0;
initial cap_s2    = 1'b0;
initial cap_s3    = 1'b0;
initial cap_s4    = 1'b0;
initial rel_s1    = 1'b0;
initial rel_s2    = 1'b0;
initial rel_s3    = 1'b0;
initial rel_s4    = 1'b0;
   initial gap       = 3'd0;

    always @(posedge clk) begin
