            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
            n_load    <= 4'd0;
            n_samp    <= 4'd0;
n_cap     <= 4'd0;
n_rel     <= 4'd0;
cap_pend  <= 1'b0;
cap_s2    <= 1'b0;
cap_s3    <= 1'b0;
cap_s4    <= 1'b0;
rel_s1    <= 1'b0;
rel_s2    <= 1'b0;
rel_s3    <= 1'b0;
rel_s4    <= 1'b0;
           gap       <= 3'd0;
        end
