        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
      cnt2 = 4'd0;
      g2   = 4'd0;
      ph   = 1'b0;
     cnt3 = 4'd0;
     g3   = 4'd0;
     own  = 3'b001;
act   = 4'd0;
o_act = 4'd0;
idlecnt = 4'd0;
o_dbg   = 4'd0;
