    initial free  = 2'd2;
   initial hwm   = 2'd0;
  initial peak_q = 2'd0;
 initial hwm_b    = 2'd0;
 initial peak_sel = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
   initial vb0   = 1'b0;
   initial vb1   = 1'b0;
   initial cntb  = 2'd0;
