        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
           s_v   <= 1'b0;
           s_d   <= 8'h00;
          s2_v  <= 1'b0;
          s2_d  <= 8'h00;
         s3_v  <= 1'b0;
         s3_d  <= 8'h00;
         sk_credit <= 2'd3;
          skid_occ <= 2'd0;
         inc_pend <= 1'b0;
        xfer_pend <= 2'd0;
o_push_tally <= 4'd0;
