               // the parked skid sample takes the freed tail slot
               v1    <= 1'b1;
               d1    <= s_d;
              s_v   <= s2_v;
              s_d   <= s2_d;
             s2_v  <= s3_v;
             s2_d  <= s3_d;
             s3_v  <= 1'b0;
             // the skid loses one unit of occupancy here; it reaches count
             // one edge later through xfer_pend
            skid_occ <= {1'b0, s2_v} + {1'b0, s3_v};
            sk_credit <= sk_credit + 2'd1;
           end else if (i_push) begin
               // we reported full, so this beat lands in the freed tail
               v1 <= 1'b1;
               d1 <= i_data;
           end else begin
               v1    <= 1'b0;
           end
       end else if (do_skid) begin
           s_v   <= 1'b1;
           s_d   <= i_data;
          skid_occ <= skid_occ + 2'd1;
         sk_credit <= sk_credit - 2'd1;
      end else if (do_skid2) begin
          s2_v  <= 1'b1;
          s2_d  <= i_data;
         skid_occ <= skid_occ + 2'd1;
        sk_credit <= sk_credit - 2'd1;
     end else if (do_skid3) begin
         s3_v  <= 1'b1;
         s3_d  <= i_data;
        skid_occ <= skid_occ + 2'd1;
        sk_credit <= sk_credit - 2'd1;
      end
        // i_push = i_pop = 0 : the buffer idles, all state held
       if (!i_rst) begin
          count     <= count + {2'b00, inc_pend} - {2'b00, core_leave} + {1'b0, xfer_pend};
           inc_pend <= core_join;
          xfer_pend <= skid_drain;
       end
if (!i_rst && do_push)
    o_push_tally <= o_push_tally + 4'd1;
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
 assign o_count = count + {1'b0, skid_occ} + {2'b00, inc_pend} + {1'b0, xfer_pend};

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
