module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
output reg        armed,   // sticky: set the first time a request is taken
output reg  [3:0] n_take,  // ledger: leases issued  (free-running, wraps)
output reg  [3:0] n_drop,  // ledger: leases retired (free-running, wraps)
output reg        stale,   // standing lease has burned one idle cycle
output reg  [3:0] req_seen // sticky union of newly-arriving request bits
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit
   // retirements are booked by half: a low-half holder settles into n_drop,
   // a high-half holder into its own column, so the two halves of the
   // ledger can be read out independently
   reg [3:0] n_drop_hi;
   // issues are booked the same way: the winner's half decides which
   // take column advances, so each half's lease traffic can be metered
   // straight off the ledger
   reg [3:0] n_take_hi;
   // channel B: a second lease register set.  Both channels drive the same
   // downstream consumer, so they share the ledger columns and the
   // acknowledge outputs; `turn` alternates which channel is offered the
   // next fresh lease.
   reg        vld_b;
   reg  [1:0] idx_b;
   reg  [3:0] oh_b;
   reg        stale_b;
   reg        turn;
// shadow copy of the previous request vector, used for edge detection only
reg [3:0] req_prev;

   // the ledger, not vld, is the authority on lease occupancy
  wire [3:0] n_ret       = n_drop + n_drop_hi;
 wire [3:0] n_iss       = n_take + n_take_hi;
 wire       outstanding = (n_iss != n_ret);

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
n_take = 4'd0;
       n_take_hi = 4'd0;
n_drop = 4'd0;
       n_drop_hi = 4'd0;
stale  = 1'b0;
req_seen  = 4'd0;
req_prev  = 4'd0;
       vld_b   = 1'b0;
       idx_b   = 2'd0;
       oh_b    = 4'b0000;
       stale_b = 1'b0;
       turn    = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
// bookkeeping only: remember which request lines have newly arrived
req_prev <= req;
req_seen <= req_seen | (req & ~req_prev);
           ack_lo <= (vld   && (idx   < 2'd2)) ||
                     (vld_b && (idx_b < 2'd2));
           ack_hi <= (vld   && (oh[3]   || oh[2])) ||
                     (vld_b && (oh_b[3] || oh_b[2]));

            if (any) begin
               // a request refreshes the standing lease on its own channel
                armed <= 1'b1;
                if (!outstanding) begin
                    // ledger is square: issue a fresh lease to the winner
                   // and hand the bus to whichever channel has the turn
                   turn <= ~turn;
                   if (turn) begin
                       vld_b   <= 1'b1;
                       stale_b <= 1'b0;
                       idx_b   <= enc;
                       oh_b    <= iso;
                   end else begin
                       vld   <= 1'b1;
                       stale <= 1'b0;
                       idx   <= enc;
                       oh    <= iso;
                   end
                  if (enc[1]) n_take_hi <= n_take_hi + 4'd1;
                  else        n_take    <= n_take    + 4'd1;
               end else if (vld_b) begin
                   // channel B is the holder: refreshed in place, and it
                   // yields the bus to a higher-priority requester
                   stale_b <= 1'b0;
                   if (enc < idx_b) begin
                       idx_b <= enc;
                       oh_b  <= iso;
                   end
               end else begin
                   // channel A is the holder
                   vld   <= 1'b1;
                   stale <= 1'b0;
                   if (enc < idx) begin
                    // lease already in flight: a higher-priority requester
                    // takes it over in place -- a hand-off, not a new lease,
                    // so the ledger does not move
                    idx <= enc;
                    oh  <= iso;
                end
               end
                // otherwise the current holder keeps the bus
            end else if (outstanding) begin
               if (vld_b) begin
                   if (stale_b) begin
                       // channel B retires into the shared drop columns
                       vld_b   <= 1'b0;
                       stale_b <= 1'b0;
                       if (idx_b[1]) n_drop_hi <= n_drop_hi + 4'd1;
                       else          n_drop    <= n_drop    + 4'd1;
                   end else begin
                       idx_b   <= idx_b + 2'd1;
                       oh_b    <= {oh_b[2:0], oh_b[3]};
                       stale_b <= 1'b1;
                   end
               end else if (stale) begin
                    // second idle cycle retires the lease; the one-hot is
                    // left parked as a record of the last holder
                    vld    <= 1'b0;
                    stale  <= 1'b0;
                   if (idx[1]) n_drop_hi <= n_drop_hi + 4'd1;
                   else        n_drop    <= n_drop    + 4'd1;
                end else begin
                    // first idle cycle: age the standing grant round-robin
                    idx   <= idx + 2'd1;
                    oh    <= {oh[2:0], oh[3]};
                    stale <= 1'b1;
                end
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

