module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
output wire [3:0] o_gnt,
output reg [3:0]  req_hist,
output reg [3:0]  n_iss,
output reg [3:0]  n_ret
);
    // Latency budget granted to an accepted request.
localparam [2:0] BUDGET_MAX = 3'd5;
localparam [2:0] BUDGET_MIN = 3'd3;

// Adaptive latency allowance. A slave that times out earns one extra
// credit for the next requester; a slave that answers within a cycle
// gives one back. Only rewritten in the gap between grants.
reg [2:0] budget;
// Latency of the most recently completed transaction, in cycles. Feeds
// the budget hysteresis below: the window is only narrowed after two
// quick responses in a row, so a single lucky slave cannot starve the
// next requester.
reg [2:0] last_lat;
// Contention ceiling. Under sustained backpressure (four consecutive
// cycles with an unserved request) the arbiter advertises a tighter
// maximum window so the request queue can drain; once the history
// clears it relaxes the ceiling again, one credit per idle cycle.
reg [2:0] cap;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
// Outstanding-transaction ledger: n_iss logs every grant handed to the
// interconnect, n_ret logs every grant given back. Both wrap freely.
// A response is only honoured while the ledger still shows an issued,
// unreturned beat, so a stray done pulse on the response channel is
// dropped instead of retiring a grant that was never logged.
wire ledger_busy = (n_iss != n_ret);
wire retire = gnt_valid && ledger_busy && (done || ((elapsed == (budget - 3'd1)) && (timer == 3'd1)));

   // Next advertised window, and the allowance actually handed out once
   // the running budget has been clamped into that window.
   wire [2:0] cap_next = (req_hist == 4'b1111) ? ((cap == BUDGET_MIN) ? BUDGET_MIN : cap - 3'd1) :
                         (req_hist == 4'b0000) ? ((cap == BUDGET_MAX) ? BUDGET_MAX : cap + 3'd1) :
                                                 cap;
   wire [2:0] alloc    = (budget > cap_next) ? cap_next : budget;

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;
initial budget    = BUDGET_MAX;
initial last_lat  = 3'd0;
initial cap       = BUDGET_MAX;
initial req_hist  = 4'd0;
initial n_iss     = 4'd0;
initial n_ret     = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
budget    <= BUDGET_MAX;
last_lat  <= 3'd0;
cap       <= BUDGET_MAX;
req_hist  <= 4'd0;
n_iss     <= 4'd0;
n_ret     <= 4'd0;
        end else if (i_ce) begin
req_hist <= {req_hist[2:0], (|req) & ~done};
            if (!gnt_valid) begin
               cap    <= cap_next;
               budget <= alloc;
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                   timer     <= alloc;    // credits left, clamped to window
                    elapsed   <= 3'd0;     // cycles burnt
n_iss     <= n_iss + 4'd1;
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
n_ret     <= n_ret + 4'd1;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
last_lat  <= elapsed;
if (!done)
   budget <= (budget >= cap) ? cap : budget + 3'd1;
else if ((elapsed <= 3'd1) && (last_lat <= 3'd1))
    budget <= (budget == BUDGET_MIN) ? BUDGET_MIN : budget - 3'd1;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));

   // Latency monitor: the recorded latency of the last completed
   // transaction always fits strictly inside the widest window the
   // arbiter can hand out, and an outstanding grant never carries more
   // credits than that window either.
   always @(posedge clk)
       assert ((last_lat < BUDGET_MAX) && (!gnt_valid || (timer <= BUDGET_MAX)));
endmodule

