assign o_nspend = n_spend;
assign o_nret   = n_ret;
assign o_phase  = phase;
assign o_rdy    = rdy;
assign o_ngrant = n_grant;
assign o_nuse   = n_use;

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
stage <= 4'd0;
stage_b <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
n_spend <= 4'd0;
n_ret <= 4'd0;
phase <= 1'b0;
rdy <= 1'b0;
n_grant <= 4'd0;
n_use <= 4'd0;
sready <= 1'b0;
n_stg <= 4'd0;
n_lnch <= 4'd0;
pri_b <= 1'b0;
req <= 1'b0;
ret_q <= 1'b0;
