                    timer <= timer - 4'd1;
            end else begin
avail <= avail + ret_q;
if (push) begin
    outst <= outst + 4'd1;
if (push_a) stage   <= stage   - 4'd1;
if (push_b) stage_b <= stage_b - 4'd1;
end
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
