module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
output wire o_grant,
output wire [2:0] o_n_in,
output wire [2:0] o_n_out
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
   // admit decision in flight toward the accumulator: the count update is
   // retimed through one register stage, so `ones` trails the window by a beat
   reg         adm_q;
   // issue pipeline: a granted request spends four cycles travelling from the
   // decision point to the head of the window, one stage per cycle
   reg         s1;
   reg         s2;
   reg         s3;
   reg         s4;
  // credit-return pipeline: a slot that falls off the far end of the window
  // walks four stages of the accounting block before its credit is handed
  // back to the retire ledger, one stage per enabled cycle
  reg         d1;
  reg         d2;
  reg         d3;
  reg         d4;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
   // post-grant cooldown: a grant is followed by two enabled cycles of refusal
   reg [1:0]   gap;
    reg         pv;
// issue/retire ledger: one tick per admit pushed into the window, one per
// slot that falls off the far end. Free running, they wrap at three bits.
reg [2:0]   n_in;
reg [2:0]   n_out;

    initial win   = 0;
    initial ones  = 0;
   initial adm_q = 0;
   initial s1    = 0;
   initial s2    = 0;
   initial s3    = 0;
   initial s4    = 0;
  initial d1    = 0;
  initial d2    = 0;
  initial d3    = 0;
  initial d4    = 0;
    initial armed = 0;
   initial gap   = 0;
    initial pv    = 0;
initial n_in  = 0;
initial n_out = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
   // plus the admit still in flight, which the accumulator has not absorbed yet
   wire [2:0] eff      = ones - retiring + (adm_q ? 3'd1 : 3'd0);
// occupancy straight off the ledger: n_in ticks when an admit is issued into
// the pipeline and n_out when a slot retires, so the difference covers the
// window and everything still in flight behind it
wire [2:0] occ  = n_in - n_out;
// the same figure once the oldest slot has retired
wire [2:0] live = occ - retiring;

// rate decision is taken from the ledger, which is exact for this cycle,
   // and is additionally blocked while the post-grant cooldown is running
wire allow = i_req && (live < LIMIT) && (gap == 2'd0);
// the retimed accumulator now sizes the cooldown instead: a window already
// carrying two admits earns the long pause, a lightly loaded one a short one
wire [1:0] cool = (eff >= 3'd2) ? 2'd2 : 2'd1;

    assign o_grant = i_ce && allow;
assign o_n_in  = n_in;
assign o_n_out = n_out;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
           adm_q <= 0;
           s1    <= 0;
           s2    <= 0;
           s3    <= 0;
           s4    <= 0;
          d1    <= 0;
          d2    <= 0;
          d3    <= 0;
          d4    <= 0;
            armed <= 0;
           gap   <= 0;
n_in  <= 0;
n_out <= 0;
        end else if (i_ce) begin
win   <= { win[W-2:0], s4 };
           ones  <= ones - retiring + (adm_q ? 3'd1 : 3'd0);
adm_q <= s4;
s1    <= allow;
s2    <= s1;
s3    <= s2;
s4    <= s3;
if (allow)
    n_in  <= n_in  + 3'd1;
d1    <= win[W-1];
d2    <= d1;
d3    <= d2;
d4    <= d3;
if (d4)
    n_out <= n_out + 3'd1;
            if (allow)
                armed <= 1'b1;
if (s4)
gap <= cool;
           else if (gap != 2'd0)
               gap <= gap - 2'd1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));

   // Cooldown consistency: halfway through a cooldown the grant that started it
   // is still resident in the window, so the mirrored occupancy is not empty.
   always @(posedge clk)
       if (pv)
           assert ((gap != 2'd1) || (ones != 3'd0 || adm_q));
endmodule

