// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
output wire       o_in_ready,
output wire [3:0] o_fire_count
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

   // second (tail) skid slot: lets the stage swallow one more word when the
   // consumer stalls for two cycles in a row instead of dropping in_ready
   // immediately behind a single buffered word
   reg       skid2_valid = 1'b0;
   reg [1:0] skid2_code  = ARM;

   // one-cycle inter-chain gap: after a FINISH leaves the stage the
   // producer is held off for a cycle so it can resynchronise on the
   // head of the next chain
   reg       gap        = 1'b0;

// in-flight word ledger: every word taken from the producer and every word
// handed to the consumer is logged. The counters free-run and wrap; their
// difference is how many words the stage is currently holding, and that is
// what the backpressure below is derived from. The ledger only covers the
// main path (output register + head slot); see tail_cnt below.
// Both counters are exported packed on the trace port.
reg [1:0] n_in  = 2'd0;
reg [1:0] n_out = 2'd0;

// the tail slot was bolted on after the ledger existed, and rather than
// re-timing the ledger it keeps its own occupancy count; the backpressure
// below sums the two
reg [1:0] tail_cnt = 2'd0;

    wire [1:0] in_code  = src_phase + 2'd1;
wire [1:0] led_occ  = n_in - n_out;
wire [2:0] occ_all  = {1'b0, led_occ} + {1'b0, tail_cnt};
wire       in_ready = (occ_all != 3'd3) && !gap;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

// where an accepted word lands, and when the tail slot shifts into the head
wire       take_tail = in_valid && in_ready && skid_valid && !out_room;
wire       take_main = in_valid && in_ready && !(skid_valid && !out_room);
wire       tail_pop  = skid2_valid && out_room;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;
assign o_fire_count = {n_in, n_out};

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
           skid2_valid <= 1'b0;
           skid2_code  <= ARM;
           gap        <= 1'b0;
n_in       <= 2'd0;
n_out      <= 2'd0;
tail_cnt   <= 2'd0;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
               end else if (in_valid && in_ready) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
               if (out_room) begin
                   // head drains into the output register; refill it from
                   // the tail slot, or straight from the producer
                   if (skid2_valid) begin
                       skid_valid <= 1'b1;
                       skid_code  <= skid2_code;
                   end else if (in_valid && in_ready) begin
                       skid_valid <= 1'b1;
                       skid_code  <= in_code;
                   end else begin
                       skid_valid <= 1'b0;
                   end
               end
           end else if (in_valid && in_ready && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

