    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
       stg_v   = 1'b0;
       stg_d   = 9'd0;
      skid_v  = 1'b0;
      skid_d  = 9'd0;
      n_push  = 4'd0;
      n_pop   = 4'd0;
o_op_shadow = 4'd0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
