// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
output reg  [2:0] len,
output reg  [3:0] qcnt
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;
    // An escape can now be taken from top level or from inside an identifier,
    // so S_ESC alone no longer says which token is being built: the state code
    // to resume with is held here while st == S_ESC.
    reg [2:0] esc_ret;
   // Second lexer channel. The two character streams are interleaved on cls
   // and take turns owning the single decode/commit datapath below. Channel B
   // measures records rather than tokens, so its length is carried across a
   // token boundary instead of being cleared.
   reg [2:0] st_b;
   reg [2:0] len_b;
   reg [2:0] esc_b;
   reg       own;   // 0 = channel A owns the shared datapath, 1 = channel B
   // Decode and commit are now separate cycles: the next-state decode and the
   // length adder no longer share one combinational path to the outputs. A
   // character is absorbed into the staging pair in one cycle and the pair is
   // driven onto st/len in the next.
   reg [2:0] st_s;
   reg [2:0] len_s;
   reg       s_vld;
reg       last_q;

   wire [2:0] cur_st  = own ? st_b  : st;
   wire [2:0] cur_len = own ? len_b : len;
   wire [2:0] cur_esc = own ? esc_b : esc_ret;
   wire [2:0] len_inc = (cur_len == 3'd7) ? 3'd7 : (cur_len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;
    initial esc_ret = S_IDLE;
   initial st_s  = S_IDLE;
   initial len_s = 3'd0;
   initial s_vld = 1'b0;
   initial st_b  = S_IDLE;
   initial len_b = 3'd0;
   initial esc_b = S_IDLE;
   initial own   = 1'b0;
initial qcnt   = 4'd0;
initial last_q = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
            esc_ret <= S_IDLE;
           st_s  <= S_IDLE;
           len_s <= 3'd0;
           s_vld <= 1'b0;
           st_b  <= S_IDLE;
           len_b <= 3'd0;
           esc_b <= S_IDLE;
           own   <= 1'b0;
qcnt   <= 4'd0;
last_q <= 1'b0;
        end else if (ce) begin
           if (s_vld) begin
              if (own) begin
                  st_b  <= st_s;   // commit cycle: the staged pair goes back
                  len_b <= len_s;  // to whichever channel was decoded
              end else begin
                  st    <= st_s;
                  len   <= len_s;
              end
               s_vld <= 1'b0;
              own   <= ~own;   // round-robin: the other stream gets the next char
           end else begin
               s_vld <= 1'b1;   // decode cycle: absorb this character
           case (cur_st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                       st_s  <= S_IDENT;
                       len_s <= 3'd1;
                    end else if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= 3'd1;
                    end else if (cls == 2'd3) begin
                       st_s  <= S_STR;
                       len_s <= 3'd0;
                    end else begin
                      st_s <= S_ESC;   // stray backslash: escaped char starts an identifier
                      if (own) esc_b <= S_IDENT; else esc_ret <= S_IDENT;
                       len_s   <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                       st_s  <= S_IDENT;
                       len_s <= len_inc;
                    end else if (cls == 2'd0) begin
                       st_s    <= S_ESC;   // a\b is still a single identifier
                      if (own) esc_b <= S_IDENT; else esc_ret <= S_IDENT;
                      len_s   <= cur_len;
                    end else begin
                       st_s  <= S_IDLE;
                      len_s <= own ? len_inc : 3'd0;   // B keeps counting the record
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                       st_s  <= S_NUM;
                       len_s <= len_inc;
                    end else begin
                       st_s  <= S_IDLE;
                      len_s <= own ? len_inc : 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                       st_s  <= S_IDLE;   // closing quote ends the token
                      len_s <= own ? len_inc : 3'd0;
                    end else if (cls == 2'd0) begin
                       st_s  <= S_ESC;    // backslash: next char is literal
                      if (own) esc_b <= S_STR; else esc_ret <= S_STR;
                      len_s <= cur_len;
                    end else begin
                       st_s  <= S_STR;
                       len_s <= len_inc;
                    end
                end
                S_ESC: begin
                  st_s  <= cur_esc;     // resume whatever token the escape interrupted
                   len_s <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                   st_s  <= S_IDLE;
                end
            endcase
           end
if (cls == 2'd3) last_q <= 1'b1; else last_q <= 1'b0;
if (last_q && cls == 2'd1) qcnt <= qcnt + 4'd1;
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

