module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

   // credits parked against the burst currently in flight
   reg [1:0] escrow;

  // a return occupies the return path for one cycle before it lands
  reg       ret_q;
  reg [3:0] ret_amt;
 // lane B: a peer return lane that picks up the next return on the
 // cycle lane A drains, so returns can arrive back to back
 reg       ret_q2;
 reg [3:0] ret_amt2;
// grant commit stage: the credit file has a single write port, so a
// winning grant's debit is registered here on the decision cycle and
// charged against the credit file on the next one
reg       gnt_q;
reg [3:0] gnt_amt;
reg [1:0] gnt_resv;
// the credit file's write port sits four stages downstream of the
// arbiter, so a winning charge walks the pipe before it lands
reg       gnt_q2;
reg [3:0] gnt_amt2;
reg [1:0] gnt_resv2;
reg       gnt_q3;
reg [3:0] gnt_amt3;
reg [1:0] gnt_resv3;
reg       gnt_q4;
reg [3:0] gnt_amt4;
reg [1:0] gnt_resv4;
reg       gnt_q5;
reg [3:0] gnt_amt5;
reg [1:0] gnt_resv5;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;
   initial escrow      = 2'd0;
  initial ret_q       = 1'b0;
  initial ret_amt     = 4'd0;
 initial ret_q2      = 1'b0;
 initial ret_amt2    = 4'd0;
initial gnt_q       = 1'b0;
initial gnt_amt     = 4'd0;
initial gnt_resv    = 2'd0;
initial gnt_q2      = 1'b0;
initial gnt_amt2    = 4'd0;
initial gnt_resv2   = 2'd0;
initial gnt_q3      = 1'b0;
initial gnt_amt3    = 4'd0;
initial gnt_resv3   = 2'd0;
initial gnt_q4      = 1'b0;
initial gnt_amt4    = 4'd0;
initial gnt_resv4   = 2'd0;
initial gnt_q5      = 1'b0;
initial gnt_amt5    = 4'd0;
initial gnt_resv5   = 2'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

   // at burst start one credit per other waiting requester is parked in
   // escrow, so a burst that has been admitted can always be drained
   wire [3:0] others = req & ~(4'b0001 << idx);
   wire [1:0] resv   = {1'b0, others[0]} + {1'b0, others[1]} +
                       {1'b0, others[2]} + {1'b0, others[3]};
   wire       burst_start = (outstanding == 4'd0);
   wire [3:0] need        = burst_start ? (4'd1 + {2'b00, resv}) : 4'd1;
   wire have_credit = (credits >= need);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
   // a return is captured one cycle and applied the next
// the charge pipe owns the credit write port from the decision
// cycle until the charge reaches the far end
wire gnt_busy = gnt_q || gnt_q2 || gnt_q3 || gnt_q4 || gnt_q5;
wire ret_start  = i_ce && ret && !ret_q && !gnt_busy &&
                  (outstanding > {3'd0, ret_q2});
wire ret_start2 = i_ce && ret && ret_q && !ret_q2 && !gnt_busy &&
                  (outstanding > 4'd1);
  // the two lanes share one credit write port; lane A drains first
  wire ret_done   = i_ce && ret_q;
  wire ret_done2  = i_ce && ret_q2 && !ret_q;
   // the return path has priority; grants stall while it is busy
wire do_grant   = i_ce && have_credit && any_req &&
!ret_q && !ret_q2 && !gnt_busy && !ret_start;
// the registered debit owns the credit write port when it lands
wire gnt_commit = i_ce && gnt_q5;

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
           escrow      <= 2'd0;
           ret_q       <= 1'b0;
           ret_amt     <= 4'd0;
          ret_q2      <= 1'b0;
          ret_amt2    <= 4'd0;
gnt_q       <= 1'b0;
gnt_amt     <= 4'd0;
gnt_resv    <= 2'd0;
gnt_q2      <= 1'b0;
gnt_amt2    <= 4'd0;
gnt_resv2   <= 2'd0;
gnt_q3      <= 1'b0;
gnt_amt3    <= 4'd0;
gnt_resv3   <= 2'd0;
gnt_q4      <= 1'b0;
gnt_amt4    <= 4'd0;
gnt_resv4   <= 2'd0;
gnt_q5      <= 1'b0;
gnt_amt5    <= 4'd0;
gnt_resv5   <= 2'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

          // capture side: each lane latches the amount it will hand back
          if (ret_start) begin
              ret_q   <= 1'b1;
              ret_amt <= (outstanding == 4'd1 + {3'd0, ret_q2})
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end
          if (ret_start2) begin
              ret_q2   <= 1'b1;
              ret_amt2 <= (outstanding == 4'd2)
                           ? (4'd1 + {2'b00, escrow}) : 4'd1;
          end


         // arbitration only records the winner's charge; the credit
// file itself is written when the charge reaches the last stage
gnt_q2    <= gnt_q;
gnt_amt2  <= gnt_amt;
gnt_resv2 <= gnt_resv;
gnt_q3    <= gnt_q2;
gnt_amt3  <= gnt_amt2;
gnt_resv3 <= gnt_resv2;
gnt_q4    <= gnt_q3;
gnt_amt4  <= gnt_amt3;
gnt_resv4 <= gnt_resv3;
gnt_q5    <= gnt_q4;
gnt_amt5  <= gnt_amt4;
gnt_resv5 <= gnt_resv4;
gnt_q     <= 1'b0;
         if (do_grant) begin
             gnt_q    <= 1'b1;
             gnt_amt  <= need;
             gnt_resv <= burst_start ? resv : escrow;
         end

         if (gnt_commit) begin
credits     <= credits - gnt_amt5;
escrow      <= gnt_resv5;
             outstanding <= outstanding + 4'd1;
           end else if (ret_done) begin
               credits <= credits + ret_amt;
               if (outstanding == 4'd1)
                   escrow <= 2'd0;
               outstanding <= outstanding - 4'd1;
               ret_q <= 1'b0;
          end else if (ret_done2) begin
              credits <= credits + ret_amt2;
              if (outstanding == 4'd1)
                  escrow <= 2'd0;
              outstanding <= outstanding - 4'd1;
              ret_q2 <= 1'b0;
           end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

