        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
           ov_state     <= OV_IDLE;
           ov_pend      <= 1'b0;
fb_cmd       <= FB_NOP;
           cur_state    <= CU_IDLE;
           cur_pend     <= 1'b0;
vs_count     <= 4'd0;
o_frame_tag  <= 4'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                   if (i_start && fb_free) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
// the clear pass hands its update to the framebuffer write port
// rather than touching the shadow directly
fb_cmd       <= FB_CLR;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                   ov_pend      <= 1'b1;   // overlay gets the buffer next
                  cur_pend     <= 1'b1;   // cursor repaints after the overlay
