module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
output wire radio_rx,  // receive chain owns the radio
output reg  [3:0] rx_evt_count // count of observed preambles (diagnostic)
);
    // one-hot MAC air-interface FSM:
//   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_BURST, bit3 = ACK_WAIT
reg [3:0] state;
initial state = 4'b0001;

// transmit burst sequencer: one-hot shift register that walks the PA
// through the preamble and data phases of a granted frame
//   bit0 = PREAMBLE, bit1 = DATA, 2'b00 = burst finished
reg [1:0] txph;
initial txph = 2'b00;

   // periodic beacon engine; shares the radio front end with the MAC FSM
   //   bit0 = B_IDLE, bit1 = B_RAMP, bit2 = B_SEND
   reg [2:0] bstate;
   reg [3:0] btimer;
  // PA bias-settling pipeline: the beacon power amp needs four cycles of
  // bias settling between the interval expiring and the ramp keying the
  // front end, so the arm decision walks these stages before it is applied
  reg pa_arm0, pa_arm1, pa_arm2, pa_arm3;
   initial bstate = 3'b001;
   initial btimer = 4'd15;
  initial pa_arm0 = 1'b0;
  initial pa_arm1 = 1'b0;
  initial pa_arm2 = 1'b0;
  initial pa_arm3 = 1'b0;
  initial rx_evt_count = 4'd0;

wire s_idle = state[0];
wire s_rx   = state[1];
wire s_txb  = state[2];
wire s_ackw = state[3];

wire tx_pre = txph[0];
wire tx_dat = txph[1];
// the MAC hands the air to the burst sequencer on the way out of IDLE
wire tx_start = s_idle & tx_req & ~rx_start;

   wire b_idle = bstate[0];
   wire b_ramp = bstate[1];
   wire b_send = bstate[2];
  wire pa_busy = pa_arm0 | pa_arm1 | pa_arm2 | pa_arm3;
  // a beacon whose PA is arming already owns the air as far as the MAC
  // is concerned, so the front end stays reserved for the whole settle
  wire b_busy = b_ramp | b_send | pa_busy;
   wire b_due  = (btimer == 4'd0);
   // the MAC keeps priority: the beacon only grabs an idle, unrequested radio
  wire b_arm  = b_idle & b_due & s_idle & ~rx_start & ~tx_req & ~pa_busy;
  // the ramp only starts once the bias pipeline has drained through
  wire b_go   = pa_arm3;

   wire [2:0] bnxt;
   assign bnxt[0] = (b_idle & ~b_go) | b_send;
   assign bnxt[1] = b_go;                             // ramp the beacon PA
   assign bnxt[2] = b_ramp;                           // ramp -> send beacon

    // next-state as a per-bit OR of its legal source states
wire [3:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
assign nxt[2] = tx_start | (s_txb & tx_pre);       // start / stay in burst
assign nxt[3] = s_txb & tx_dat;                    // data done -> ACK wait

    always @(posedge clk) begin
        if (rst)
state <= 4'b0001;
       // the air is single-ported: the MAC FSM stalls while the beacon has it
       else if (step && !b_busy)
            state <= nxt;
    end

  // the sequencer shifts a zero in on every granted cycle, so the burst
  // self-terminates one cycle after the data phase
  always @(posedge clk) begin
      if (rst)
          txph <= 2'b00;
      else if (step && !b_busy) begin
          if (tx_start)
              txph <= 2'b01;
          else
              txph <= {txph[0], 1'b0};
      end
  end

   always @(posedge clk) begin
      if (rst) begin
          bstate <= 3'b001;
          pa_arm0 <= 1'b0;
          pa_arm1 <= 1'b0;
          pa_arm2 <= 1'b0;
          pa_arm3 <= 1'b0;
      end
       else if (step)
      begin
          bstate <= bnxt;
          // bias settle: one stage per cycle, a single token in flight
          pa_arm0 <= b_arm;
          pa_arm1 <= pa_arm0;
          pa_arm2 <= pa_arm1;
          pa_arm3 <= pa_arm2;
      end
   end

   // beacon interval: reload on transmission, hold at zero until the air frees
   always @(posedge clk) begin
       if (rst)
           btimer <= 4'd15;
       else if (step) begin
           if (b_send)
               btimer <= 4'd15;
           else if (btimer != 4'd0)
               btimer <= btimer - 4'd1;
       end
   end

  // diagnostic preamble counter: observes the inputs only, drives nothing else
  always @(posedge clk) begin
      if (rst)
          rx_evt_count <= 4'd0;
      else if (step && rx_start)
          rx_evt_count <= rx_evt_count + 4'd1;
  end

    // decoded radio ownership
assign radio_tx = tx_pre | tx_dat | b_ramp | b_send;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

