// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
output wire busy,
output reg [3:0] evt_count
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;
    localparam [1:0] QDEPTH = 2'd2;   // staging queue in front of the window
   localparam [1:0] CDEPTH = 2'd2;   // completion buffer inside the window

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [1:0] queued;   // accepted, still waiting for a free window slot
   reg [1:0] qb;       // class-B staging queue sharing the same window
   reg [1:0] cdone;    // response landed, retirement handshake still pending
   reg       rr;       // round-robin pointer for the freed window slot
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid
reg [2:0] hist;     // sampled pin activity history (observability only)

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        queued  = 2'd0;
       qb      = 2'd0;
       cdone   = 2'd0;
       rr      = 1'b0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
evt_count = 4'd0;
hist      = 3'd0;
    end

   assign busy = (outst != 3'd0) || (queued != 2'd0) || (qb != 2'd0) || (cdone != 2'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);
   // window occupancy: response-pending entries plus entries whose response
   // has landed and that are waiting for the retirement handshake
   wire [2:0] occ = outst + {1'b0, cdone};
   wire cdone_room = (cdone < CDEPTH);

   wire [3:0] total = {1'b0, occ} + {2'b0, queued} + {2'b0, qb};

   // accept while the window plus both staging queues still have capacity
   wire do_issue  = ce && issue && (total < ({1'b0, WINDOW} + {2'b0, QDEPTH} + {2'b0, QDEPTH}));
   // a response moves the transaction out of the pipeline into the buffer
   wire do_resp   = ce && (outst != 3'd0) && (retire || force_ret) && cdone_room;
   // the buffer gives one entry back per enabled cycle; that handshake is
   // what advances the retire counter and releases the window slot
   wire do_retire = ce && (cdone != 2'd0);

    // a window slot is free, or is being freed by this cycle's retirement
   wire slot_free = (occ < WINDOW) || do_retire;
   // staged transactions are older than an incoming one, so they go first;
   // the two classes take turns for the slot the window frees up
   wire admit_a = ce && (queued != 2'd0) && slot_free && (!rr || (qb == 2'd0));
   wire admit_b = ce && (qb != 2'd0) && slot_free && !admit_a;
   wire admit   = admit_a || admit_b;
   wire direct  = do_issue && slot_free && !admit;
   wire enq     = do_issue && !direct;
   // a fresh transaction joins the shorter of the two queues
   wire enq_a   = enq && (queued <= qb);
   wire enq_b   = enq && !enq_a;

    wire [2:0] outst_n  = outst + ((admit || direct) ? 3'd1 : 3'd0)
                               - (do_resp ? 3'd1 : 3'd0);
   wire [1:0] queued_n = queued + (enq_a ? 2'd1 : 2'd0)
                                - (admit_a ? 2'd1 : 2'd0);
   wire [1:0] qb_n     = qb + (enq_b ? 2'd1 : 2'd0)
                            - (admit_b ? 2'd1 : 2'd0);
   wire [1:0] cdone_n  = cdone + (do_resp ? 2'd1 : 2'd0)
                               - (do_retire ? 2'd1 : 2'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;
       queued <= queued_n;
       qb     <= qb_n;
       cdone  <= cdone_n;
       if (admit) rr <= admit_a;

       if (do_issue || do_resp) begin
            // any scoreboard event restarts (or clears) the deadline
           if (outst_n == 3'd0 && queued_n == 2'd0 && qb_n == 2'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
if (ce) begin
    hist      <= {hist[1:0], issue ^ retire};
    evt_count <= evt_count + {3'd0, (hist[2] ^ retire)};
end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

