    initial v1    = 1'b0;
    initial head  = 1'b0;
    initial tail  = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;
   initial credits = 3'd2;
   initial limit  = 3'd2;
   initial full_r = 1'b0;

