            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
credits <= 3'd2;
           limit  <= 3'd2;
           full_r <= 1'b0;
        end else begin
            if (do_push) begin
                if (tail == 1'b0) begin
                    v0 <= 1'b1;
                    d0 <= i_data;
                end else begin
                    v1 <= 1'b1;
                    d1 <= i_data;
                end
                tail <= ~tail;
