            if (do_pop) begin
                if (head == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                head <= ~head;
            end

            count <= count + (do_push ? 3'd1 : 3'd0)
                            - (do_pop  ? 3'd1 : 3'd0);

           credits <= credits - (do_push ? 3'd1 : 3'd0)
                             + (do_pop  ? 3'd1 : 3'd0);

