module smbus_pec_mon (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire scl_low,
    input wire wvalid,
    input wire [127:0] wdata
);
    localparam [5:0] TMAX = 6'd50;

    reg [5:0]   low_cnt      = 6'd0;
    reg         timeout_flag = 1'b0;
    reg         before_to    = 1'b1;
    reg [127:0] wbuf         = 128'd0;
    reg         pend         = 1'b0;
    reg         pend_cnt     = 1'b0;
    reg [7:0]   pec_acc      = 8'h00;
    reg [6:0]   wcnt         = 7'd0;
    reg [7:0]   pec_snap     = 8'h00;
    reg         pv           = 1'b0;

    function [7:0] crc8_128;
        input [7:0] c;
        input [127:0] d;
        integer i;
        reg [7:0] r;
        reg fb;
        begin
            r = c;
            for (i = 127; i >= 0; i = i - 1) begin
                fb = r[7] ^ d[i];
                r = {r[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
            end
            crc8_128 = r;
        end
    endfunction

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (!rst_n) begin
            low_cnt      <= 6'd0;
            timeout_flag <= 1'b0;
            before_to    <= 1'b1;
            wbuf         <= 128'd0;
            pend         <= 1'b0;
            pend_cnt     <= 1'b0;
            pec_acc      <= 8'h00;
            wcnt         <= 7'd0;
            pec_snap     <= 8'h00;
        end else if (en) begin
            if (!scl_low)
                low_cnt <= 6'd0;
            else if (low_cnt < TMAX)
                low_cnt <= low_cnt + 6'd1;

            if (low_cnt == TMAX - 6'd1 && scl_low) begin
                timeout_flag <= 1'b1;
                before_to    <= 1'b0;
            end

            if (wvalid)
                wbuf <= wdata;

            if (wvalid)
                pend <= 1'b1;
            else if (pend)
                pend <= 1'b0;

            if (wvalid)
                pend_cnt <= 1'b1;
            else if (pend_cnt)
                pend_cnt <= 1'b0;

            if (pend)
                pec_acc <= crc8_128(pec_acc, wbuf);

            if (pend_cnt) begin
                wcnt     <= wcnt + 7'd1;
                pec_snap <= crc8_128(pec_acc, wbuf);
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(rst_n) && before_to && $past(before_to) && $stable(wcnt))
            assert ($stable(pec_acc));
