            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
