module pix_palette_bimap (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] din_a,
    input wire [7:0] din_b,
    output wire hit,
    output wire [5:0] addr,
    output wire [7:0] partner
);
    // 48 entries x 8 bits, flattened: entry i lives at [i*8 +: 8]
    reg [383:0] key_mem = 384'd0;
    reg [383:0] val_mem = 384'd0;
    reg [47:0]  valid = 48'd0;
    reg [5:0]   wr_ptr = 6'd0;
    reg         hit_q = 1'b0;
    reg [5:0]   addr_q = 6'd0;
    reg [7:0]   partner_q = 8'd0;
    reg         ever_ins = 1'b0;
    reg         pre_flush = 1'b1;

    assign hit = hit_q;
    assign addr = addr_q;
    assign partner = partner_q;

    // parallel search, lowest matching index wins
    reg       m_hit;
    reg [5:0] m_addr;
    reg [7:0] m_partner;
    reg [7:0] sel;
    integer i;
    always @(*) begin
        m_hit = 1'b0;
        m_addr = 6'd0;
        m_partner = 8'd0;
        sel = 8'd0;
        for (i = 47; i >= 0; i = i - 1) begin
            sel = (op == 2'b01) ? val_mem[i*8 +: 8] : key_mem[i*8 +: 8];
            if (valid[i] && (sel == din_a)) begin
                m_hit = 1'b1;
                m_addr = i;
                m_partner = (op == 2'b01) ? key_mem[i*8 +: 8] : val_mem[i*8 +: 8];
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 48'd0;
            hit_q <= 1'b0;
            addr_q <= 6'd0;
            partner_q <= 8'd0;
            ever_ins <= 1'b0;
            pre_flush <= 1'b1;
            wr_ptr <= 6'd0;
        end else if (en) begin
            case (op)
                2'b00, 2'b01: begin
                    hit_q <= m_hit;
                    addr_q <= m_addr;
                    partner_q <= m_partner;
                end
                2'b10: begin
                    key_mem[wr_ptr*8 +: 8] <= din_a;
                    val_mem[wr_ptr*8 +: 8] <= din_b;
                    valid[wr_ptr] <= 1'b1;
                    ever_ins <= 1'b1;
                    wr_ptr <= (wr_ptr == 6'd47) ? 6'd0 : wr_ptr + 6'd1;
                end
                default: begin
                    valid <= 48'd0;
                    hit_q <= 1'b0;
                    ever_ins <= 1'b0;
                    pre_flush <= 1'b0;
                end
            endcase
        end
    end

    // Precedence: before the first flush, a registered hit requires a prior insert
    always @(posedge clk)
        assert (!(pre_flush && hit_q) || ever_ins);
endmodule

