    initial begin
        row_idx  = 8'd0;
        scan_tmr = 8'd0;
        row_n    = 32'hFFFF_FFFE;
        for (i = 0; i < 32; i = i + 1) key_map[i] = 8'd0;
    end

    wire [7:0] nxt = (row_idx == 8'd31) ? 8'd0 : (row_idx + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            row_idx  <= 8'd0;
            scan_tmr <= 8'd0;
            row_n    <= 32'hFFFF_FFFE;
