            if (scan_tmr == DWELL - 8'd1) begin
                scan_tmr <= 8'd0;
                key_map[row_idx[4:0]] <= ~col_in;
                row_idx  <= nxt;
                row_n    <= ~(32'b1 << nxt);
            end else begin
                scan_tmr <= scan_tmr + 8'd1;
            end
        end
    end

    assign key_map_out = key_map[row_idx[4:0]];

    reg pv = 1'b0;
    reg rst_q = 1'b1;
    always @(posedge clk) begin
        pv    <= 1'b1;
        rst_q <= rst;
    end

