        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            fin_q <= 1'b0;
            cnt <= 5'd0;
            sumA <= 16'd0;
            sumB <= 16'd0;
