            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (in_valid) begin
                        phase <= RUN;
                        started_seen <= 1'b1;
                        cnt <= 5'd1;
                        sumA <= fold_first[15:0];
                        sumB <= fold_first[31:16];
                    end
