                S_BANDCAL: begin
                    cnt <= 16'd0;
                    if (band_ok) begin
                        state <= S_CLOSE;
                    end else begin
                        band <= band + 4'd1;
                    end
                end
                S_CLOSE: begin
                    cnt <= cnt + 16'd1;
                    if (cnt >= 16'd200)
                        state <= S_LOCKWAIT;
