module udp_hamming_tx (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         req,
    input  wire [127:0] data_i,
    input  wire         link_down,
    output wire [136:0] code_o,
    output wire         valid_o
);
    reg [127:0] data_q;
    reg [8:0]   chk_q;
    reg [1:0]   step;
    reg [2:0]   cd;
    reg         busy;
    reg [136:0] code_q;
    reg         valid_q;
    reg         pre_r;

    initial begin
        data_q  = 128'd0;
        chk_q   = 9'd0;
        step    = 2'd0;
        cd      = 3'd0;
        busy    = 1'b0;
        code_q  = 137'd0;
        valid_q = 1'b0;
        pre_r   = 1'b1;
    end

    assign code_o  = code_q;
    assign valid_o = valid_q;

    // current 32-bit beat
    wire [31:0] beat = data_q[{step, 5'b00000} +: 32];

    // Hamming contribution of this beat: data bit idx sits at position 129+idx
    reg [8:0] beat_chk;
    reg [5:0] j;
    always @(*) begin
        beat_chk = 9'd0;
        for (j = 6'd0; j < 6'd32; j = j + 6'd1) begin
            if (beat[j[4:0]]) begin
                beat_chk[7:0] = beat_chk[7:0] ^ (8'd129 + {1'b0, step, j[4:0]});
                beat_chk[8]   = ~beat_chk[8];
            end
        end
    end

    wire [8:0] chk_next  = chk_q ^ beat_chk;
    wire       par_final = chk_next[8] ^ (^chk_next[7:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            data_q  <= 128'd0;
            chk_q   <= 9'd0;
            step    <= 2'd0;
            cd      <= 3'd0;
            busy    <= 1'b0;
            code_q  <= 137'd0;
            valid_q <= 1'b0;
        end else if (en) begin
            if (busy) begin
                chk_q <= chk_next;
                step  <= step + 2'd1;
                cd    <= cd - 3'd1;
                if (step == 2'd3) begin
                    code_q  <= {par_final, chk_next[7:0], data_q};
                    valid_q <= 1'b1;
                    busy    <= 1'b0;
                end
            end else if (req) begin
                data_q  <= data_i;
                chk_q   <= 9'd0;
                step    <= 2'd0;
                cd      <= 3'd4;
                busy    <= 1'b1;
                valid_q <= 1'b0;
            end
        end
    end

    // scope register: ignores en
    always @(posedge clk) begin
        if (!rst_n)
            pre_r <= 1'b1;
        else if (link_down)
            pre_r <= 1'b0;
    end

    always @(posedge clk)
        if (pre_r) assert (!(busy && cd == 3'd0));
endmodule

