    localparam [127:0] PAT = "PIN_UART_A15____";

    reg [127:0] mem [0:15];
    reg [3:0] addr = 4'd0;
    reg [1:0] phase = 2'd0;
    reg [6:0] countdown = 7'd0;
    reg win = 1'b0;
    initial fail = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 128'd0;
    end

    assign busy = win;

    wire [5:0] pa = {phase, addr};
    wire [127:0] rd = mem[addr];
    wire [127:0] exp_rd = (phase == 2'd2) ? ~PAT : PAT;
    wire [127:0] wr = (phase == 2'd1) ? ~PAT : PAT;
    wire do_read = (phase != 2'd0);
    wire do_write = (phase != 2'd3);

    always @(posedge clk) begin
        if (!rst && en && win && do_write)
            mem[addr] <= wr;
    end

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            countdown <= 7'd0;
            addr <= 4'd0;
            phase <= 2'd0;
            fail <= 1'b0;
        end else if (en) begin
            if (!win) begin
                if (start) begin
                    win <= 1'b1;
                    countdown <= 7'd64;
                    addr <= 4'd0;
                    phase <= 2'd0;
                    fail <= 1'b0;
                end
            end else begin
                if (do_read && (rd != exp_rd))
                    fail <= 1'b1;
                {phase, addr} <= pa + 6'd1;
                if (pa == 6'd63) begin
                    win <= 1'b0;
                    countdown <= 7'd0;
                end else begin
                    countdown <= countdown - 7'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    wire cd_zero = (countdown == 7'd0);

    always @(posedge clk) begin
        if (pv && !rst && win && $stable(win))
            assert ($stable(cd_zero));
    end
