module pmod_simd_div (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       req,
    input  wire       req_mode,
    input  wire [7:0] dividend,
    input  wire [7:0] divisor,
    input  wire       cfg_wr,
    output reg        resp_valid,
    output wire [7:0] quotient,
    output wire [7:0] remainder,
    output wire       busy_o
);
    reg       busy = 1'b0;
    reg       mode = 1'b0;
    reg [7:0] prem = 8'd0;
    reg [7:0] dvs  = 8'd0;
    reg [7:0] quo  = 8'd0;
    reg [7:0] cnt  = 8'd0;
    reg [7:0] dl   = 8'd0;
    reg       pre  = 1'b1;
    initial resp_valid = 1'b0;

    assign quotient  = quo;
    assign remainder = prem;
    assign busy_o    = busy;

    wire [7:0] w_cur = mode     ? 8'd4 : 8'd8;
    wire [7:0] w_req = req_mode ? 8'd4 : 8'd8;
    wire       last  = (cnt == (w_cur - 8'd1));

    // 8-bit lane
    wire [8:0] r8  = {prem, quo[7]};
    wire       ge8 = (r8 >= {1'b0, dvs});
    wire [8:0] s8  = r8 - {1'b0, dvs};

    // two 4-bit lanes
    wire [4:0] rlo  = {prem[3:0], quo[3]};
    wire       gelo = (rlo >= {1'b0, dvs[3:0]});
    wire [4:0] slo  = rlo - {1'b0, dvs[3:0]};
    wire [4:0] rhi  = {prem[7:4], quo[7]};
    wire       gehi = (rhi >= {1'b0, dvs[7:4]});
    wire [4:0] shi  = rhi - {1'b0, dvs[7:4]};

    wire [7:0] prem_n = mode ? {(gehi ? shi[3:0] : rhi[3:0]), (gelo ? slo[3:0] : rlo[3:0])}
                             : (ge8 ? s8[7:0] : r8[7:0]);
    wire [7:0] quo_n  = mode ? {quo[6:4], gehi, quo[2:0], gelo}
                             : {quo[6:0], ge8};

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                busy <= 1'b0;
                cnt  <= 8'd0;
                dl   <= 8'd0;
                mode <= 1'b0;
                pre  <= 1'b1;
                resp_valid <= 1'b0;
            end else begin
                resp_valid <= 1'b0;
                if (!busy) begin
                    if (cfg_wr)
                        pre <= 1'b0;
                    if (req) begin
                        prem <= 8'd0;
                        quo  <= dividend;
                        dvs  <= divisor;
                        mode <= req_mode;
                        cnt  <= 8'd0;
                        dl   <= w_req;
                        busy <= 1'b1;
                    end
                end else begin
                    prem <= prem_n;
                    quo  <= quo_n;
                    cnt  <= cnt + 8'd1;
                    dl   <= dl - 8'd1;
                    if (last) begin
                        busy <= 1'b0;
                        resp_valid <= 1'b1;
                    end
                end
            end
        end
    end

    // A1: countdown never expires while an operation is outstanding
    always @(*)
        if (pre && busy)
            assert (dl != 8'd0);

    // A2: deadline and completion coincide
    always @(*)
        if (pre && busy && dl == 8'd1)
            assert (cnt == (mode ? 8'd3 : 8'd7));
endmodule

