module polar_sc_result_dec (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire abort,
    input wire wr,
    input wire [2:0] wr_addr,
    input wire [127:0] llr_in,
    output wire [7:0] o_result,
    output wire o_done
);
    localparam [7:0] FROZEN = 8'b0001_0111;
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, DECODE = 2'd2, DONE = 2'd3;

    reg [127:0] llr_mem [0:7];
    reg [7:0] ps;
    reg [7:0] dec;
    reg [2:0] leaf_idx;
    reg [1:0] phase;
    reg armed_seen;
    reg started_seen;
    reg pre_abort;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) llr_mem[i] = 128'd0;
        ps = 8'd0;
        dec = 8'd0;
        leaf_idx = 3'd0;
        phase = IDLE;
        armed_seen = 1'b0;
        started_seen = 1'b0;
        pre_abort = 1'b1;
    end

    wire [127:0] cur_word = llr_mem[leaf_idx];
    wire [7:0] la = cur_word[7:0];
    wire [7:0] lb = cur_word[15:8];
    wire [6:0] min_mag = (la[6:0] < lb[6:0]) ? la[6:0] : lb[6:0];
    wire [7:0] f_llr = {la[7] ^ lb[7], min_mag};
    wire [2:0] prev_idx = leaf_idx - 3'd1;
    wire u_prev = ps[prev_idx];
    wire [7:0] g_llr = u_prev ? (lb - la) : (lb + la);
    wire [7:0] leaf_llr = leaf_idx[0] ? g_llr : f_llr;
    wire bit_hat = FROZEN[leaf_idx] ? 1'b0 : leaf_llr[7];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_abort <= 1'b1;
            leaf_idx <= 3'd0;
            ps <= 8'd0;
            dec <= 8'd0;
        end else if (en) begin
            if (wr && phase != DECODE)
                llr_mem[wr_addr] <= llr_in;
            if (abort) begin
                phase <= IDLE;
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            phase <= ARMED;
                            armed_seen <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
                            phase <= DECODE;
                            started_seen <= 1'b1;
                            leaf_idx <= 3'd0;
                            ps <= 8'd0;
                        end
                    end
                    DECODE: begin
                        dec[leaf_idx] <= bit_hat;
                        ps[leaf_idx] <= bit_hat;
                        llr_mem[leaf_idx] <= {cur_word[127:16], f_llr, g_llr};
                        leaf_idx <= leaf_idx + 3'd1;
                        if (leaf_idx == 3'd7)
                            phase <= DONE;
                    end
                    DONE: begin
                        if (arm) begin
                            phase <= ARMED;
                            started_seen <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_result = dec;
    assign o_done = (phase == DONE);

    always @(posedge clk)
        if (pre_abort && phase == 2'd3)
            assert (started_seen && armed_seen);
