                count   <= count + 64'd1;
                empty_q <= 1'b0;
                if (count == 64'd15)
                    full_q <= 1'b1;
                if (count + 64'd1 == af_thr)
                    afull_q <= 1'b1;
                if (count == ae_thr)
                    aempty_q <= 1'b0;
