                count <= count - 64'd1;
                if (count == 64'd1)
                    empty_q <= 1'b1;
                if (count == 64'd16)
                    full_q <= 1'b0;
                if (count == af_thr)
                    afull_q <= 1'b0;
                if (count - 64'd1 == ae_thr)
                    aempty_q <= 1'b1;
            end
        end
