    reg [1:0] phase;
    reg latch_a, latch_b;
    reg sync_a, sync_b;
    reg own_a, own_b;
    reg win;
    reg [31:0] n_grants;

    initial phase = IDLE;
    initial latch_a = 1'b0;
    initial latch_b = 1'b0;
    initial sync_a = 1'b0;
    initial sync_b = 1'b0;
    initial own_a = 1'b0;
    initial own_b = 1'b0;
    initial win = 1'b0;
    initial n_grants = 32'd0;

    // cross-coupled set terms: each side inhibited by the other, A wins ties
    wire set_a = req_a & ~latch_b;
    wire set_b = req_b & ~latch_a & ~set_a;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            latch_a <= 1'b0;
            latch_b <= 1'b0;
            sync_a <= 1'b0;
            sync_b <= 1'b0;
            own_a <= 1'b0;
            own_b <= 1'b0;
            win <= 1'b0;
            n_grants <= 32'd0;
