module ifu_align_buf (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_rvalid,
    input  wire [127:0] i_rdata,
    input  wire         i_pop,
    output wire         o_req,
    output wire [31:0]  o_fetch_addr,
    output wire         o_valid,
    output wire [127:0] o_line,
    output wire [31:0]  o_pc
);
    reg [127:0] abuf [0:7];
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [3:0]  count = 4'd0;
    reg [31:0] fetch_ptr = 32'd0;
    reg [31:0] head_pc = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            abuf[i] = 128'd0;
    end

    wire [3:0] occ   = wptr - rptr;
    wire       full  = (occ == 4'd8);
    wire       empty = (occ == 4'd0);
    wire push_ok = i_ce && i_rvalid && !full;
    wire pop_ok  = i_ce && i_pop && !empty;

    always @(posedge clk) begin
        if (push_ok) begin
            abuf[wptr[2:0]] <= i_rdata;
            wptr            <= wptr + 4'd1;
            fetch_ptr       <= fetch_ptr + 32'd16;
        end
        if (pop_ok) begin
            rptr    <= rptr + 4'd1;
            head_pc <= head_pc + 32'd16;
        end
        case ({push_ok, pop_ok})
            2'b10:   count <= count + 4'd1;
            2'b01:   count <= count - 4'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (push_ok)
            armed <= 1'b1;

    always @(posedge clk)
        pv <= 1'b1;

    assign o_req        = !full;
    assign o_fetch_addr = fetch_ptr;
    assign o_valid      = !empty;
    assign o_line       = abuf[rptr[2:0]];
    assign o_pc         = head_pc;

    always @(posedge clk)
        if (armed && pv && $stable(rptr))
            assert ($stable(head_pc) && (count <= 4'd8));
