module backoff_ctrl (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire req,
    input wire col,
    input wire [63:0] rnd,
    output wire tx_active,
    output wire busy,
    output wire [63:0] o_attempts
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_WAIT = 2'd1;
    localparam [1:0] S_TX   = 2'd2;
    localparam [63:0] MAXA    = 64'd3;
    localparam [63:0] BUDGET0 = 64'd18;

    reg [1:0]  state;
    reg        pending;
    reg [63:0] attempts;
    reg [63:0] slot;
    reg [63:0] budget;

    initial begin
        state = S_IDLE;
        pending = 1'b0;
        attempts = 64'd0;
        slot = 64'd0;
        budget = 64'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            pending <= 1'b0;
            attempts <= 64'd0;
            slot <= 64'd0;
            budget <= 64'd0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state <= S_TX;
                        pending <= 1'b1;
                        attempts <= 64'd0;
                        slot <= 64'd0;
                        budget <= BUDGET0;
                    end
                end
                S_WAIT: begin
                    budget <= budget - 64'd1;
                    if (slot == 64'd0)
                        state <= S_TX;
                    else
                        slot <= slot - 64'd1;
                end
                S_TX: begin
                    budget <= budget - 64'd1;
                    if (!col) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else if (attempts >= MAXA) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else begin
                        attempts <= attempts + 64'd1;
                        slot <= rnd & ((64'd1 << (attempts + 64'd1)) - 64'd1);
                        state <= S_WAIT;
                    end
                end
                default: begin
                    state <= S_IDLE;
                    pending <= 1'b0;
                end
            endcase
        end
    end

    assign tx_active = (state == S_TX);
    assign busy = pending;
    assign o_attempts = attempts;

    always @(posedge clk)
        if (pending)
            assert (budget != 64'd0);
endmodule


