module welch_spectral_avg (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [7:0]  mag,
    input  wire        dump,
    input  wire [6:0]  rd_addr,
    output wire [23:0] rd_data,
    output wire        avg_done
