    assign rd_data  = acc[rd_addr] >> 3;
    assign avg_done = armed && (samples_left == 11'd0);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Before the first dump, the frame count never exceeded 8
    always @(posedge clk)
        if (pv && armed)
            assert ($past(frame_cnt) <= 8'd8);
