    function [31:0] clz32;
        input [31:0] v;
        integer i;
        reg found;
        begin
            clz32 = 32'd32;
            found = 1'b0;
            for (i = 31; i >= 0; i = i - 1) begin
                if (!found && v[i]) begin
                    clz32 = 31 - i;
                    found = 1'b1;
                end
            end
        end
    endfunction

