                phase <= 2'd0;
                pre_r <= 1'b0;
            end else begin
                case (phase)
                    2'd0: if (i_load) begin
                        dest <= i_dest;
                        field <= i_field;
                        off <= i_off;
                        len <= (i_len > 7'd64) ? 7'd64 : i_len;
                        phase <= 2'd1;
                        armed_seen <= 1'b1;
