    wire j = start && !busy;
    wire k = busy && (work == 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            work  <= 64'd0;
            timer <= 64'd0;
        end else if (ce) begin
            // gated JK latch: set / reset / invert while enabled, hold otherwise
            case ({j, k})
                2'b10:   busy <= 1'b1;
                2'b01:   busy <= 1'b0;
                2'b11:   busy <= ~busy;
                default: busy <= busy;
            endcase
            if (j) begin
                work  <= LEN;
                timer <= LEN + 64'd1;
            end else if (busy) begin
                if (work != 64'd0)
                    work <= work - 64'd1;
                timer <= timer - 64'd1;
            end
        end
    end

    // bounded response: countdown never expires while request outstanding
    always @(posedge clk)
        assert (!(busy && timer == 64'd0));
