module tb_drv_demux (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire         i_req,
    input  wire [3:0]   i_sel,
    input  wire [15:0]  i_data,
    output wire [255:0] o_bus,
    output wire         o_busy
);
    localparam [15:0] K = 16'd8;

    reg [3:0]   sel_r;
    reg [15:0]  data_r;
    reg [255:0] out_q;
    reg         pending;
    reg [15:0]  cnt;
    reg [15:0]  ph;

    initial sel_r   = 4'd0;
    initial data_r  = 16'd0;
    initial out_q   = 256'd0;
    initial pending = 1'b0;
    initial cnt     = 16'd0;
    initial ph      = 16'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            sel_r   <= 4'd0;
            data_r  <= 16'd0;
            out_q   <= 256'd0;
            pending <= 1'b0;
            cnt     <= 16'd0;
            ph      <= 16'd0;
        end else if (i_ce) begin
            if (!pending) begin
                if (i_req) begin
                    pending <= 1'b1;
                    sel_r   <= i_sel;
                    data_r  <= i_data;
                    cnt     <= K;
                    ph      <= 16'd0;
                end
            end else begin
                if (ph == K - 16'd1) begin
                    out_q[sel_r*16 +: 16] <= data_r;
                    pending <= 1'b0;
                    cnt     <= 16'd0;
                    ph      <= 16'd0;
                end else begin
                    ph  <= ph + 16'd1;
                    cnt <= cnt - 16'd1;
                end
            end
        end
    end

    assign o_bus  = out_q;
    assign o_busy = pending;

    assert property (!pending || cnt != 16'd0);
endmodule

