    wire [63:0] d0 = (i_err_sgn ^ hist[0]) ? (~mu + 64'd1) : mu;
    wire [63:0] d1 = (i_err_sgn ^ hist[1]) ? (~mu + 64'd1) : mu;

    always @(posedge clk) begin
        if (rst) begin
            coef0 <= 64'd0;
            coef1 <= 64'd0;
            hist <= 2'b00;
            hist_cnt <= 2'd0;
            upd_cnt <= 64'd0;
            phase <= P_IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_mu_wr) begin
                mu <= i_mu;
                q_seen <= 1'b1;
            end
            hist <= {hist[0], i_dec};
            if (hist_cnt != 2'd2)
                hist_cnt <= hist_cnt + 2'd1;
            case (phase)
                P_IDLE: begin
                    if (hist_cnt == 2'd2) begin
                        phase <= P_ARMED;
                        arm_seen <= 1'b1;
                    end
