module fb_scanout (
    input  wire        clk,
    input  wire        start,
    input  wire        ce,
    input  wire [31:0] base_in,
    output wire [31:0] o_addr,
    output wire        o_rd,
    output wire        o_eol,
    output wire        o_eof
);
    // 32 pixels per line, 32 lines per frame, raster-order scanout
    reg        armed    = 1'b0;
    reg [31:0] base     = 32'd0;
    reg [31:0] cur_addr = 32'd0;
    reg [31:0] line     = 32'd0;
    reg [31:0] px       = 32'd0;

    wire adv = armed && ce;
    wire eol = (px == 32'd31);
    wire eof = eol && (line == 32'd31);

    assign o_addr = cur_addr;
    assign o_rd   = adv;
    assign o_eol  = adv && eol;
    assign o_eof  = adv && eof;

    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        if (adv) begin
            if (eof) begin
                base     <= base_in;
                cur_addr <= base_in;
                line     <= 32'd0;
                px       <= 32'd0;
            end else if (eol) begin
                px       <= 32'd0;
                line     <= line + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end else begin
                px       <= px + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end
        end
    end

    // after scanout has been started, the fetch address stays inside the frame
    always @(posedge clk)
        if (armed)
            assert (cur_addr - base <= 32'd1023);
