    input wire ce,
    input wire req,
    input wire [1:0] op,
    input wire [1:0] lsz,
    input wire [63:0] a_in,
    input wire [63:0] b_in,
    output wire busy_o,
    output wire [63:0] result,
    output wire [7:0] lane_flags
);
    localparam [63:0] K = 64'd8;
    reg busy = 1'b0;
    reg [63:0] cd = 64'd0;
    reg [63:0] pos = 64'd0;
    reg [63:0] a_r = 64'd0;
    reg [63:0] b_r = 64'd0;
    reg [63:0] res = 64'd0;
    reg [7:0] flg = 8'd0;
    reg [1:0] op_r = 2'd0;
    reg [1:0] lsz_r = 2'd0;
    reg carry = 1'b0;

    wire [2:0] p = pos[2:0];
    wire lane_lo = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & ~p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b00)) | (p == 3'd0);
    wire lane_hi = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b11)) | (p == 3'd7);
    wire [7:0] ab = a_r[{p, 3'b000} +: 8];
    wire [7:0] bb = b_r[{p, 3'b000} +: 8];
    wire sub = (op_r == 2'd1);
    wire arith = ~op_r[1];
    wire cin = lane_lo ? sub : carry;
    wire [8:0] sum = {1'b0, ab} + {1'b0, bb ^ {8{sub}}} + {8'd0, cin};
    reg [7:0] r8;
    always @(*) begin
        case (op_r)
            2'd0, 2'd1: r8 = sum[7:0];
            2'd2: r8 = ab & bb;
            default: r8 = ab ^ bb;
        endcase
    end

    always @(posedge clk) begin
        if (ce) begin
            if (busy) begin
                res[{p, 3'b000} +: 8] <= r8;
                flg[p] <= lane_hi & arith & sum[8];
                carry <= sum[8];
                cd <= cd - 64'd1;
                if (pos == 64'd7) begin
                    busy <= 1'b0;
                    pos <= 64'd0;
                end else begin
                    pos <= pos + 64'd1;
                end
