module trace_buffer (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_trig,
    input  wire        i_flush,
    input  wire [63:0] i_sample,
    input  wire [5:0]  i_raddr,
    output wire [63:0] o_rdata,
    output wire        o_done,
    output wire [5:0]  o_trig_pos
);
    localparam [63:0] POST     = 64'd12;
    localparam [5:0]  DEPTH_M1 = 6'd47;

    reg [63:0] mem [0:47];
    reg [5:0]  wptr       = 6'd0;
    reg [5:0]  trig_pos   = 6'd0;
    reg        triggered  = 1'b0;
    reg        done       = 1'b0;
    reg [63:0] remaining  = 64'd0;
    reg [63:0] post_count = 64'd0;
    reg        no_abort   = 1'b1;
    reg        pv         = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) mem[i] = 64'd0;
    end

    wire [5:0] wptr_nxt = (wptr == DEPTH_M1) ? 6'd0 : wptr + 6'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_flush) begin
                triggered  <= 1'b0;
                done       <= 1'b0;
                remaining  <= 64'd0;
                post_count <= 64'd0;
                no_abort   <= 1'b0;
            end else if (!done) begin
                mem[wptr] <= i_sample;
                wptr      <= wptr_nxt;
                if (!triggered) begin
                    if (i_trig) begin
                        triggered  <= 1'b1;
                        trig_pos   <= wptr;
                        remaining  <= POST;
                        post_count <= 64'd0;
                    end
                end else begin
                    remaining  <= remaining - 64'd1;
                    post_count <= post_count + 64'd1;
                    if (post_count == POST - 64'd1)
                        done <= 1'b1;
                end
            end
        end
    end

    assign o_rdata    = (i_raddr <= DEPTH_M1) ? mem[i_raddr] : 64'd0;
    assign o_done     = done;
    assign o_trig_pos = trig_pos;

    wire expired = (remaining == 64'd0);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && no_abort && $rose(expired))
            assert (done);
endmodule

