module act_gate_counter (
    input wire clk,
    input wire ce,
    input wire gate,
    input wire evt,
    output reg [7:0] result
);
    reg       gate_q = 1'b0;
    reg       evt_q  = 1'b0;
    reg [7:0] cnt    = 8'd0;
    reg       win    = 1'b0;
    reg       seen   = 1'b0;
    initial result = 8'd0;

    wire edge_det = evt && !evt_q;

    always @(posedge clk) begin
        if (ce) begin
            gate_q <= gate;
            evt_q  <= evt;
            if (gate && !gate_q) begin
                win  <= 1'b1;
                seen <= 1'b0;
            end else if (gate && gate_q) begin
                if (edge_det) begin
                    seen <= 1'b1;
                    if (cnt != 8'hFF)
                        cnt <= cnt + 8'd1;
                end
            end else if (!gate && gate_q) begin
                result <= cnt;
                cnt    <= 8'd0;
                win    <= 1'b0;
            end
        end
    end

    assert property (!win || seen || cnt == 8'd0);
endmodule

