module fracn_mash_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        clear,
    input  wire [31:0] int_in,
    input  wire [31:0] frac_in,
    input  wire [31:0] len_in,
    output reg  [31:0] div_ratio,
    output wire        busy
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_RUN   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    reg [1:0]  phase;
    reg        win;
    reg        seen_arm;
    reg        seen_start;
    reg [31:0] int_set;
    reg [31:0] frac_set;
    reg [31:0] len_set;
    reg [31:0] remaining;
    reg [31:0] acc1;
    reg [31:0] acc2;
    reg        c2_d;

    initial phase      = P_IDLE;
    initial win        = 1'b0;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial int_set    = 32'd0;
    initial frac_set   = 32'd0;
    initial len_set    = 32'd0;
    initial remaining  = 32'd0;
    initial acc1       = 32'd0;
    initial acc2       = 32'd0;
    initial c2_d       = 1'b0;
    initial div_ratio  = 32'd0;

    // two-stage MASH 1-1 sigma-delta modulator
    wire [32:0] sum1 = {1'b0, acc1} + {1'b0, frac_set};
    wire [32:0] sum2 = {1'b0, acc2} + {1'b0, sum1[31:0]};
    wire        c1   = sum1[32];
    wire        c2   = sum2[32];

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            win        <= 1'b0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            int_set    <= 32'd0;
            frac_set   <= 32'd0;
            len_set    <= 32'd0;
            remaining  <= 32'd0;
            acc1       <= 32'd0;
            acc2       <= 32'd0;
            c2_d       <= 1'b0;
            div_ratio  <= 32'd0;
        end else if (ce) begin
            case (phase)
                P_IDLE: if (arm) begin
                    int_set    <= int_in;
                    frac_set   <= frac_in;
                    len_set    <= len_in;
                    acc1       <= 32'd0;
                    acc2       <= 32'd0;
                    c2_d       <= 1'b0;
                    phase      <= P_ARMED;
                    win        <= 1'b1;
                    seen_arm   <= 1'b1;
                    seen_start <= 1'b0;
                end
                P_ARMED: if (start) begin
                    remaining  <= len_set;
                    phase      <= P_RUN;
                    seen_start <= 1'b1;
                end
                P_RUN: begin
                    acc1      <= sum1[31:0];
                    acc2      <= sum2[31:0];
                    c2_d      <= c2;
                    div_ratio <= int_set + {31'd0, c1} + {31'd0, c2} - {31'd0, c2_d};
                    if (remaining == 32'd0)
                        phase <= P_DONE;
                    else
                        remaining <= remaining - 32'd1;
                end
                P_DONE: if (clear) begin
                    phase      <= P_IDLE;
                    win        <= 1'b0;
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    assign busy = (phase == P_RUN);

    // chain precedence inside the arm..clear window: finish implies start and arm happened
    always @(posedge clk)
        if (win && phase == P_DONE)
            assert (seen_arm && seen_start);
endmodule

