module swd_target_port (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        swdio_in,
    output wire        swdio_oe,
    output wire        swdio_out,
    output wire [31:0] o_wdata,
    output wire        o_busy
);
    localparam [2:0] PH_IDLE = 3'd0;
    localparam [2:0] PH_REQ  = 3'd1;
    localparam [2:0] PH_TRN1 = 3'd2;
    localparam [2:0] PH_ACK  = 3'd3;
    localparam [2:0] PH_DATA = 3'd4;
    localparam [2:0] PH_TRN2 = 3'd5;
    localparam [31:0] K = 32'd38;

    reg [2:0]  phase;
    reg [7:0]  req_sr;
    reg [31:0] bitcnt;
    reg [31:0] data_sr;
    reg        par_acc;
    reg        rnw_q;
    reg        outstanding;
    reg [31:0] countdown;
    reg        no_err;
    reg [31:0] wdata;

    initial begin
        phase = PH_IDLE;
        req_sr = 8'd0;
        bitcnt = 32'd0;
        data_sr = 32'd0;
        par_acc = 1'b0;
        rnw_q = 1'b0;
        outstanding = 1'b0;
        countdown = 32'd0;
        no_err = 1'b1;
        wdata = 32'd0;
    end

    wire [7:0] req_full = {swdio_in, req_sr[7:1]};
    wire req_ok = req_full[0] && !req_full[6] && req_full[7] &&
                  (req_full[5] == ^req_full[4:1]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE;
            req_sr <= 8'd0;
            bitcnt <= 32'd0;
            data_sr <= 32'd0;
            par_acc <= 1'b0;
            rnw_q <= 1'b0;
            outstanding <= 1'b0;
            countdown <= 32'd0;
            no_err <= 1'b1;
            wdata <= 32'd0;
        end else if (ce) begin
            case (phase)
                PH_IDLE: begin
                    if (swdio_in) begin
                        req_sr <= req_full;
                        bitcnt <= 32'd1;
                        phase <= PH_REQ;
                    end
                end
                PH_REQ: begin
                    req_sr <= req_full;
                    if (bitcnt == 32'd7) begin
                        bitcnt <= 32'd0;
                        if (req_ok) begin
                            phase <= PH_TRN1;
                            outstanding <= 1'b1;
                            countdown <= K;
                            rnw_q <= req_full[2];
                        end else begin
                            phase <= PH_IDLE;
                            no_err <= 1'b0;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_TRN1: begin
                    phase <= PH_ACK;
                    bitcnt <= 32'd0;
                    countdown <= countdown - 32'd1;
                    par_acc <= 1'b0;
                    if (rnw_q) data_sr <= wdata;
                    else data_sr <= 32'd0;
                end
                PH_ACK: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd2) begin
                        phase <= PH_DATA;
                        bitcnt <= 32'd0;
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_DATA: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd32) begin
                        phase <= PH_TRN2;
                        bitcnt <= 32'd0;
                        if (!rnw_q) begin
                            if (par_acc != swdio_in) no_err <= 1'b0;
                            else wdata <= data_sr;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                        if (rnw_q) begin
                            par_acc <= par_acc ^ data_sr[0];
                            data_sr <= {1'b0, data_sr[31:1]};
                        end else begin
                            par_acc <= par_acc ^ swdio_in;
                            data_sr <= {swdio_in, data_sr[31:1]};
