                    busy        <= 1'b1;
                    in_reset    <= 1'b0;
                    shift       <= {8'd0, color};
                    bit_cnt     <= N_BITS;
                    pulse_timer <= 32'd0;
                    gap_cnt     <= 32'd0;
                    deadline    <= K;
