                gain <= gain_next;
                hist[step[2:0]] <= gain;
                cd   <= cd - 64'd1;
                step <= step + 64'd1;
                if (step == 64'd7)
                    pend <= 1'b0;
            end
            if (acc && s_tuser)
                win <= 1'b1;
            else if (eof)
                win <= 1'b0;
        end
    end

