    input wire [15:0] in_data,
    input wire drain,
    output reg out_valid,
    output reg [15:0] out_val,
    output reg [15:0] out_cnt
);
    localparam [15:0] MAX = 16'd24;

    reg [15:0] cur;
    reg [15:0] cnt;
    reg [15:0] dl;
    reg busy;
    reg pre_drain;
    reg pv;

    initial begin
        cur = 16'd0;
        cnt = 16'd0;
        dl = 16'd0;
        busy = 1'b0;
        pre_drain = 1'b1;
        pv = 1'b0;
        out_valid = 1'b0;
        out_val = 16'd0;
        out_cnt = 16'd0;
    end

