    always @(posedge clk) begin
        if (rst) begin
            cur <= 16'd0;
            cnt <= 16'd0;
            dl <= 16'd0;
            busy <= 1'b0;
            pre_drain <= 1'b1;
            out_valid <= 1'b0;
            out_val <= 16'd0;
            out_cnt <= 16'd0;
        end else if (en) begin
            out_valid <= 1'b0;
            if (drain) begin
                pre_drain <= 1'b0;
                if (busy) begin
                    out_valid <= 1'b1;
                    out_val <= cur;
                    out_cnt <= cnt;
                    busy <= 1'b0;
                    cnt <= 16'd0;
                    dl <= 16'd0;
                end
            end else if (in_valid) begin
                if (!busy) begin
                    cur <= in_data;
                    cnt <= 16'd1;
                    dl <= MAX;
                    busy <= 1'b1;
