module hbpf_breathe (
    input  wire clk,
    input  wire en,
    output wire led
);
    localparam [63:0] STEP      = 64'h0000000100000000;
    localparam [63:0] NSTEPS    = 64'h0000000080000000;
    localparam [63:0] MAX       = 64'h8000000000000000;
    localparam [63:0] PRESC_MAX = 64'd999;

    reg [63:0] pwm_cnt  = 64'd0;
    reg [63:0] presc    = 64'd0;
    reg [63:0] pos      = 64'd0;
    reg [63:0] duty     = 64'd0;
    reg [63:0] headroom = 64'h8000000000000000;
    reg        dir        = 1'b1;
    reg        first_rise = 1'b1;

    assign led = (pwm_cnt < duty);

    wire tick = en && (presc == PRESC_MAX);

    always @(posedge clk) begin
        if (en) begin
            pwm_cnt <= pwm_cnt + 64'd1;
            if (presc == PRESC_MAX)
                presc <= 64'd0;
            else
                presc <= presc + 64'd1;
        end
        if (tick) begin
            if (dir) begin
                if (pos < NSTEPS) begin
                    pos      <= pos + 64'd1;
                    duty     <= duty + STEP;
                    headroom <= headroom - STEP;
                end else begin
                    dir        <= 1'b0;
                    first_rise <= 1'b0;
                end
            end else begin
                if (pos > 64'd0) begin
                    pos      <= pos - 64'd1;
                    duty     <= duty - STEP;
                    headroom <= headroom + STEP;
                end else begin
                    dir <= 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (first_rise)
            assert (duty <= MAX);

    always @(posedge clk)
        if (first_rise)
            assert (headroom <= MAX);
endmodule

