    reg [7:0]   refcnt;
    reg         root_on;
    reg         pend;
    reg [7:0]   prog;
    reg [7:0]   cd;
    reg         first_n;
    reg         pv;

    initial dom_on  = 128'd0;
    initial refcnt  = 8'd0;
    initial root_on = 1'b0;
    initial pend    = 1'b0;
    initial prog    = 8'd0;
    initial cd      = 8'd0;
    initial first_n = 1'b1;
    initial pv      = 1'b0;

