module mmio_router_tmo (
    input wire clk,
    input wire en,
    input wire cfg_we,
    input wire [5:0] cfg_idx,
    input wire [63:0] cfg_base,
    input wire [63:0] cfg_limit,
    input wire req,
    input wire [63:0] req_addr,
    input wire win_clr,
    output wire o_busy,
    output wire o_win,
    output wire [5:0] o_sel
);
    localparam [63:0] K = 64'd16;

    reg [63:0] base  [0:63];
    reg [63:0] limit [0:63];
    reg        busy;
    reg        win;
    reg [5:0]  sel;
    reg [63:0] cnt;
    reg [63:0] age;

    integer i;
    initial begin
        busy = 1'b0;
        win  = 1'b0;
        sel  = 6'd0;
        cnt  = 64'd0;
        age  = 64'd0;
        for (i = 0; i < 64; i = i + 1) begin
            base[i]  = 64'd0;
            limit[i] = 64'd0;
        end
    end

    reg       hit;
    reg [5:0] hidx;
    integer j;
    always @(*) begin
        hit  = 1'b0;
        hidx = 6'd0;
        for (j = 63; j >= 0; j = j - 1) begin
            if ((base[j] <= req_addr) && (req_addr <= limit[j])) begin
                hit  = 1'b1;
                hidx = j[5:0];
            end
        end
    end

    wire accept = req && hit && !busy;

    always @(posedge clk) begin
        if (en) begin
            if (cfg_we) begin
                base[cfg_idx]  <= cfg_base;
                limit[cfg_idx] <= cfg_limit;
            end
            if (win_clr)
                win <= 1'b0;
            else if (accept)
                win <= 1'b1;
            if (busy) begin
                if (age == K - 64'd1) begin
                    busy <= 1'b0;
                    cnt  <= 64'd0;
                    age  <= 64'd0;
                end else begin
                    cnt <= cnt - 64'd1;
                    age <= age + 64'd1;
                end
            end else if (accept) begin
                busy <= 1'b1;
                sel  <= hidx;
                cnt  <= K;
                age  <= 64'd0;
            end
        end
    end

    assign o_busy = busy;
    assign o_win  = win;
    assign o_sel  = sel;

    always @(posedge clk)
        if (win && busy)
            assert (cnt != 64'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cnt <= K);
endmodule


