module dbg_failover_mux (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [7:0] pri_data,
    input  wire [7:0] bak_data,
    input  wire       pri_fault,
    input  wire       pri_ok,
    output wire [7:0] out_data
);
    reg [7:0] health     = 8'd0;
    reg       arm_f      = 1'b0;
    reg       start_f    = 1'b0;
    reg       fin_f      = 1'b0;
    reg       active_src = 1'b0;
    reg       pv         = 1'b0;

    assign out_data = active_src ? bak_data : pri_data;

    always @(posedge clk) begin
        if (!rst_n) begin
            health     <= 8'd0;
            arm_f      <= 1'b0;
            start_f    <= 1'b0;
            fin_f      <= 1'b0;
            active_src <= 1'b0;
        end else if (en) begin
            if (pri_ok && fin_f && active_src) begin
                health     <= 8'd0;
                arm_f      <= 1'b0;
                start_f    <= 1'b0;
                fin_f      <= 1'b0;
                active_src <= 1'b0;
            end else begin
                if (pri_fault && health != 8'hFF)
                    health <= health + 8'd1;
                if (health >= 8'd3 && !arm_f)
                    arm_f <= 1'b1;
                if (arm_f && pri_fault && !start_f)
                    start_f <= 1'b1;
                if (start_f && !fin_f)
                    fin_f <= 1'b1;
                if (start_f && arm_f && !active_src)
                    active_src <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $stable(fin_f))
            assert ($stable(active_src));
endmodule

