    output reg [4:0] spare_sel,
    output reg [63:0] row_out
);
    reg [63:0] fuse_addr [0:15];
    reg [15:0] fuse_en;
    reg [63:0] lat_addr;
    reg busy;
    reg [4:0] idx;
    reg [63:0] cnt;
    reg hit;
    reg [3:0] hit_slot;
    reg pre_ev;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fuse_addr[i] = 64'd0;
    end
    initial fuse_en = 16'd0;
    initial lat_addr = 64'd0;
    initial busy = 1'b0;
    initial idx = 5'd0;
    initial cnt = 64'd0;
    initial hit = 1'b0;
    initial hit_slot = 4'd0;
    initial pre_ev = 1'b1;
    initial spare_sel = 5'd0;
    initial row_out = 64'd0;

    // combinational compare of the current 4-entry window
    reg win_hit;
    reg [3:0] win_slot;
    reg [3:0] s;
    integer k;
    always @(*) begin
        win_hit = 1'b0;
        win_slot = 4'd0;
        s = 4'd0;
        for (k = 3; k >= 0; k = k - 1) begin
            s = idx[3:0] + k;
            if (fuse_en[s] && (fuse_addr[s] == lat_addr)) begin
                win_hit = 1'b1;
                win_slot = s;
            end
        end
    end

    wire fin_hit = hit | win_hit;
    wire [3:0] fin_slot = hit ? hit_slot : win_slot;

    always @(posedge clk) begin
        if (rst) begin
            fuse_en <= 16'd0;
            lat_addr <= 64'd0;
            busy <= 1'b0;
            idx <= 5'd0;
            cnt <= 64'd0;
            hit <= 1'b0;
            hit_slot <= 4'd0;
            pre_ev <= 1'b1;
            spare_sel <= 5'd0;
            row_out <= 64'd0;
        end else if (en) begin
            if (fuse_load) begin
                fuse_addr[fuse_idx] <= fuse_val;
                fuse_en[fuse_idx] <= 1'b1;
            end
            if (fuse_reload) begin
                idx <= 5'd0;
                pre_ev <= 1'b0;
            end else if (busy) begin
                if (win_hit && !hit) begin
                    hit <= 1'b1;
                    hit_slot <= win_slot;
                end
                if (idx == 5'd12) begin
                    busy <= 1'b0;
                    if (fin_hit) begin
                        spare_sel <= {1'b1, fin_slot};
                        row_out <= 64'hFFFF_FFFF_FFFF_FFF0 | {60'd0, fin_slot};
                    end else begin
                        spare_sel <= 5'd0;
                        row_out <= lat_addr;
                    end
                end else begin
                    idx <= idx + 5'd4;
                    cnt <= cnt - 64'd1;
                end
            end else if (req) begin
                lat_addr <= row_addr;
                busy <= 1'b1;
                idx <= 5'd0;
                cnt <= 64'd4;
                hit <= 1'b0;
            end
        end
    end

    always @(*)
        if (pre_ev && busy)
            assert ((cnt != 64'd0) && (idx < 5'd16));
endmodule

