        input [3:0] idx;
        begin
            case (idx)
                4'd0:  brow = 12'hDC5;
                4'd1:  brow = 12'hB8B;
                4'd2:  brow = 12'h717;
                4'd3:  brow = 12'hE2D;
                4'd4:  brow = 12'hC5B;
                4'd5:  brow = 12'h8B7;
                4'd6:  brow = 12'h16F;
                4'd7:  brow = 12'h2DD;
                4'd8:  brow = 12'h5B9;
                4'd9:  brow = 12'hB71;
                4'd10: brow = 12'h6E3;
                default: brow = 12'hFFE;
            endcase
        end
