    reg [31:0] wr_cnt;
    reg [31:0] cm_cnt;
    reg err;
    reg locked;
    reg pre_lock;
    integer k;

    initial begin
        func_sel = 24'd0;
        wr_cnt = 32'd0;
        cm_cnt = 32'd0;
        err = 1'b0;
        locked = 1'b0;
        pre_lock = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            func_sel <= 24'd0;
            wr_cnt <= 32'd0;
            cm_cnt <= 32'd0;
            err <= 1'b0;
            locked <= 1'b0;
            pre_lock <= 1'b1;
        end else if (en) begin
            if (wr && !locked) begin
                for (k = 0; k < 8; k = k + 1)
                    if (wr_idx == k) func_sel[k*3 +: 3] <= wr_func;
                wr_cnt <= wr_cnt + 32'd1;
                cm_cnt <= cm_cnt + 32'd1;
            end
            err <= err | (wr_cnt != cm_cnt);
            if (lock_req) begin
                locked <= 1'b1;
                pre_lock <= 1'b0;
            end
        end
    end

