                                (fs == 3'd2) ? dac_bit :
                                (fs == 3'd3) ? uart_tx : 1'b0;
        end
    endgenerate

    assign o_err = err;
    assign o_locked = locked;

    always @(posedge clk)
        if (pre_lock)
            assert (!err);
