module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
    output wire         full
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    wire can_pop = (count != 5'd0) &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end else
                        st <= ST_IDLE;
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

