                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (err_valid) begin
                        phase <= CAPT;
                        start_seen <= 1'b1;
                        syn_q <= err_syn;
                        addr_q <= err_addr;
                        type_q <= err_ue;
