    output wire [31:0] exp_o
);
    reg [1:0] phase = 2'd0;
    reg [31:0] mant = 32'd0;
    reg [31:0] exp_r = 32'd0;
    reg [5:0] shamt = 6'd0;
    reg armed_f = 1'b0;
    reg started_f = 1'b0;
    reg q_seen = 1'b0;
    reg pv = 1'b0;

    assign done = (phase == 2'd3);
    assign mant_o = mant;
    assign exp_o = exp_r;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            q_seen <= q_seen | load;
            case (phase)
                2'd0: begin
                    if (arm) begin
                        mant <= din;
                        exp_r <= ein;
                        shamt <= 6'd0;
                        armed_f <= 1'b1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    if (start) begin
                        started_f <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    if (mant[31] || (mant == 32'd0) || (shamt >= 6'd32)) begin
                        exp_r <= exp_r - {26'd0, shamt};
                        phase <= 2'd3;
