                    if (ack) begin
                        armed_f <= 1'b0;
                        started_f <= 1'b0;
                        phase <= 2'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && q_seen && $past(q_seen) && $past(phase) == 2'd3)
            assert ($past(armed_f) && $past(started_f));
