module dfx_quiesce (
    input wire clk,
    input wire rst,
    input wire en,
    input wire issue,
    input wire ret,
    output wire bus_quiet
);
    reg [15:0] out_cnt;
    reg [15:0] iss_cnt;
    reg [15:0] ret_cnt;
    reg        armed;
    initial out_cnt = 16'd0;
    initial iss_cnt = 16'd0;
    initial ret_cnt = 16'd0;
    initial armed   = 1'b0;

    wire iss_ok = issue && (out_cnt != 16'hFFFF);
    wire ret_ok = ret && (out_cnt != 16'd0);

    always @(posedge clk) begin
        if (rst) begin
            out_cnt <= 16'd0;
            iss_cnt <= 16'd0;
            ret_cnt <= 16'd0;
            armed   <= 1'b0;
        end else if (en) begin
            out_cnt <= out_cnt + {15'd0, iss_ok} - {15'd0, ret_ok};
            iss_cnt <= iss_cnt + {15'd0, iss_ok};
            ret_cnt <= ret_cnt + {15'd0, ret_ok};
            armed   <= armed | iss_ok;
        end
    end

    assign bus_quiet = ~(out_cnt[0] | out_cnt[1] | out_cnt[2] | out_cnt[3] |
                         out_cnt[4] | out_cnt[5] | out_cnt[6] | out_cnt[7] |
                         out_cnt[8] | out_cnt[9] | out_cnt[10] | out_cnt[11] |
                         out_cnt[12] | out_cnt[13] | out_cnt[14] | out_cnt[15]);

    always @(posedge clk)
        if (armed && bus_quiet)
            assert (ret_cnt == iss_cnt);
endmodule

