module ppu_clkfail_ctl (
    input  wire clk,
    input  wire rst_n,
    input  wire en,
    input  wire prim_fail,
    output wire use_backup,
    output wire busy,
    output wire fail_flag
);
    localparam [7:0] SETTLE = 8'd200;

    reg       sel_src     = 1'b0;
    reg       switching   = 1'b0;
    reg [7:0] settle_cnt  = 8'd0;
    reg       sticky_fail = 1'b0;
    reg [7:0] fail_cnt    = 8'd0;
    reg       fail_seen   = 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            sel_src     <= 1'b0;
            switching   <= 1'b0;
            settle_cnt  <= 8'd0;
            sticky_fail <= 1'b0;
            fail_cnt    <= 8'd0;
            fail_seen   <= 1'b0;
        end else if (en) begin
            if (prim_fail) begin
                fail_seen   <= 1'b1;
                sticky_fail <= 1'b1;
                if (fail_cnt != 8'd255)
                    fail_cnt <= fail_cnt + 8'd1;
            end
            if (prim_fail && !sel_src && !switching) begin
                switching  <= 1'b1;
                settle_cnt <= SETTLE;
            end else if (switching) begin
                settle_cnt <= settle_cnt - 8'd1;
                if (settle_cnt == 8'd1) begin
                    sel_src   <= 1'b1;
                    switching <= 1'b0;
                end
            end
        end
    end

    assign use_backup = sel_src;
    assign busy       = switching;
    assign fail_flag  = sticky_fail;

    always @(posedge clk)
        if (sel_src)
            assert (fail_seen);
