module caribou_cuckoo_barrett (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        req,
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire        rehash,
    input  wire [31:0] new_mod,
    output reg  [32:0] res_r,
    output reg         done,
    output reg         busy,
    output reg         expired
);
    reg [31:0] mod_r;
    reg [32:0] mu_r;
    reg [63:0] prod_r;
    reg [31:0] q_r;
    reg [2:0]  stage;
    reg [31:0] cnt;
    reg        pre_rehash;

    initial begin
        mod_r      = 32'hFFFF_FFFF;
        mu_r       = 33'h1_0000_0001;
        prod_r     = 64'd0;
        q_r        = 32'd0;
        res_r      = 33'd0;
        stage      = 3'd0;
        cnt        = 32'd0;
        busy       = 1'b0;
        done       = 1'b0;
        expired    = 1'b0;
        pre_rehash = 1'b1;
    end

    wire [64:0] two64   = {1'b1, 64'd0};
    wire [64:0] mu_full = (new_mod == 32'd0) ? 65'd0 : (two64 / {33'd0, new_mod});
    wire [96:0] pm      = prod_r * mu_r;
    wire [63:0] qm      = q_r * mod_r;
    wire [63:0] diff    = prod_r - qm;
    wire [32:0] mod_ext = {1'b0, mod_r};

    always @(posedge clk) begin
        if (rst) begin
            mod_r      <= 32'hFFFF_FFFF;
            mu_r       <= 33'h1_0000_0001;
            prod_r     <= 64'd0;
            q_r        <= 32'd0;
            res_r      <= 33'd0;
            stage      <= 3'd0;
            cnt        <= 32'd0;
            busy       <= 1'b0;
            done       <= 1'b0;
            expired    <= 1'b0;
            pre_rehash <= 1'b1;
        end else if (en) begin
            if (rehash) pre_rehash <= 1'b0;
            if (!busy) begin
                if (req) begin
                    prod_r <= a * b;
                    busy   <= 1'b1;
                    stage  <= 3'd0;
                    cnt    <= 32'd5;
                    done   <= 1'b0;
                end else if (rehash) begin
                    mod_r <= new_mod;
                    mu_r  <= mu_full[32:0];
                    done  <= 1'b0;
                end
            end else begin
                cnt     <= cnt - 32'd1;
                expired <= expired | ((cnt == 32'd1) && (stage != 3'd4));
                case (stage)
                    3'd0: begin
                        q_r   <= pm[95:64];
                        stage <= 3'd1;
                    end
                    3'd1: begin
                        res_r <= diff[32:0];
                        stage <= 3'd2;
                    end
                    3'd2: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd3;
                    end
                    3'd3: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd4;
                    end
                    3'd4: begin
                        done <= 1'b1;
                        busy <= 1'b0;
                    end
                    default: begin
                        stage <= stage;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) begin
        pv <= 1'b1;
        if (pv && pre_rehash && en && $stable(done))
            assert ($stable(expired));
    end
endmodule

