            if (kick) begin
                if (cnt > win_thr)
                    fault[0] <= 1'b1;
                else begin
                    cnt      <= reload;
                    win_open <= 1'b0;
                end
            end else if (cnt == 8'd0) begin
                fault[1] <= 1'b1;
            end else begin
                cnt      <= cnt - 8'd1;
                win_open <= ((cnt - 8'd1) <= win_thr);
            end
        end
    end

    assign o_fault = fault;
    assign o_armed = armed;
    assign o_cnt   = cnt;

    always @(posedge clk)
        if (pv && armed && $rose(fault[1]))
            assert (win_open);
