        valid  = 32'd0;
        wr_ptr = 6'd0;
        count  = 64'd0;
        armed  = 1'b1;
        for (k = 0; k < 32; k = k + 1) begin
            prefix_mem[k] = 64'd0;
            len_mem[k]    = 7'd0;
        end
    end

