                cd <= cd - 8'd1;
                if (phase == 8'd3) begin
                    busy     <= 1'b0;
                    phase    <= 8'd0;
                    dec_bits <= bits;
                    err_i    <= sym_i - pt_i;
                    err_q    <= sym_q - pt_q;
                    done     <= 1'b1;
                end else begin
                    phase <= phase + 8'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (!rst && ce && cfg_we && !busy)
            pre_cfg <= 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_cfg && $past(busy))
            assert ($past(cd) != 8'd0);
