        if (ce) begin
            case (phase)
                IDLE: begin
                    if (start) begin
                        op_read  <= op_rd;
                        frame_sr <= {2'b01, (op_rd ? 2'b10 : 2'b01), phy_ad, reg_ad, 2'b10, wr_data};
                        pre_cnt  <= 64'd0;
                        bit_cnt  <= 64'd0;
                        phase    <= PRE;
                    end
                end
                PRE: begin
                    if (pre_cnt == 64'd31) begin
                        pre_cnt <= 64'd0;
                        bit_cnt <= 64'd0;
                        phase   <= CMD;
                    end else begin
                        pre_cnt <= pre_cnt + 64'd1;
                    end
                end
                CMD: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd13) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b1;
                        phase   <= TA;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                TA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd1) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b0;
                        phase   <= DATA;
                        if (op_read) ta_pending <= 1'b1;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                DATA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (op_read) rx_sh <= {rx_sh[14:0], mdio_i};
                    if (bit_cnt == 64'd15) begin
                        bit_cnt <= 64'd0;
                        phase   <= IDLE;
