    always @(posedge clk) begin
        if (rst) begin
            cyc        <= 16'd0;
            lap        <= 16'd0;
            align_cnt0 <= 16'd0;
            win        <= 1'b0;
            ph         <= 128'd0;
            div_act    <= {8{16'd2}};
            off_act    <= 128'd0;
            div_sh     <= {8{16'd2}};
            off_sh     <= 128'd0;
        end else begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;
            if (cfg_we) begin
                div_sh[cfg_sel*16 +: 16] <= cfg_div;
                off_sh[cfg_sel*16 +: 16] <= cfg_off;
            end
            if (ce) begin
                if (wrap) begin
                    cyc        <= 16'd0;
                    lap        <= lap + 16'd1;
                    align_cnt0 <= 16'd0;
                end else begin
                    cyc <= cyc + 16'd1;
                    if (cyc == off0) align_cnt0 <= align_cnt0 + 16'd1;
