    reg [1:0] phase      = 2'd0;
    reg [7:0] cnt        = 8'd0;
    reg       seen_arm   = 1'b0;
    reg       seen_start = 1'b0;
    reg [1:0] op_r       = 2'd0;
    reg [7:0] opa        = 8'd0;
    reg [7:0] opb        = 8'd0;
