        if (rst) begin
            phase      <= IDLE;
            cnt        <= 8'd0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            carry      <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase      <= ARMED;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        op_r       <= op;
                    end
