module axi_burst_to_lite (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_awvalid,
    input  wire [3:0]   i_awid,
    input  wire [31:0]  i_awaddr,
    input  wire [2:0]   i_awlen,
    input  wire         i_wr_en,
    input  wire [2:0]   i_wr_idx,
    input  wire [127:0] i_wr_data,
    input  wire [1:0]   i_lite_bresp,
    input  wire         i_bready,
    output wire         o_awready,
    output wire         o_lite_valid,
    output wire [31:0]  o_lite_awaddr,
    output wire [127:0] o_lite_wdata,
    output wire         o_bvalid,
    output wire [3:0]   o_bid,
    output wire [1:0]   o_bresp
);
    reg         busy = 1'b0;
    reg         bvalid = 1'b0;
    reg         win = 1'b0;
    reg [3:0]   beats_left = 4'd0;
    reg [3:0]   deadline = 4'd0;
    reg [31:0]  addr = 32'd0;
    reg [3:0]   id = 4'd0;
    reg [1:0]   resp_acc = 2'd0;
    reg [2:0]   bidx = 3'd0;
    reg [127:0] wbuf [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            wbuf[i] = 128'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            bvalid <= 1'b0;
            win <= 1'b0;
            beats_left <= 4'd0;
            deadline <= 4'd0;
            addr <= 32'd0;
            id <= 4'd0;
            resp_acc <= 2'd0;
            bidx <= 3'd0;
        end else if (i_ce) begin
            if (!busy && !bvalid && i_awvalid) begin
                busy <= 1'b1;
                win <= 1'b1;
                id <= i_awid;
                addr <= i_awaddr;
                beats_left <= {1'b0, i_awlen} + 4'd1;
                deadline <= {1'b0, i_awlen} + 4'd1;
                resp_acc <= 2'd0;
                bidx <= 3'd0;
            end else if (busy) begin
                beats_left <= beats_left - 4'd1;
                deadline <= deadline - 4'd1;
                addr <= addr + 32'd16;
                bidx <= bidx + 3'd1;
                if (i_lite_bresp > resp_acc)
                    resp_acc <= i_lite_bresp;
                if (beats_left == 4'd1) begin
                    busy <= 1'b0;
                    bvalid <= 1'b1;
                end
            end else if (bvalid && i_bready) begin
                bvalid <= 1'b0;
                win <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (!rst && i_ce && i_wr_en)
            wbuf[i_wr_idx] <= i_wr_data;

    assign o_awready     = !busy && !bvalid;
    assign o_lite_valid  = busy;
    assign o_lite_awaddr = addr;
    assign o_lite_wdata  = wbuf[bidx];
    assign o_bvalid      = bvalid;
    assign o_bid         = id;
    assign o_bresp       = resp_acc;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(beats_left) == 4'd0 || $past(deadline) != 4'd0);
endmodule

