module qspi_xip_ctrl (
    input  wire        clk,
    input  wire        ce,
    input  wire        req,
    input  wire [23:0] addr,
    input  wire        cfg_we,
    input  wire [7:0]  cfg_wdata,
    input  wire [3:0]  io_in,
    output wire [3:0]  io_out,
    output wire        cs_n,
    output reg         busy,
    output reg         pf_valid,
    output reg  [31:0] pf_data
);
    reg        cs_active  = 1'b0;
    reg [31:0] cnt        = 32'd0;
    reg [31:0] nib        = 32'd0;
    reg [31:0] sh_out     = 32'd0;
    reg [7:0]  cfg_opcode = 8'hEB;
    reg        armed      = 1'b0;

    initial busy     = 1'b0;
    initial pf_valid = 1'b0;
    initial pf_data  = 32'd0;

    assign cs_n   = !cs_active;
    assign io_out = sh_out[31:28];

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (cfg_we)
                    cfg_opcode <= cfg_wdata;
                if (req) begin
                    armed     <= 1'b1;
                    busy      <= 1'b1;
                    cs_active <= 1'b1;
                    cnt       <= 32'd20;
                    nib       <= 32'd0;
                    pf_valid  <= 1'b0;
                    sh_out    <= {cfg_opcode, addr};
                end
            end else begin
                cnt    <= cnt - 32'd1;
                sh_out <= {sh_out[27:0], 4'h0};
                if (cnt <= 32'd8) begin
                    pf_data <= {pf_data[27:0], io_in};
                    if (nib == 32'd7) begin
                        pf_valid  <= 1'b1;
                        cs_active <= 1'b0;
                        nib       <= 32'd0;
                    end else begin
                        nib <= nib + 32'd1;
                    end
                end
                if (cnt == 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (!(busy && pf_valid));

    always @(posedge clk)
        if (armed) assert (!(cs_active && !busy));
endmodule

