    always @(posedge clk) begin
        if (rst) begin
            cnt       <= 8'd0;
            duty      <= 8'd128;
            fault_lat <= 1'b0;
            safe_hi   <= 4'b0000;
            safe_lo   <= 4'b1111;
            clr_arm   <= 1'b0;
            out_hi    <= 4'b0000;
            out_lo    <= 4'b1111;
        end else if (ce) begin
            cnt <= cnt + 8'd1;
            if (duty_we)
                duty <= duty_in;
            if (cfg_we) begin
                safe_hi <= cfg_hi;
                safe_lo <= cfg_lo & ~cfg_hi;
            end
            if (clr_req)
                clr_arm <= 1'b1;
            if (fault_in)
                fault_lat <= 1'b1;
            else if (clr_arm && fault_lat) begin
                fault_lat    <= 1'b0;
                clr_arm      <= 1'b0;
                no_clear_yet <= 1'b0;
            end
            if (fault_in || fault_lat) begin
                out_hi <= safe_hi;
                out_lo <= safe_lo;
            end else begin
                out_hi <= {4{pwm_on}};
                out_lo <= {4{~pwm_on}};
            end
        end
    end

    always @(posedge clk)
        if (no_clear_yet)
            assert ((out_hi & out_lo) == 4'd0);
