module ecc_dbg_mem (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cmd_valid,
    input  wire        cmd_wr,
    input  wire [5:0]  cmd_addr,
    input  wire [31:0] cmd_wdata,
    input  wire [38:0] cmd_inject,
    input  wire        rsp_ack,
    output wire        rsp_valid,
    output reg  [31:0] rsp_rdata,
    output reg  [6:0]  rsp_syndrome,
    output reg         rsp_sbe,
    output reg         rsp_dbe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, START = 2'd2, DONE = 2'd3;

    function [38:0] secded_enc(input [31:0] d);
        integer i, j, p, k;
        reg [38:0] c;
        reg par;
        begin
            c = 39'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    c[i] = d[j];
                    j = j + 1;
                end
            end
            for (p = 0; p < 6; p = p + 1) begin
                par = 1'b0;
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) par = par ^ c[k];
                c[1 << p] = par;
            end
            c[0] = ^c[38:1];
            secded_enc = c;
        end
    endfunction

    function [5:0] secded_syn(input [38:0] c);
        integer p, k;
        reg [5:0] s;
        begin
            s = 6'd0;
            for (p = 0; p < 6; p = p + 1)
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) s[p] = s[p] ^ c[k];
            secded_syn = s;
        end
    endfunction

    function [31:0] secded_data(input [38:0] c);
        integer i, j;
        reg [31:0] d;
        begin
            d = 32'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    d[j] = c[i];
                    j = j + 1;
                end
            end
            secded_data = d;
        end
    endfunction

    reg [1:0]  phase      = IDLE;
    reg        arm_seen   = 1'b0;
    reg        start_seen = 1'b0;
    reg        q_seen     = 1'b0;
    reg        wr_q       = 1'b0;
    reg [5:0]  addr_q     = 6'd0;
    reg [31:0] wdata_q    = 32'd0;
    reg [38:0] inj_q      = 39'd0;
    reg [38:0] rd_cw_q    = 39'd0;
    reg [38:0] mem [0:63];

    integer n;
    initial begin
        for (n = 0; n < 64; n = n + 1) mem[n] = 39'd0;
        rsp_rdata    = 32'd0;
        rsp_syndrome = 7'd0;
        rsp_sbe      = 1'b0;
        rsp_dbe      = 1'b0;
    end

    wire [38:0] wr_cw = secded_enc(wdata_q) ^ inj_q;
    wire [5:0]  syn   = secded_syn(rd_cw_q);
    wire        ovp   = ^rd_cw_q;
    wire        sbe   = ovp;
    wire        dbe   = !ovp && (syn != 6'd0);
    wire [38:0] fixed = sbe ? (rd_cw_q ^ (39'd1 << syn)) : rd_cw_q;

    assign rsp_valid = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: if (cmd_valid) begin
                    phase      <= ARMED;
                    arm_seen   <= 1'b1;
                    start_seen <= 1'b0;
                    wr_q       <= cmd_wr;
                    addr_q     <= cmd_addr;
                    wdata_q    <= cmd_wdata;
                    inj_q      <= cmd_inject;
                    if (cmd_wr) q_seen <= 1'b1;
                end
                ARMED: begin
                    if (wr_q) mem[addr_q] <= wr_cw;
                    rd_cw_q    <= wr_q ? wr_cw : mem[addr_q];
                    start_seen <= 1'b1;
                    phase      <= START;
                end
                START: begin
                    rsp_rdata    <= secded_data(fixed);
                    rsp_syndrome <= {ovp, syn};
                    rsp_sbe      <= sbe;
                    rsp_dbe      <= dbe;
                    phase        <= DONE;
                end
                DONE: if (rsp_ack) begin
                    phase      <= IDLE;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    assert property (!q_seen || !rsp_valid || (arm_seen && start_seen));
