module gshare_streak (
    input  wire        clk,
    input  wire        upd,
    input  wire        taken,
    input  wire [63:0] upd_pc,
    input  wire [63:0] fetch_pc,
    input  wire        restore,
    input  wire [63:0] restore_ghr,
    output wire        pred_taken
);
    reg [63:0] ghr      = 64'd0;
    reg [63:0] streak_t = 64'd0;
    reg [63:0] streak_n = 64'd0;
    reg        armed    = 1'b1;
    reg [1:0]  pht [0:255];
    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            pht[i] = 2'b01;
    end

    wire [7:0] fidx = fetch_pc[9:2] ^ ghr[7:0];
    wire [7:0] uidx = upd_pc[9:2] ^ ghr[7:0];
    assign pred_taken = pht[fidx][1];

    wire [63:0] t_inc = (streak_t == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_t : streak_t + 64'd1;
    wire [63:0] n_inc = (streak_n == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_n : streak_n + 64'd1;

    always @(posedge clk) begin
        if (restore) begin
            ghr   <= restore_ghr;
            armed <= 1'b0;
        end else if (upd) begin
            ghr <= {ghr[62:0], taken};
            if (taken) begin
                pht[uidx] <= (pht[uidx] == 2'b11) ? 2'b11 : pht[uidx] + 2'b01;
                if (!ghr[0]) begin
                    streak_t <= 64'd1;
                    streak_n <= 64'd0;
                end else begin
                    streak_t <= t_inc;
                end
            end else begin
                pht[uidx] <= (pht[uidx] == 2'b00) ? 2'b00 : pht[uidx] - 2'b01;
                if (ghr[0]) begin
                    streak_n <= 64'd1;
                    streak_t <= 64'd0;
                end else begin
                    streak_n <= n_inc;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(streak_t) != 64'd0 && $past(streak_n) != 64'd0));
endmodule

