module bus_timeout_mon (
    input  wire        clk,
    input  wire        i_clr,
    input  wire        i_ce,
    input  wire        i_arm,
    input  wire [31:0] i_thresh,
    input  wire        i_req,
    input  wire        i_resp,
    output wire        o_err_resp,
    output wire        o_timeout,
    output wire [31:0] o_txn_count
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_BUSY  = 2'd2;

    reg [1:0]  phase;
    reg [31:0] thresh;
    reg [31:0] wait_cnt;
    reg [31:0] txn_count;
    reg        to_err;
    reg        seen_arm;
    reg        seen_start;

    initial begin
        phase = P_IDLE;
        thresh = 32'd0;
        wait_cnt = 32'd0;
        txn_count = 32'd0;
        to_err = 1'b0;
        seen_arm = 1'b0;
        seen_start = 1'b0;
    end

    always @(posedge clk) begin
        if (i_clr) begin
            phase <= P_IDLE;
            thresh <= 32'd0;
            wait_cnt <= 32'd0;
            txn_count <= 32'd0;
            to_err <= 1'b0;
            seen_arm <= 1'b0;
            seen_start <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (i_arm) begin
                        thresh <= i_thresh;
                        seen_arm <= 1'b1;
                        phase <= P_ARMED;
                    end
                end
                P_ARMED: begin
                    if (i_req) begin
                        seen_start <= 1'b1;
                        wait_cnt <= 32'd0;
                        txn_count <= txn_count + 32'd1;
                        phase <= P_BUSY;
                    end
                end
                P_BUSY: begin
                    if (i_resp) begin
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else if (wait_cnt >= thresh) begin
                        to_err <= 1'b1;
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else begin
                        wait_cnt <= wait_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_err_resp  = (phase == P_BUSY) && !i_resp && (wait_cnt >= thresh);
    assign o_timeout   = to_err;
    assign o_txn_count = txn_count;

    assert property (!to_err || (seen_arm && seen_start));
