module tap_delay_chain (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire [31:0] cfg_tap,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    // 12-stage x 32-bit data chain plus a parallel marker chain
    reg [383:0] chain;
    reg [11:0]  mark;
    reg [31:0]  tap;
    reg [1:0]   phase;
    reg         started;
    reg         q_seen;

    initial chain   = 384'd0;
    initial mark    = 12'h000;
    initial tap     = 32'd0;
    initial phase   = IDLE;
    initial started = 1'b0;
    initial q_seen  = 1'b0;

    wire tap_ok   = (tap < 32'd12);
    wire tap_mark = tap_ok ? mark[tap[3:0]] : 1'b0;
    assign dout   = tap_ok ? chain[{tap[3:0], 5'b00000} +: 32] : 32'd0;
    assign done   = (phase == DONE);

    wire go_arm    = ce && (phase == IDLE) && arm;
    wire go_finish = ce && ((phase == ARMED) || (phase == RUN)) && tap_mark;
    wire go_start  = ce && (phase == ARMED) && start && !tap_mark;

    always @(posedge clk) begin
        if (ce) begin
            chain <= {chain[351:0], din};
            mark  <= {mark[10:0], go_start};
        end
        if (go_arm) begin
            phase  <= ARMED;
            q_seen <= 1'b1;
            tap    <= (cfg_tap < 32'd12) ? cfg_tap : 32'd11;
        end else if (go_finish) begin
            phase <= DONE;
        end else if (go_start) begin
            phase   <= RUN;
            started <= 1'b1;
        end
    end

    // after the first arm: finish is never observed unless start happened
    always @(posedge clk)
        if (q_seen) assert (phase != DONE || started);
endmodule

