module traffic_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       preempt,
    output wire       ns_green,
    output wire       ew_green,
    output wire [2:0] phase_o
);
    // phases: 0 NS_GREEN, 1 NS_YELLOW, 2 ALL_RED_A, 3 EW_GREEN, 4 EW_YELLOW, 5 ALL_RED_B
    reg [2:0]  phase     = 3'd0;
    reg [15:0] timer     = 16'd39;
    reg [15:0] green_cnt = 16'd0;
    reg        armed     = 1'b1;
    reg        pv        = 1'b0;

    assign ns_green = (phase == 3'd0);
    assign ew_green = (phase == 3'd3);
    assign phase_o  = phase;

    function [15:0] dur;
        input [2:0] p;
        begin
            case (p)
                3'd0:    dur = 16'd39;
                3'd1:    dur = 16'd4;
                3'd2:    dur = 16'd1;
                3'd3:    dur = 16'd29;
                3'd4:    dur = 16'd4;
                default: dur = 16'd1;
            endcase
        end
    endfunction

    wire [2:0] nxt = (phase >= 3'd5) ? 3'd0 : phase + 3'd1;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            phase     <= 3'd0;
            timer     <= 16'd39;
            green_cnt <= 16'd0;
            armed     <= 1'b1;
        end else if (step) begin
            if (phase == 3'd0)
                green_cnt <= green_cnt + 16'd1;
            if (phase == 3'd0 && preempt) begin
                timer <= 16'd200;
                armed <= 1'b0;
            end else if (timer == 16'd0) begin
                phase <= nxt;
                timer <= dur(nxt);
                if (nxt == 3'd0)
                    green_cnt <= 16'd0;
            end else begin
                timer <= timer - 16'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $fell(ns_green))
            assert (green_cnt <= 16'd40);
endmodule

