    // the stored copy is left untouched
    assign bypass_en = (phase == 2'd2);
    assign dout = bypass_en ? din : stored;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (open_w)       win <= 1'b1;
            else if (close_w) win <= 1'b0;

            case (phase)
                2'd0: if (arm) begin
                    phase    <= 2'd1;
                    arm_seen <= 1'b1;
                    stored   <= din;
                end
                2'd1: if (start) begin
                    phase      <= 2'd2;
                    start_seen <= 1'b1;
                end
                2'd2: if (finish) begin
                    phase    <= 2'd3;
                    xact_cnt <= xact_cnt + 32'd1;
                end
                default: begin
                    phase      <= 2'd0;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
