    input  wire            dst_ce,
    output wire [N-1:0]    out_pulse,
    output wire            busy_o
);
    localparam [63:0] LAT = 64'd3;

    reg [N-1:0] src_tog = {N{1'b0}};
    reg [N-1:0] s1 = {N{1'b0}};
    reg [N-1:0] s2 = {N{1'b0}};
    reg [N-1:0] s3 = {N{1'b0}};
    reg         busy = 1'b0;
    reg [63:0]  countdown = 64'd0;

    assign in_ready  = !busy;
    wire   accept    = in_valid && in_ready;
    assign out_pulse = s2 ^ s3;
    assign busy_o    = busy;

    always @(posedge clk) begin
        if (rst) begin
            src_tog   <= {N{1'b0}};
            s1        <= {N{1'b0}};
            s2        <= {N{1'b0}};
            s3        <= {N{1'b0}};
            busy      <= 1'b0;
            countdown <= 64'd0;
