module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
endmodule


