module mn_clken_gen #(
    parameter W = 64,
    parameter [W-1:0] M_DEF = 64'd3,
    parameter [W-1:0] N_DEF = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         req,
    input  wire         cfg_load,
    input  wire [W-1:0] cfg_m,
    input  wire [W-1:0] cfg_n,
    output wire         ce_out,
    output wire         busy
);
    reg [W-1:0] m_r = M_DEF;
    reg [W-1:0] n_r = N_DEF;
    reg [W-1:0] err = {W{1'b0}};
    reg [W-1:0] cd  = {W{1'b0}};
    reg         armed = 1'b0;
    reg         timeout = 1'b0;

    wire [W:0]   sum  = {1'b0, err} + {1'b0, m_r};
    wire         hit  = (sum >= {1'b0, n_r});
    wire [W:0]   diff = sum - {1'b0, n_r};
    wire [W-1:0] err_nxt = step ? (hit ? diff[W-1:0] : sum[W-1:0]) : err;
    wire         cfg_ok = (cfg_n != {W{1'b0}}) && (cfg_m != {W{1'b0}}) && (cfg_m <= cfg_n);

    assign ce_out = step && hit;
    assign busy   = armed;

    always @(posedge clk) begin
        if (rst) begin
            m_r     <= M_DEF;
            n_r     <= N_DEF;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else if (cfg_load && cfg_ok) begin
            m_r     <= cfg_m;
            n_r     <= cfg_n;
            err     <= {W{1'b0}};
            cd      <= {W{1'b0}};
            armed   <= 1'b0;
            timeout <= 1'b0;
        end else begin
            err <= err_nxt;
            if (!armed) begin
                if (req) begin
                    armed <= 1'b1;
                    cd    <= n_r - err_nxt;
                end
            end else if (step) begin
                if (hit)
                    armed <= 1'b0;
                else if (cd <= m_r)
                    timeout <= 1'b1;
                else
                    cd <= cd - m_r;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(armed))
            assert ($stable(timeout));
endmodule

