module oc_csum_acc #(
    parameter W = 32
) (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    input  wire         i_ce,
    output wire [W-1:0] o_csum
);
    reg [W-1:0] acc;
    reg [W-1:0] hold_data;
    reg         hold_valid;
    reg         seen_nz;
    reg         armed;
    initial acc = {W{1'b0}};
    initial hold_data = {W{1'b0}};
    initial hold_valid = 1'b0;
    initial seen_nz = 1'b0;
    initial armed = 1'b1;

    wire drain = i_ce && hold_valid;
    assign in_ready = !hold_valid || drain;
    wire accept = in_valid && in_ready;

    // end-around-carry (one's-complement) adder, purely combinational
    wire [W:0]   raw     = {1'b0, acc} + {1'b0, hold_data};
    wire         eac     = raw[W];
    wire [W-1:0] eac_sum = raw[W-1:0] + {{(W-1){1'b0}}, eac};

    always @(posedge clk) begin
        if (i_reset) begin
            acc        <= {W{1'b0}};
            hold_data  <= {W{1'b0}};
            hold_valid <= 1'b0;
            seen_nz    <= 1'b0;
            armed      <= 1'b1;
        end else begin
            if (drain) begin
                acc <= eac_sum;
                if (eac)
                    armed <= 1'b0;
            end
            if (accept) begin
                hold_data  <= in_data;
                hold_valid <= 1'b1;
                if (in_data != {W{1'b0}})
                    seen_nz <= 1'b1;
            end else if (drain) begin
                hold_valid <= 1'b0;
            end
        end
    end

    assign o_csum = ~acc;

    always @(*)
        assert (!armed || seen_nz || acc == {W{1'b0}});
endmodule

