module sqrt_restoring #(
    parameter W  = 128,
    parameter SW = 7
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           ce,
    input  wire           start,
    input  wire [W-1:0]   radicand,
    output wire [W/2-1:0] root,
    output wire           busy,
    output wire           done
);
    typedef enum logic [1:0] {IDLE = 2'd0, BUSY = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0]  TOP   = {2'b01, {(W-2){1'b0}}};
    localparam [SW-1:0] STEPS = W / 2;

    state_t        state;
    reg [W-1:0]    rem;
    reg [W-1:0]    res;
    reg [W-1:0]    bit_r;
    reg [SW-1:0]   step;

    initial begin
        state = IDLE;
        rem   = {W{1'b0}};
        res   = {W{1'b0}};
        bit_r = TOP;
        step  = {SW{1'b0}};
    end

    wire [W-1:0] trial = res + bit_r;
    wire         fits  = (rem >= trial);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            rem   <= {W{1'b0}};
            res   <= {W{1'b0}};
            bit_r <= TOP;
            step  <= {SW{1'b0}};
        end else if (ce) begin
            case (state)
                IDLE, DONE: begin
                    if (start) begin
                        state <= BUSY;
                        rem   <= radicand;
                        res   <= {W{1'b0}};
                        bit_r <= TOP;
                        step  <= {SW{1'b0}};
                    end
                end
                BUSY: begin
                    if (bit_r == {W{1'b0}}) begin
                        state <= DONE;
                    end else begin
                        if (fits) begin
                            rem <= rem - trial;
                            res <= (res >> 1) + bit_r;
                        end else begin
                            res <= res >> 1;
                        end
                        bit_r <= bit_r >> 2;
                        step  <= step + 1'b1;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    assign root = res[W/2-1:0];
    assign busy = (state == BUSY);
    assign done = (state == DONE);

    always @(*) assert (step <= STEPS);
endmodule

