module usb_stream_writer (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire ack,
    input wire s_valid,
    input wire s_last,
    input wire [31:0] s_data,
    input wire trig_arm,
    input wire trig_disarm,
    output wire busy,
    output wire full,
    output wire [31:0] o_pkt_len,
    output wire o_eop
);
    parameter DEPTH = 16;
    parameter AW = 4;
    parameter DW = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, CAPTURE = 2'd1, DONE = 2'd2} state_t;

    state_t state = IDLE;
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [DW-1:0] byte_cnt = {DW{1'b0}};
    reg [DW-1:0] pkt_len = {DW{1'b0}};
    reg eop = 1'b0;
    reg win = 1'b0;
    reg [DW-1:0] mem [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    assign busy = (state == CAPTURE);
    assign full = (byte_cnt == DEPTH);
    assign o_pkt_len = pkt_len;
    assign o_eop = eop;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            wr_ptr <= {AW{1'b0}};
            byte_cnt <= {DW{1'b0}};
            pkt_len <= {DW{1'b0}};
            eop <= 1'b0;
            win <= 1'b0;
        end else if (ce) begin
            if (trig_arm)
                win <= 1'b1;
            else if (trig_disarm)
                win <= 1'b0;
            case (state)
                IDLE: begin
                    if (start) begin
                        state <= CAPTURE;
                        wr_ptr <= {AW{1'b0}};
                        byte_cnt <= {DW{1'b0}};
                        eop <= 1'b0;
                    end
                end
                CAPTURE: begin
                    if (s_valid) begin
                        mem[wr_ptr] <= s_data;
                        wr_ptr <= wr_ptr + 1'b1;
                        byte_cnt <= byte_cnt + 1;
                        if (s_last || (wr_ptr == DEPTH-1)) begin
                            state <= DONE;
                            pkt_len <= byte_cnt + 1;
                            eop <= s_last;
                        end
                    end
                end
                DONE: begin
                    if (ack)
                        state <= IDLE;
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(*)
        if (win) assert (!(busy && full));
endmodule

