module i2c_arb_monitor #(
    parameter FRAME_BITS = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire        drv_bit,
    input  wire        sda_in,
    output reg         lost,
    output reg  [31:0] lost_pos,
    output reg         last_drv
);
    localparam [31:0] FRAME = FRAME_BITS;

    reg        busy    = 1'b0;
    reg [31:0] bit_cnt = 32'd0;
    reg        win     = 1'b0;
    reg [31:0] sh_cnt  = 32'd0;

    initial begin
        lost     = 1'b0;
        lost_pos = 32'd0;
        last_drv = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            bit_cnt  <= 32'd0;
            lost     <= 1'b0;
            lost_pos <= 32'd0;
            last_drv <= 1'b1;
            win      <= 1'b0;
            sh_cnt   <= 32'd0;
        end else if (ce) begin
            if (stop) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (start && !busy) begin
                busy     <= 1'b1;
                bit_cnt  <= 32'd0;
                lost     <= 1'b0;
                lost_pos <= 32'd0;
                last_drv <= 1'b1;
                win      <= 1'b0;
                sh_cnt   <= 32'd0;
            end else if (busy) begin
                last_drv <= lost ? 1'b1 : drv_bit;
                if (!lost && drv_bit && !sda_in) begin
                    lost     <= 1'b1;
                    lost_pos <= bit_cnt;
                    win      <= 1'b1;
                    sh_cnt   <= 32'd0;
                end else if (win) begin
                    sh_cnt <= sh_cnt + 32'd1;
                end
                bit_cnt <= bit_cnt + 32'd1;
                if (bit_cnt == FRAME - 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win) assert (lost_pos < bit_cnt);

    always @(posedge clk)
        if (win) assert (sh_cnt < bit_cnt);
endmodule

