module pkt_framer #(
    parameter W = 16,
    parameter DEPTH = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_start,
    input  wire [W-1:0] i_len,
    input  wire [W-1:0] i_data,
    output reg  [W-1:0] o_word,
    output reg          o_sof,
    output reg          o_eof
);
    localparam [W-1:0] MAX_LEN    = DEPTH;
    localparam [W-1:0] START_DELIM = 16'hA5A5;
    localparam [W-1:0] END_DELIM   = 16'h5A5A;
    localparam [1:0] S_IDLE = 2'd0, S_HDR = 2'd1, S_PAY = 2'd2, S_TRL = 2'd3;

    reg [1:0]   frame_state = S_IDLE;
    reg [W-1:0] byte_cnt    = {W{1'b0}};
    reg [W-1:0] len_reg     = {{(W-1){1'b0}}, 1'b1};
    reg         armed       = 1'b0;
    reg         pv          = 1'b0;
    initial o_word = {W{1'b0}};
    initial o_sof  = 1'b0;
    initial o_eof  = 1'b0;

    wire [W-1:0] len_clamped = (i_len == {W{1'b0}}) ? {{(W-1){1'b0}}, 1'b1} :
                               ((i_len > MAX_LEN) ? MAX_LEN : i_len);
    wire over_lim = (byte_cnt > MAX_LEN);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            frame_state <= S_IDLE;
            byte_cnt    <= {W{1'b0}};
            len_reg     <= {{(W-1){1'b0}}, 1'b1};
            o_word      <= {W{1'b0}};
            o_sof       <= 1'b0;
            o_eof       <= 1'b0;
        end else if (i_ce) begin
            case (frame_state)
                S_IDLE: begin
                    o_sof <= 1'b0;
                    o_eof <= 1'b0;
                    if (i_start) begin
                        len_reg     <= len_clamped;
                        o_word      <= START_DELIM;
                        o_sof       <= 1'b1;
                        armed       <= 1'b1;
                        frame_state <= S_HDR;
                    end
                end
                S_HDR: begin
                    o_sof       <= 1'b0;
                    o_word      <= len_reg;
                    byte_cnt    <= {W{1'b0}};
                    frame_state <= S_PAY;
                end
