module agu_burst #(
    parameter AW     = 32,
    parameter BURST  = 8,
    parameter STRIDE = 4
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          start,
    input  wire          pre_inc,
    input  wire [AW-1:0] base_in,
    input  wire [AW-1:0] index_in,
    input  wire [AW-1:0] disp_in,
    input  wire [1:0]    scale_in,
    output wire [AW-1:0] ea,
    output wire          fault
);
    typedef enum logic [1:0] {IDLE = 2'd0, RUN = 2'd1, DONE = 2'd2} state_t;

    state_t state = IDLE;
    reg [AW-1:0] base_r = {AW{1'b0}};
    reg [AW-1:0] end_r  = {AW{1'b0}};
    reg [AW-1:0] ea_r   = {AW{1'b0}};
    reg [AW-1:0] beats  = {AW{1'b0}};
    reg          fault_r = 1'b0;
    reg          armed   = 1'b1;

    wire [AW-1:0] step_base = base_r + STRIDE;
    wire [AW-1:0] scaled_ix = index_in << scale_in;
    wire [AW-1:0] ea_next   = (pre_inc ? step_base : base_r) + scaled_ix + disp_in;
    wire          misaligned = |ea_next[1:0];

    always @(posedge clk) begin
        if (rst) begin
            state   <= IDLE;
            base_r  <= {AW{1'b0}};
            end_r   <= {AW{1'b0}};
            ea_r    <= {AW{1'b0}};
            beats   <= {AW{1'b0}};
            fault_r <= 1'b0;
        end else if (ce) begin
            case (state)
                IDLE: if (start) begin
                    base_r  <= base_in;
                    end_r   <= base_in + BURST * STRIDE;
                    beats   <= {AW{1'b0}};
                    fault_r <= 1'b0;
                    state   <= RUN;
                end
                RUN: begin
                    ea_r    <= ea_next;
                    fault_r <= misaligned;
                    base_r  <= step_base;
                    beats   <= beats + 1'b1;
                    if (step_base == end_r)
                        state <= DONE;
                end
                DONE: state <= IDLE;
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (!rst && ce && state == RUN && misaligned)
            armed <= 1'b0;

    assign ea    = ea_r;
    assign fault = fault_r;

    assert property (!armed || beats <= BURST);
endmodule

