module warm_reset_quiesce #(
    parameter NPORTS = 64,
    parameter [31:0] TIMEOUT = 32'd16
) (
    input  wire              clk,
    input  wire              ce,
    input  wire              req_valid,
    output wire              req_ready,
    input  wire [NPORTS-1:0] port_idle,
    output wire              quiesce_req,
    output wire              block_new,
    output reg               warm_rst,
    output reg               timed_out
);
    reg              quiesce;
    reg [31:0]       timer;
    reg [31:0]       elapsed;
    reg [NPORTS-1:0] ack;
    reg              before_rst;

    initial begin
        quiesce    = 1'b0;
        timer      = 32'd0;
        elapsed    = 32'd0;
        ack        = {NPORTS{1'b0}};
        warm_rst   = 1'b0;
        timed_out  = 1'b0;
        before_rst = 1'b1;
    end

    assign req_ready   = ce && !quiesce;
    assign quiesce_req = quiesce;
    assign block_new   = quiesce;

    wire accept   = req_valid && req_ready;
    wire all_idle = &(ack | port_idle);
    wire expire   = (elapsed == TIMEOUT - 32'd1);

    always @(posedge clk) begin
        if (ce) begin
            warm_rst <= 1'b0;
            if (!quiesce) begin
                if (accept) begin
                    quiesce <= 1'b1;
                    timer   <= TIMEOUT;
                    elapsed <= 32'd0;
                    ack     <= {NPORTS{1'b0}};
