        if (accept) begin
            period_sh <= in_period;
            cmp_sh    <= in_cmp;
            pend      <= 1'b1;
        end else if (wrap) begin
            pend      <= 1'b0;
        end
        if (accept)
            armed <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed && $stable(pend))
            assert ($stable(period_act));
endmodule

