module psg_minority_tally #(
    parameter [31:0] FRAME = 32'd64
) (
    input  wire clk,
    input  wire step,
    input  wire start,
    input  wire stop,
    input  wire ch_a,
    input  wire ch_b,
    input  wire ch_c,
    output wire minority,
    output wire busy
);
    typedef enum logic [1:0] {S_IDLE = 2'd0, S_RUN = 2'd1, S_DONE = 2'd2} state_t;

    // Minority gate: complement of the majority of the three channel bits
    wire majority = (ch_a & ch_b) | (ch_a & ch_c) | (ch_b & ch_c);
    assign minority = ~majority;

    state_t state;
    reg [31:0] pos;
    reg [31:0] cnt;
    reg armed;

    initial state = S_IDLE;
    initial pos = 32'd0;
    initial cnt = 32'd0;
    initial armed = 1'b0;

    assign busy = (state == S_RUN);

    always @(posedge clk) begin
        if (step) begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        state <= S_RUN;
                        pos <= 32'd0;
                        cnt <= 32'd0;
                    end
                end
                S_RUN: begin
                    pos <= pos + 32'd1;
                    cnt <= cnt + {31'd0, minority};
                    if (pos == FRAME - 32'd1)
                        state <= S_DONE;
                end
                S_DONE: begin
                    if (start) begin
                        state <= S_RUN;
                        pos <= 32'd0;
                        cnt <= 32'd0;
                    end
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    // Window register: opened by a frame start, closed by stop (which may never come)
    always @(posedge clk) begin
        if (step) begin
            if (start)
                armed <= 1'b1;
            else if (stop)
                armed <= 1'b0;
        end
    end

    assert property (!armed || cnt <= FRAME);
endmodule

