module twiddle_rom_seq #(
    parameter N   = 256,
    parameter LGN = 8,
    parameter DW  = 64
) (
    input  wire          clk,
    input  wire          i_reset,
    input  wire          i_ce,
    output reg  [DW-1:0] o_re,
    output reg  [DW-1:0] o_im,
    output reg           o_unity,
    output reg           o_negj,
    output reg           o_win
);
    localparam HALF = N / 2;
    localparam QW   = N / 4;
    localparam SH   = DW - 2 - 2*(LGN-2);
    localparam [DW-1:0] ONE = {2'b01, {(DW-2){1'b0}}};

    // quarter-wave magnitude table: cos(pi*x/(N/2)) approximated as 1-(x/QW)^2
    function [DW-1:0] cmag;
        input [LGN-2:0] x;
        reg [2*(LGN-1)-1:0] sq;
        begin
            sq   = x * x;
            cmag = ONE - ({{(DW-2*(LGN-1)){1'b0}}, sq} << SH);
        end
    endfunction

    // real coefficient table: cos(2*pi*k/N), quadrant folded
    function [DW-1:0] re_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    re_rom =  cmag(r);
                2'd1:    re_rom = -cmag(QW - r);
                2'd2:    re_rom = -cmag(r);
                default: re_rom =  cmag(QW - r);
            endcase
        end
    endfunction

    // imaginary coefficient table: -sin(2*pi*k/N), quadrant folded
    function [DW-1:0] im_rom;
        input [LGN-1:0] k;
        reg [LGN-2:0] r;
        begin
            r = {1'b0, k[LGN-3:0]};
            case (k[LGN-1:LGN-2])
                2'd0:    im_rom = -cmag(QW - r);
                2'd1:    im_rom = -cmag(r);
                2'd2:    im_rom =  cmag(QW - r);
                default: im_rom =  cmag(r);
            endcase
        end
    endfunction

    reg [DW-1:0]  pos;
    reg [DW-1:0]  stage;
    reg [LGN-1:0] re_addr;
    reg [LGN-1:0] im_addr;

    initial pos     = 0;
    initial stage   = 0;
    initial re_addr = 0;
    initial im_addr = 0;
    initial o_re    = 0;
    initial o_im    = 0;
    initial o_unity = 1'b0;
    initial o_negj  = 1'b0;
    initial o_win   = 1'b0;

    // twiddle index for butterfly position pos in stage: (pos << stage) mod N
    wire [LGN-1:0] tw_k = pos[LGN-1:0] << stage[2:0];

    always @(posedge clk) begin
        if (i_reset) begin
            pos     <= 0;
            stage   <= 0;
            re_addr <= 0;
            im_addr <= 0;
            o_re    <= 0;
            o_im    <= 0;
            o_unity <= 1'b0;
            o_negj  <= 1'b0;
            o_win   <= 1'b0;
        end else if (i_ce) begin
            // separate address registers for the real and imaginary ROM ports
            re_addr <= tw_k;
            im_addr <= tw_k;
            // registered coefficient output pair
            o_re    <= re_rom(re_addr);
            o_im    <= im_rom(im_addr);
            o_unity <= (re_addr == 0);
            o_negj  <= (im_addr == QW);
            if (pos == HALF-1) begin
                pos   <= 0;
                stage <= (stage == LGN-1) ? 0 : stage + 1;
            end else begin
                pos   <= pos + 1;
            end
            // stage window: opens at first butterfly, closes at last
            if (pos == 0)
                o_win <= 1'b1;
            else if (pos == HALF-1)
                o_win <= 1'b0;
        end
    end

    // within a stage window, the unity and -j coefficient markers never coincide
    assert property (!o_win || !(o_unity && o_negj));
endmodule

