module irq_first_arrival #(
    parameter NCH  = 8,
    parameter IDXW = 3,
    parameter TW   = 64
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire            clr,
    input  wire [NCH-1:0]  irq,
    output reg             captured,
    output reg [IDXW-1:0]  win_idx,
    output reg [NCH-1:0]   win_mask,
    output reg [TW-1:0]    cap_time
);
    localparam [NCH-1:0] ONE = 1;

    reg [TW-1:0] tick;

    initial begin
        captured = 1'b0;
        win_idx  = {IDXW{1'b0}};
        win_mask = {NCH{1'b0}};
        cap_time = {TW{1'b0}};
        tick     = {TW{1'b0}};
    end

    function [IDXW-1:0] first_idx;
        input [NCH-1:0] v;
        integer i;
        begin
            first_idx = {IDXW{1'b0}};
            for (i = NCH-1; i >= 0; i = i - 1)
                if (v[i]) first_idx = i;
        end
    endfunction

    wire [IDXW-1:0] enc = first_idx(irq);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            captured <= 1'b0;
            win_idx  <= {IDXW{1'b0}};
            win_mask <= {NCH{1'b0}};
            cap_time <= {TW{1'b0}};
            tick     <= {TW{1'b0}};
        end else if (ce) begin
            tick <= tick + {{(TW-1){1'b0}}, 1'b1};
            if (!captured && (|irq)) begin
                captured <= 1'b1;
                win_idx  <= enc;
                win_mask <= ONE << enc;
                cap_time <= tick;
            end else if (captured && clr) begin
                captured <= 1'b0;
                win_mask <= win_mask & ~(ONE << win_idx);
            end
        end
    end

    always @(*) assert (captured || win_mask == {NCH{1'b0}});
endmodule

