module eye_scan_monitor #(
    parameter [63:0] NSAMP = 64'd16,
    parameter [63:0] H_PTS = 64'd4,
    parameter [63:0] V_PTS = 64'd4
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        start,
    input  wire        abort,
    input  wire        data_bit,
    input  wire        offset_bit,
    output wire        busy,
    output wire [63:0] o_mismatch,
    output wire [63:0] o_h_off,
    output wire [63:0] o_v_off
);
    typedef enum logic [1:0] {S_IDLE, S_SAMPLE, S_STEP, S_DONE} state_t;

    state_t     state;
    reg [63:0]  h_off;
    reg [63:0]  v_off;
    reg [63:0]  sample_cnt;
    reg [63:0]  mismatch_cnt;
    reg         window;

    initial begin
        state        = S_IDLE;
        h_off        = 64'd0;
        v_off        = 64'd0;
        sample_cnt   = 64'd0;
        mismatch_cnt = 64'd0;
        window       = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state        <= S_IDLE;
            h_off        <= 64'd0;
            v_off        <= 64'd0;
            sample_cnt   <= 64'd0;
            mismatch_cnt <= 64'd0;
            window       <= 1'b0;
        end else if (en) begin
            case (state)
                S_IDLE: begin
                    if (start) begin
                        state        <= S_SAMPLE;
                        h_off        <= 64'd0;
                        v_off        <= 64'd0;
                        sample_cnt   <= 64'd0;
                        mismatch_cnt <= 64'd0;
                        window       <= 1'b1;
                    end
                end
                S_SAMPLE: begin
                    if (abort) begin
                        state  <= S_IDLE;
                        window <= 1'b0;
                    end else begin
                        sample_cnt <= sample_cnt + 64'd1;
                        if (data_bit != offset_bit)
                            mismatch_cnt <= mismatch_cnt + 64'd1;
                        if (sample_cnt == NSAMP - 64'd1)
                            state <= S_STEP;
                    end
                end
                S_STEP: begin
                    sample_cnt   <= 64'd0;
                    mismatch_cnt <= 64'd0;
                    if (h_off == H_PTS - 64'd1) begin
                        h_off <= 64'd0;
                        if (v_off == V_PTS - 64'd1) begin
                            v_off <= 64'd0;
                            state <= S_DONE;
                        end else begin
                            v_off <= v_off + 64'd1;
                            state <= S_SAMPLE;
                        end
                    end else begin
                        h_off <= h_off + 64'd1;
                        state <= S_SAMPLE;
                    end
                end
                S_DONE: begin
                    window <= 1'b0;
                    state  <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    assign busy       = (state != S_IDLE);
    assign o_mismatch = mismatch_cnt;
    assign o_h_off    = h_off;
    assign o_v_off    = v_off;

    always @(posedge clk)
        if (window)
            assert (mismatch_cnt <= NSAMP);
endmodule


