module requant_unit #(
    parameter W  = 64,
    parameter SW = 6
) (
    input  wire          clk,
    input  wire          rst,
    input  wire          ce,
    input  wire          arm,
    input  wire          start,
    input  wire          ack,
    input  wire          clr,
    input  wire [W-1:0]  cfg_mult,
    input  wire [SW-1:0] cfg_shift,
    input  wire [W-1:0]  acc_in,
    output reg  [W-1:0]  out_q,
    output reg  [1:0]    phase
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, BUSY = 2'd2, DONE = 2'd3;

    reg [W-1:0]  mult_cfg  = {W{1'b0}};
    reg [SW-1:0] shift_cfg = {SW{1'b0}};
    reg [W-1:0]  work      = {W{1'b0}};
    reg [SW-1:0] cnt       = {SW{1'b0}};
    reg          run       = 1'b0;
    reg          win       = 1'b0;
    initial out_q = {W{1'b0}};
    initial phase = IDLE;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            run   <= 1'b0;
            cnt   <= {SW{1'b0}};
            work  <= {W{1'b0}};
            win   <= 1'b0;
        end else if (ce) begin
            if (clr)
                win <= 1'b0;
            if (phase == IDLE && arm) begin
                mult_cfg  <= cfg_mult;
                shift_cfg <= cfg_shift;
                phase     <= ARMED;
                win       <= 1'b1;
            end
            if (phase == ARMED && start) begin
                work  <= acc_in * mult_cfg;
                cnt   <= shift_cfg;
                run   <= 1'b1;
                phase <= BUSY;
            end
            if (phase == DONE && ack)
                phase <= IDLE;
            if (run) begin
                if (cnt == {SW{1'b0}}) begin
                    out_q <= work;
                    run   <= 1'b0;
                    phase <= DONE;
                end else begin
                    work <= work >> 1;
                    cnt  <= cnt - 1'b1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(phase))
            assert ($stable(out_q));
endmodule

