module mem_autopd #(
    parameter W = 64,
    parameter [W-1:0] DEF_THRESH = 64'd4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         activity,
    input  wire         thr_we,
    input  wire [W-1:0] thr_din,
    output reg          pd_req,
    output reg  [W-1:0] idle_cnt
);
    typedef enum logic [1:0] {ACTIVE = 2'd0, COUNTING = 2'd1, POWERDN = 2'd2} state_t;

    state_t state;
    reg [W-1:0] threshold;
    reg pv;

    initial begin
        state     = ACTIVE;
        threshold = DEF_THRESH;
        pd_req    = 1'b0;
        idle_cnt  = {W{1'b0}};
        pv        = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (thr_we && state == ACTIVE)
                threshold <= thr_din;
            if (activity) begin
                state    <= ACTIVE;
                idle_cnt <= {W{1'b0}};
                pd_req   <= 1'b0;
            end else begin
                case (state)
                    ACTIVE: begin
                        state    <= COUNTING;
                        idle_cnt <= {{(W-1){1'b0}}, 1'b1};
                    end
                    COUNTING: begin
                        if (idle_cnt >= threshold) begin
                            state  <= POWERDN;
                            pd_req <= 1'b1;
                        end else begin
                            idle_cnt <= idle_cnt + {{(W-1){1'b0}}, 1'b1};
                        end
                    end
                    POWERDN: begin
                        state <= POWERDN;
                    end
                    default: begin
                        state    <= ACTIVE;
                        idle_cnt <= {W{1'b0}};
                        pd_req   <= 1'b0;
                    end
                endcase
            end
        end
    end

    always @(posedge clk)
        if (pv && pd_req && $stable(pd_req))
            assert ($stable(idle_cnt));
endmodule

