module pam4_gray_mapper #(
    parameter W = 64
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         load,
    input  wire         precode,
    input  wire [W-1:0] data,
    output reg  [1:0]   sym_out,
    output reg          sym_valid
);
    localparam [63:0] NSYM = W / 2;

    reg [W-1:0] stage;
    reg [63:0]  sym_left;
    reg [63:0]  deadline;
    reg [1:0]   prev_sym;
    reg         armed;

    initial begin
        stage     = {W{1'b0}};
        sym_left  = 64'd0;
        deadline  = 64'd0;
        prev_sym  = 2'd0;
        sym_out   = 2'd0;
        sym_valid = 1'b0;
        armed     = 1'b0;
    end

    wire [1:0] pair  = stage[1:0];
    wire [1:0] gray  = {pair[1], pair[1] ^ pair[0]};
    wire [1:0] sum4  = gray + prev_sym;
    wire [1:0] coded = precode ? sum4 : gray;

    always @(posedge clk) begin
        if (rst) begin
            stage     <= {W{1'b0}};
            sym_left  <= 64'd0;
            deadline  <= 64'd0;
            prev_sym  <= 2'd0;
            sym_out   <= 2'd0;
            sym_valid <= 1'b0;
        end else if (ce) begin
            sym_valid <= 1'b0;
            if (sym_left == 64'd0) begin
                if (load) begin
                    stage    <= data;
                    sym_left <= NSYM;
                    deadline <= NSYM;
                    armed    <= 1'b1;
                end
            end else begin
                sym_out   <= coded;
                sym_valid <= 1'b1;
                prev_sym  <= coded;
                stage     <= stage >> 2;
                sym_left  <= sym_left - 64'd1;
                deadline  <= deadline - 64'd1;
            end
        end
    end

    always @(posedge clk)
        if (armed && sym_left != 64'd0)
            assert (deadline != 64'd0);

    always @(posedge clk)
        if (armed && sym_left == 64'd0)
            assert (deadline == 64'd0);
endmodule

