module pkt_boundary_mux #(
    parameter NSRC = 4,
    parameter DW   = 64,
    parameter CW   = 64
) (
    input  wire               clk,
    input  wire               rst,
    input  wire               step,
    input  wire [NSRC-1:0]    valid,
    input  wire [NSRC-1:0]    eop,
    input  wire [NSRC*DW-1:0] in_data,
    output wire               out_valid,
    output wire               out_eop,
    output wire [DW-1:0]      out_data,
    output wire [$clog2(NSRC)-1:0] out_src
);
    localparam SW = $clog2(NSRC);

    reg [SW-1:0] cur_src;
    reg          locked;
    reg          win;
    reg          started;
    reg [CW-1:0] arm_cnt;
    reg [CW-1:0] start_cnt;
    reg [CW-1:0] fin_cnt;
    reg [CW-1:0] tot_beats;

    initial begin
        cur_src   = {SW{1'b0}};
        locked    = 1'b0;
        win       = 1'b0;
        started   = 1'b0;
        arm_cnt   = {CW{1'b0}};
        start_cnt = {CW{1'b0}};
        fin_cnt   = {CW{1'b0}};
        tot_beats = {CW{1'b0}};
    end

    reg [SW-1:0] pick;
    reg          any_valid;
    integer i;
    always @(*) begin
        any_valid = 1'b0;
        pick = {SW{1'b0}};
        for (i = NSRC-1; i >= 0; i = i - 1)
            if (valid[i]) begin
                any_valid = 1'b1;
                pick = i;
            end
    end

    wire sel_valid = valid[cur_src];
    wire sel_eop   = eop[cur_src];
    wire beat      = locked && sel_valid;

    assign out_valid = step && beat;
    assign out_eop   = step && beat && sel_eop;
    assign out_data  = in_data[cur_src*DW +: DW];
    assign out_src   = cur_src;

    always @(posedge clk) begin
        if (rst) begin
            cur_src   <= {SW{1'b0}};
            locked    <= 1'b0;
            win       <= 1'b0;
            started   <= 1'b0;
            arm_cnt   <= {CW{1'b0}};
            start_cnt <= {CW{1'b0}};
            fin_cnt   <= {CW{1'b0}};
            tot_beats <= {CW{1'b0}};
        end else if (step) begin
            if (!locked) begin
                if (any_valid) begin
                    cur_src <= pick;
                    locked  <= 1'b1;
                    win     <= 1'b1;
                    arm_cnt <= arm_cnt + 1'b1;
                end
            end else if (sel_valid) begin
                tot_beats <= tot_beats + 1'b1;
                if (!started)
                    start_cnt <= start_cnt + 1'b1;
                if (sel_eop) begin
                    fin_cnt <= fin_cnt + 1'b1;
                    locked  <= 1'b0;
                    win     <= 1'b0;
                    started <= 1'b0;
                end else begin
                    started <= 1'b1;
                end
            end
        end
    end

    always @(*)
        assert (!win || (((arm_cnt - start_cnt) <= 64'd1) && ((start_cnt - fin_cnt) <= 64'd1)));
endmodule

