                last_id <= sel_id;
            if (claim_ok)
                inflight_cnt <= inflight_cnt + 16'd1;
            else if (do_dec)
                inflight_cnt <= inflight_cnt - 16'd1;
            if (claim_ok)
                armed <= 1'b1;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed)
            assert (!$stable(inflight_cnt) || $stable(inflight));
