module first_ready_latch #(
    parameter NCH  = 4,
    parameter IDXW = 2,
    parameter CW   = 64
) (
    input  wire            clk,
    input  wire            rst,
    input  wire            ce,
    input  wire            arm,
    input  wire            clr,
    input  wire [NCH-1:0]  ch_rdy,
    output reg  [IDXW-1:0] winner,
    output reg             captured,
    output reg             armed,
    output reg  [CW-1:0]   cap_cnt
);
    initial begin
        winner   = {IDXW{1'b0}};
        captured = 1'b0;
        armed    = 1'b0;
        cap_cnt  = {CW{1'b0}};
    end

    reg [IDXW-1:0] first_idx;
    integer i;
    always @(*) begin
        first_idx = {IDXW{1'b0}};
        for (i = NCH-1; i >= 0; i = i - 1)
            if (ch_rdy[i]) first_idx = i[IDXW-1:0];
    end

    wire any_rdy = |ch_rdy;

    always @(posedge clk) begin
        if (rst) begin
            winner   <= {IDXW{1'b0}};
            captured <= 1'b0;
            armed    <= 1'b0;
            cap_cnt  <= {CW{1'b0}};
        end else if (ce) begin
            if (clr) begin
                armed    <= 1'b0;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (arm) begin
                armed    <= 1'b1;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (armed && !captured && any_rdy) begin
                captured <= 1'b1;
                winner   <= first_idx;
                cap_cnt  <= cap_cnt + {{(CW-1){1'b0}}, 1'b1};
            end
        end
    end

    always @(*) assert (!armed || cap_cnt <= 64'd1);
endmodule

