module noc_freq_meter #(
    parameter GATE = 8
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        in_valid,
    output wire        in_ready,
    input  wire        in_edge,
    output reg         out_valid,
    input  wire        out_ready,
    output reg  [31:0] result
);
    reg [31:0] gate_cnt;
    reg [31:0] ev_cnt;
    reg [31:0] gate_snap;
    reg        armed;

    initial begin
        gate_cnt  = 32'd0;
        ev_cnt    = 32'd0;
        gate_snap = 32'd0;
        result    = 32'd0;
        out_valid = 1'b0;
        armed     = 1'b0;
    end

    assign in_ready = !out_valid;
    wire in_fire    = in_valid && in_ready;
    wire out_fire   = out_valid && out_ready;
    wire gate_close = in_fire && (gate_cnt == GATE - 1);

    always @(posedge clk) begin
        if (rst) begin
            gate_cnt  <= 32'd0;
            ev_cnt    <= 32'd0;
            gate_snap <= 32'd0;
            result    <= 32'd0;
            out_valid <= 1'b0;
            armed     <= 1'b0;
        end else begin
            if (in_fire)
                armed <= 1'b1;
            if (in_fire) begin
                if (gate_close) begin
                    gate_cnt  <= 32'd0;
                    ev_cnt    <= 32'd0;
                    result    <= ev_cnt + {31'd0, in_edge};
                    gate_snap <= gate_cnt + 32'd1;
                    out_valid <= 1'b1;
                end else begin
                    gate_cnt <= gate_cnt + 32'd1;
                    ev_cnt   <= ev_cnt + {31'd0, in_edge};
                end
            end else if (out_fire) begin
                out_valid <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed && out_valid)
            assert (result <= gate_snap);
endmodule

