module apb_periph_ctrl #(
    parameter NREG = 12,
    parameter [31:0] WAIT = 32'd3,
    parameter [31:0] K = WAIT + 32'd2
)(
    input  wire        clk,
    input  wire        i_ce,
    input  wire        req_valid,
    output wire        req_ready,
    input  wire        req_write,
    input  wire [3:0]  req_addr,
    input  wire [31:0] req_wdata,
    output reg  [31:0] rdata,
    output reg         pslverr_o,
    output wire        psel,
    output reg         penable
);
    typedef enum logic [1:0] {IDLE = 2'd0, SETUP = 2'd1, ACCESS = 2'd2} state_t;

    state_t     state;
    reg [31:0]  timer;
    reg [31:0]  wait_cnt;
    reg [3:0]   sel;
    reg         wr;
    reg [31:0]  wdata;
    reg         err;
    reg         armed;
    reg [31:0]  regs [0:NREG-1];

    integer i;
    initial begin
        state     = IDLE;
        timer     = 32'd0;
        wait_cnt  = 32'd0;
        sel       = 4'd0;
        wr        = 1'b0;
        wdata     = 32'd0;
        err       = 1'b0;
        armed     = 1'b1;
        rdata     = 32'd0;
        pslverr_o = 1'b0;
        penable   = 1'b0;
        for (i = 0; i < NREG; i = i + 1) regs[i] = 32'd0;
    end

    assign req_ready = i_ce && (state == IDLE);
    assign psel      = (state != IDLE);

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                IDLE: begin
                    if (req_valid) begin
                        state <= SETUP;
                        timer <= K;
                        wr    <= req_write;
                        wdata <= req_wdata;
                        if (req_addr < NREG) begin
                            sel <= req_addr;
                            err <= 1'b0;
                        end else begin
                            sel <= 4'd0;
                            err <= 1'b1;
                        end
                    end
                end
                SETUP: begin
                    state    <= ACCESS;
                    penable  <= 1'b1;
                    timer    <= timer - 32'd1;
                    wait_cnt <= WAIT;
                end
                ACCESS: begin
                    if (wait_cnt == 32'd0) begin
                        state     <= IDLE;
                        penable   <= 1'b0;
                        timer     <= 32'd0;
                        pslverr_o <= err;
                        if (err)
                            armed <= 1'b0;
                        else if (wr)
                            regs[sel] <= wdata;
                        else
                            rdata <= regs[sel];
                    end else begin
                        wait_cnt <= wait_cnt - 32'd1;
                        timer    <= timer - 32'd1;
                    end
                end
                default: begin
                    state   <= IDLE;
                    penable <= 1'b0;
                    timer   <= 32'd0;
                end
            endcase
        end
    end

    // Bounded response, before the first slave error:
    // the completion countdown never expires while a transfer is outstanding
    always @(posedge clk)
        if (armed && state != IDLE) assert (timer != 32'd0);

    // during the access phase the countdown always outlasts the remaining wait states
    always @(posedge clk)
        if (armed && penable) assert (timer > wait_cnt);
endmodule

