    reg [SW-1:0] op_sig   = {SW{1'b0}};
    reg [7:0]    op_scale = 8'd0;
    reg [EW-1:0] work_exp = {EW{1'b0}};
    reg [SW-1:0] work_sig = {SW{1'b0}};
    reg          work_ovf = 1'b0;
    reg          work_uf  = 1'b0;
    reg          sticky   = 1'b0;
    reg [EW-1:0] res_exp  = {EW{1'b0}};
    reg [SW-1:0] res_sig  = {SW{1'b0}};
    reg          res_ovf  = 1'b0;
    reg          res_uf   = 1'b0;
    reg          no_ovf   = 1'b1;
    reg          pv       = 1'b0;

    wire [EW+1:0] sum   = {2'b00, op_exp} + {{2{op_scale[7]}}, op_scale};
    wire [EW+1:0] under = {{(EW+1){1'b0}}, 1'b1} - sum;
    wire          sum_neg = sum[EW+1];
    wire          sum_ovf = !sum_neg && (sum[EW:0] >= {1'b0, EXP_INF});
    wire          sum_unf = sum_neg || (sum == {(EW+2){1'b0}});
    wire [3:0]    sh_amt  = (under > MAXSH) ? MAXSH4 : under[3:0];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= IDLE;
            busy     <= 1'b0;
            sh_cnt   <= 4'd0;
            op_exp   <= {EW{1'b0}};
            op_sig   <= {SW{1'b0}};
            op_scale <= 8'd0;
            work_exp <= {EW{1'b0}};
            work_sig <= {SW{1'b0}};
            work_ovf <= 1'b0;
            work_uf  <= 1'b0;
            sticky   <= 1'b0;
            res_exp  <= {EW{1'b0}};
            res_sig  <= {SW{1'b0}};
            res_ovf  <= 1'b0;
            res_uf   <= 1'b0;
            no_ovf   <= 1'b1;
        end else if (ce) begin
            case (phase)
                IDLE: if (arm) begin
                    op_exp   <= exp_in;
                    op_sig   <= sig_in;
                    op_scale <= scale_in;
                    phase    <= ARMED;
                end
                ARMED: if (start) begin
                    busy   <= 1'b1;
                    sticky <= 1'b0;
                    phase  <= STARTED;
                    if (sum_ovf) begin
                        work_exp <= EXP_INF;
                        work_sig <= {SW{1'b0}};
                        work_ovf <= 1'b1;
                        work_uf  <= 1'b0;
                        sh_cnt   <= 4'd0;
                    end else if (sum_unf) begin
                        work_exp <= {EW{1'b0}};
                        work_sig <= op_sig;
                        work_ovf <= 1'b0;
                        work_uf  <= 1'b1;
                        sh_cnt   <= sh_amt;
                    end else begin
                        work_exp <= sum[EW-1:0];
                        work_sig <= op_sig;
                        work_ovf <= 1'b0;
                        work_uf  <= 1'b0;
                        sh_cnt   <= 4'd0;
                    end
                end
                STARTED: if (sh_cnt == 4'd0) phase <= FINISHED;
                FINISHED: phase <= IDLE;
            endcase
            if (busy) begin
                if (sh_cnt != 4'd0) begin
                    work_sig <= work_sig >> 1;
                    sticky   <= sticky | work_sig[0];
                    sh_cnt   <= sh_cnt - 4'd1;
                end else begin
                    res_exp <= work_exp;
                    res_sig <= work_sig;
                    res_ovf <= work_ovf;
                    res_uf  <= work_uf & (sticky | (work_sig == {SW{1'b0}}));
                    busy    <= 1'b0;
                    if (work_ovf) no_ovf <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    assign o_exp  = res_exp;
    assign o_sig  = res_sig;
    assign o_ovf  = res_ovf;
    assign o_uf   = res_uf;
    assign o_done = (phase == FINISHED);

    always @(posedge clk)
        if (pv && no_ovf && $stable(phase))
            assert ($stable(res_exp) && $stable(res_sig));
endmodule


