module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

