module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  stat_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [15:0] start_cnt;
reg [15:0] stop_cnt;
reg [15:0] beat_cnt;
reg [7:0]  wrap_cnt;
reg [15:0] idle_cnt;
reg        err_sticky;
reg [1:0]  stat_sel;
reg [127:0] pf_data [0:3];
reg [3:0]   pf_tag  [0:3];
reg [1:0]   pf_wp;
reg [1:0]   pf_rp;
reg [2:0]   pf_used;

    initial begin
start_cnt  = 16'd0;
stop_cnt   = 16'd0;
beat_cnt   = 16'd0;
wrap_cnt   = 8'd0;
idle_cnt   = 16'd0;
err_sticky = 1'b0;
stat_sel   = 2'd0;
stat_o     = 32'h0;
pf_data[0] = 128'h0;
pf_data[1] = 128'h0;
pf_data[2] = 128'h0;
pf_data[3] = 128'h0;
pf_tag[0]  = 4'd0;
pf_tag[1]  = 4'd0;
pf_tag[2]  = 4'd0;
pf_tag[3]  = 4'd0;
pf_wp      = 2'd0;
pf_rp      = 2'd0;
pf_used    = 3'd0;
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end
   // shared crossbar lane: this source owns the even arbitration slots
   wire       slot_gnt    = ~stat_sel[0];
   wire       pf_full     = (pf_used == 3'd4);
   wire       pf_empty    = (pf_used == 3'd0);
   wire       pf_push     = win && !pf_full;
   wire       pf_pop      = win && !pf_empty && slot_gnt;
   wire [3:0] pf_head_tag = pf_tag[pf_rp];
   wire       pf_last     = (pf_head_tag == 4'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
start_cnt  <= 16'd0;
stop_cnt   <= 16'd0;
beat_cnt   <= 16'd0;
wrap_cnt   <= 8'd0;
idle_cnt   <= 16'd0;
err_sticky <= 1'b0;
stat_sel   <= 2'd0;
stat_o     <= 32'h0;
pf_data[0] <= 128'h0;
pf_data[1] <= 128'h0;
pf_data[2] <= 128'h0;
pf_data[3] <= 128'h0;
pf_tag[0]  <= 4'd0;
pf_tag[1]  <= 4'd0;
pf_tag[2]  <= 4'd0;
pf_tag[3]  <= 4'd0;
pf_wp      <= 2'd0;
pf_rp      <= 2'd0;
pf_used    <= 3'd0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
if (start)
    start_cnt <= start_cnt + 16'd1;
if (stop)
    stop_cnt <= stop_cnt + 16'd1;
if (start && stop)
    err_sticky <= 1'b1;
if (win && !start && !stop) begin
    beat_cnt <= beat_cnt + 16'd1;
   if (pf_pop && pf_last)
        wrap_cnt <= wrap_cnt + 8'd1;
end
if (!win)
    idle_cnt <= idle_cnt + 16'd1;
stat_sel <= stat_sel + 2'd1;
case (stat_sel)
    2'd0: stat_o <= {start_cnt, stop_cnt};
    2'd1: stat_o <= {beat_cnt, idle_cnt};
   2'd2: stat_o <= {5'h0, pf_used, wrap_cnt, 15'h0, err_sticky};
    default: stat_o <= {err_sticky, 7'h0, wrap_cnt, beat_cnt};
endcase
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
               pf_wp   <= 2'd0;
               pf_rp   <= 2'd0;
               pf_used <= 3'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
               if (pf_push) begin
                   pf_data[pf_wp] <= rom_word;
                   pf_tag[pf_wp]  <= {1'b0, rd_ptr};
                   pf_wp          <= pf_wp + 2'd1;
                   rd_ptr         <= rd_ptr + 3'd1;
               end
               if (pf_pop) begin
                   out_q <= pf_data[pf_rp];
                   out_v <= 1'b1;
                   pf_rp <= pf_rp + 2'd1;
                   if (pf_last)
                       cnt <= 4'd0;
                   else
                       cnt <= cnt + 4'd1;
               end
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

