            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
st0_q <= 128'h0; st1_q <= 128'h0; st2_q <= 128'h0; st3_q <= 128'h0;
st0_idx <= 3'd0; st1_idx <= 3'd0; st2_idx <= 3'd0; st3_idx <= 3'd0;
st0_v <= 1'b0; st1_v <= 1'b0; st2_v <= 1'b0; st3_v <= 1'b0;
start_cnt <= 8'd0;
stop_cnt  <= 8'd0;
beat_cnt  <= 16'd0;
csum      <= 16'd0;
idle_wdog <= 12'd0;
wdog_flag <= 1'b0;
err_flag  <= 1'b0;
seq_err   <= 1'b0;
last_tag  <= 3'd7;
dbg_stat  <= 32'd0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
st0_v  <= 1'b0;
st1_v  <= 1'b0;
st2_v  <= 1'b0;
st3_v  <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
st0_q   <= rom_word;
st0_idx <= rd_ptr;
st0_v   <= 1'b1;
st1_q   <= st0_q;
st1_idx <= st0_idx;
st1_v   <= st0_v;
st2_q   <= st1_q;
st2_idx <= st1_idx;
st2_v   <= st1_v;
st3_q   <= st2_q;
st3_idx <= st2_idx;
st3_v   <= st2_v;
if (st3_v) begin
out_q <= st3_q;
out_v <= 1'b1;
if (st3_idx == 3'd7)
cnt <= 4'd0;
else
cnt <= cnt + 4'd1;
end
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                end
            end
        end
if (rst_n) begin
if (en) begin
if (start)
start_cnt <= start_cnt + 8'd1;
if (stop)
stop_cnt <= stop_cnt + 8'd1;
if (start && stop)
err_flag <= 1'b1;
if (start || win)
idle_wdog <= 12'd0;
else if (idle_wdog != 12'hFFF)
idle_wdog <= idle_wdog + 12'd1;
if (idle_wdog == 12'hFFE)
wdog_flag <= 1'b1;
if (start)
last_tag <= 3'd7;
if (win && !start && !stop && st3_v) begin
beat_cnt <= beat_cnt + 16'd1;
csum     <= {csum[14:0], csum[15]} ^ st3_q[15:0] ^ st3_q[127:112];
last_tag <= st3_idx;
if (st3_idx != last_tag + 3'd1)
seq_err <= 1'b1;
end
end
dbg_stat <= {wdog_flag, err_flag, seq_err, idle_wdog[4:0], start_cnt ^ stop_cnt, beat_cnt ^ csum};
end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
    assign cnt_o = cnt;
    assign rd_ptr_o = rd_ptr;
    assign st0_idx_o = st0_idx;
    assign st0_v_o = st0_v;
    assign st1_idx_o = st1_idx;
