    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

