                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
// monitor-side decodes
wire bad_k        = i_ce && i_k && !do_comma && !do_sof && !do_eof;
wire mon_pkt_data = do_data && (phase == PH_PKT);
wire [15:0] len_nxt = cur_len + 16'd1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
idle_cnt <= 16'd0; wdog_cnt <= 12'd0; cur_len <= 16'd0; rd_hist <= 8'd0;
last_kcode <= 2'd0; bad_k_seen <= 1'b0;
o_err_cnt <= 16'd0; o_max_len <= 16'd0; o_wdog <= 1'b0; o_mon_status <= 8'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
if (!rst) begin
// idle cycle counter (saturating)
if (!i_ce && (idle_cnt != 16'hFFFF)) idle_cnt <= idle_cnt + 16'd1;
// illegal / out-of-sequence control symbol logger
if (bad_k) begin
bad_k_seen <= 1'b1;
if (o_err_cnt != 16'hFFFF) o_err_cnt <= o_err_cnt + 16'd1;
end
if (i_ce && i_k) last_kcode <= i_kcode;
// comma watchdog
if (do_comma) begin
wdog_cnt <= 12'd0;
o_wdog   <= 1'b0;
end else if (wdog_cnt != WDOG_LIMIT) begin
wdog_cnt <= wdog_cnt + 12'd1;
end else begin
o_wdog   <= 1'b1;
end
// packet payload length tracker
if (do_sof) begin
cur_len <= 16'd0;
end else if (mon_pkt_data && (cur_len != 16'hFFFF)) begin
cur_len <= len_nxt;
if (len_nxt > o_max_len) o_max_len <= len_nxt;
end
// running disparity history
if (i_ce) rd_hist <= {rd_hist[6:0], o_rd};
o_mon_status <= {bad_k_seen, (idle_cnt[15:12] != 4'd0), last_kcode, rd_hist[3:0]};
end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

Find strengthening invariant(s): facts about the design's reachable states that
(a) hold in every reachable state, and (b) together with the properties make
the set inductive, closing the proof by k-induction for EVERY assertion - an
invariant list that proves one assertion but leaves another failing is not a
solution.

Reply with JSON: {"invariants": ["<expr>", ...]} where each entry is a single
Verilog boolean expression over the module's signals. No other output.

Format rules for each expression - violations make the answer ungradeable:
- plain synthesizable Verilog only: no `->` (write `!a || b` for implication),
  no `$past` or other system functions, no SVA operators, no prose
- complete expressions only, with sized constants (`4'd8`, not `8`)
- TOP-LEVEL signal names only: every expression is evaluated in the top
  module. State inside a sub-module is visible only through the wires its
  instance drives - use those names. A sub-module-internal name (even
  without a dot) does not exist at the top level and voids the answer.

Here is a SystemVerilog design. It contains ONE OR MORE properties, written as
immediate assertions - count them; a design with sub-modules may carry an
assertion inside a sub-module as well as one at the top. Every assertion is
true of the design but the set is NOT provable by k-induction on its own: a
prover starting from an arbitrary state can violate at least one of them.

module tplan_px_drain (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire abort_req,
   input wire frame_act,
   input wire push,
   input wire push_eof,
   input wire [7:0] push_pix,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire ready,
   output wire drained,
   output wire eof_pend_o,
   output wire [2:0] fill_o,
   output wire [4:0] col_o,
   output wire [7:0] px_o,
   output wire px_vld_o,
   output wire px_eol_o,
   output wire hblank_o,
   output wire [7:0] sig_o,
   output wire [7:0] stall_o
);
   localparam [2:0] DEPTH = 3'd4;
   localparam [4:0] LINE_LAST = 5'd23;

   reg [7:0] fifo [0:3];
   reg [1:0] wr_ptr;
   reg [1:0] rd_ptr;
   reg [2:0] cnt;
   reg [3:0] cfg_div;
   reg [3:0] cfg_hblank;
   reg       cfg_inv;
   reg [7:0] cfg_blank;
   reg [3:0] div_cnt;
   reg [3:0] hb_cnt;
   reg [4:0] col_out;
   reg [7:0] px_q;
   reg       px_vld;
   reg       px_eol;
   reg       eof_pend;
   reg [7:0] sig_run;
   reg [7:0] sig_last;
   reg [7:0] stall_cnt;

   integer j;
   initial begin
       for (j = 0; j < 4; j = j + 1)
           fifo[j] = 8'h00;
   end
   initial wr_ptr = 2'd0;
   initial rd_ptr = 2'd0;
   initial cnt = 3'd0;
   initial cfg_div = 4'd0;
   initial cfg_hblank = 4'd0;
   initial cfg_inv = 1'b0;
   initial cfg_blank = 8'h00;
   initial div_cnt = 4'd0;
   initial hb_cnt = 4'd0;
   initial col_out = 5'd0;
   initial px_q = 8'h00;
   initial px_vld = 1'b0;
   initial px_eol = 1'b0;
   initial eof_pend = 1'b0;
   initial sig_run = 8'h00;
   initial sig_last = 8'h00;
   initial stall_cnt = 8'd0;

   function [7:0] crc8_step;
       input [7:0] c;
       input [7:0] d;
       integer b;
       reg [7:0] x;
       begin
           x = c ^ d;
           for (b = 0; b < 8; b = b + 1)
               x = x[7] ? ((x << 1) ^ 8'h07) : (x << 1);
           crc8_step = x;
       end
   endfunction

   wire full = (cnt == DEPTH);
   wire empty = (cnt == 3'd0);
   wire tick = (div_cnt == 4'd0);
   wire in_hb = (hb_cnt != 4'd0);
   wire acc = push && !full;
   wire pop = tick && !in_hb && !empty;
   wire [7:0] head_pix = fifo[rd_ptr] ^ {8{cfg_inv}};

   assign ready = !full;
   assign drained = eof_pend && empty && tick && !in_hb;
   assign eof_pend_o = eof_pend;
   assign fill_o = cnt;
   assign col_o = col_out;
   assign px_o = px_q;
   assign px_vld_o = px_vld;
   assign px_eol_o = px_eol;
   assign hblank_o = in_hb;
   assign sig_o = sig_last;
   assign stall_o = stall_cnt;

   always @(posedge clk) begin
       if (!rst_n) begin
           for (j = 0; j < 4; j = j + 1)
               fifo[j] <= 8'h00;
           wr_ptr <= 2'd0;
           rd_ptr <= 2'd0;
           cnt <= 3'd0;
           cfg_div <= 4'd0;
           cfg_hblank <= 4'd0;
           cfg_inv <= 1'b0;
           cfg_blank <= 8'h00;
           div_cnt <= 4'd0;
           hb_cnt <= 4'd0;
           col_out <= 5'd0;
           px_q <= 8'h00;
           px_vld <= 1'b0;
           px_eol <= 1'b0;
           eof_pend <= 1'b0;
           sig_run <= 8'h00;
           sig_last <= 8'h00;
           stall_cnt <= 8'd0;
       end else if (en) begin
           if (frame_act && full && !abort_req && (stall_cnt != 8'hFF))
               stall_cnt <= stall_cnt + 8'd1;
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: cfg_hblank <= csr_wdata[3:0];
                   3'd6: begin
                       cfg_inv <= csr_wdata[0];
                       if (csr_wdata[7])
                           stall_cnt <= 8'd0;
                   end
                   3'd7: cfg_blank <= csr_wdata;
               endcase
           end
           if (abort_req) begin
               wr_ptr <= 2'd0;
               rd_ptr <= 2'd0;
               cnt <= 3'd0;
               div_cnt <= 4'd0;
               hb_cnt <= 4'd0;
               col_out <= 5'd0;
               px_q <= cfg_blank;
               px_vld <= 1'b0;
               px_eol <= 1'b0;
               eof_pend <= 1'b0;
               sig_run <= 8'h00;
           end else begin
               if (acc) begin
                   fifo[wr_ptr] <= push_pix;
                   wr_ptr <= wr_ptr + 2'd1;
                   if (push_eof)
                       eof_pend <= 1'b1;
               end
               if (acc && !pop)
                   cnt <= cnt + 3'd1;
               else if (pop && !acc)
                   cnt <= cnt - 3'd1;
               if (!tick)
                   div_cnt <= div_cnt - 4'd1;
               else if (pop || in_hb)
                   div_cnt <= cfg_div;
               if (tick) begin
                   if (in_hb) begin
                       hb_cnt <= hb_cnt - 4'd1;
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end else if (pop) begin
                       px_q <= head_pix;
                       px_vld <= 1'b1;
                       rd_ptr <= rd_ptr + 2'd1;
                       sig_run <= crc8_step(sig_run, head_pix);
                       if (col_out == LINE_LAST) begin
                           col_out <= 5'd0;
                           hb_cnt <= cfg_hblank;
                           px_eol <= 1'b1;
                       end else begin
                           col_out <= col_out + 5'd1;
                           px_eol <= 1'b0;
                       end
                   end else begin
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end
               end
               if (drained) begin
                   eof_pend <= 1'b0;
                   sig_last <= sig_run;
                   sig_run <= 8'h00;
               end
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire [7:0] o_scan_pix,
  output wire o_scan_vld,
  output wire o_scan_eol,
  output wire o_scan_hblank,
  output wire o_scan_ready,
  output wire o_drain_busy,
  output wire [7:0] o_scan_fill_col,
  output wire [7:0] o_frame_sig,
  output wire [7:0] o_scan_stall
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
  wire dr_ready, dr_drained, dr_eof_pend;
  wire dr_px_vld, dr_px_eol, dr_hblank;
  wire [2:0] dr_fill;
  wire [4:0] dr_col;
  wire [7:0] dr_px;
  wire [7:0] dr_sig;
  wire [7:0] dr_stall;
  wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
  wire px_push = (phase == RUN) && !abort_req && dr_ready;
  wire frame_end = px_push && last_col && last_row;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  tplan_px_drain u_drain (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .abort_req(abort_req),
      .frame_act(phase == RUN),
      .push(px_push),
      .push_eof(last_col && last_row),
      .push_pix(gen_pix),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .ready(dr_ready),
      .drained(dr_drained),
      .eof_pend_o(dr_eof_pend),
      .fill_o(dr_fill),
      .col_o(dr_col),
      .px_o(dr_px),
      .px_vld_o(dr_px_vld),
      .px_eol_o(dr_px_eol),
      .hblank_o(dr_hblank),
      .sig_o(dr_sig),
      .stall_o(dr_stall)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
