module toast_spi_cs_keeper (
   input  wire        clk,
   input  wire        rst,
   input  wire        en,
   input  wire        hold_done,
   input  wire        gap_end,
   input  wire        launch,
   input  wire        q_empty,
   input  wire [4:0]  head_slv,
   input  wire [4:0]  sel,
   output wire        keep,
   output wire        merge,
   output wire [23:0] rel_mask,
   output wire        held_o,
   output wire [2:0]  burst_o,
   output wire [2:0]  peak_o,
   output wire [7:0]  merge_cnt_o,
   output wire [7:0]  brk_cnt_o,
  output wire [23:0] merged_mask_o,
  output wire [2:0]  burst_nx_o
);
   localparam [2:0] MAX_BURST = 3'd4;

   reg        held        = 1'b0;
   reg [2:0]  burst       = 3'd0;
   reg [2:0]  peak        = 3'd0;
   reg [7:0]  merge_cnt   = 8'd0;
   reg [7:0]  brk_cnt     = 8'd0;
   reg [23:0] merged_mask = 24'd0;

   // CS is carried into the gap when the burst has room and the next frame
   // targets the same slave, or the queue is empty (linger for a follow-up).
   wire       same_slv = (head_slv == sel);
   wire       room     = (burst < MAX_BURST);
   wire       cont     = held && launch && same_slv;
   wire       broken   = held && gap_end && !cont;
   wire [2:0] burst_nx = cont ? burst + 3'd1 : 3'd0;

   assign keep          = hold_done && room && (q_empty || same_slv);
   assign merge         = held && same_slv;
   assign rel_mask      = held ? (24'd1 << sel) : 24'd0;
   assign held_o        = held;
   assign burst_o       = burst;
   assign peak_o        = peak;
   assign merge_cnt_o   = merge_cnt;
   assign brk_cnt_o     = brk_cnt;
   assign merged_mask_o = merged_mask;
  assign burst_nx_o    = burst_nx;

   always @(posedge clk) begin
       if (rst) begin
           held        <= 1'b0;
           burst       <= 3'd0;
           peak        <= 3'd0;
           merge_cnt   <= 8'd0;
           brk_cnt     <= 8'd0;
           merged_mask <= 24'd0;
       end else if (en) begin
           if (hold_done)
               held <= keep;
           else if (gap_end)
               held <= 1'b0;

           if (launch) begin
               burst <= burst_nx;
               if (burst_nx > peak)
                   peak <= burst_nx;
           end

           if (cont) begin
               if (merge_cnt != 8'hFF)
                   merge_cnt <= merge_cnt + 8'd1;
               merged_mask <= merged_mask | (24'd1 << sel);
           end

           if (broken && brk_cnt != 8'hFF)
               brk_cnt <= brk_cnt + 8'd1;
       end
   end
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
   output wire         full,
   output wire         cs_held,
   output wire [2:0]   cs_burst,
   output wire [2:0]   cs_peak_burst,
   output wire [7:0]   cs_merge_count,
   output wire [7:0]   cs_break_count,
  output wire [23:0]  cs_merged_slaves,
  output wire         trc_d,
  output wire         trc_frm,
  output wire         trc_eor,
  output wire         trc_rdy,
  output wire         trc_busy,
  output wire [3:0]   trc_level,
  output wire [3:0]   trc_hwm,
  output wire [4:0]   trc_last_slv,
  output wire [7:0]   trc_seq
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

   // Trace port: every launched frame posts a record into an 8-entry
   // record FIFO; a serializer ships records out on trc_d with a CRC-8.
   localparam [1:0] TX_IDLE = 2'd0;
   localparam [1:0] TX_BODY = 2'd1;
   localparam [1:0] TX_CRC  = 2'd2;
   localparam [1:0] TX_GAP  = 2'd3;
   localparam [7:0] TX_LAST = 8'd178;
   localparam [7:0] TX_IFG  = 8'd3;

   reg [4:0]   lg_slv [0:7];
   reg [2:0]   lg_pos [0:7];
   reg         lg_mrg [0:7];
   reg         lg_fst [0:7];
   reg [7:0]   lg_tsu [0:7];
   reg [7:0]   lg_prv [0:7];
   reg [7:0]   lg_seq [0:7];
   reg [15:0]  lg_ts  [0:7];
   reg [127:0] lg_dat [0:7];
   reg [3:0]   lg_wp  = 4'd0;
   reg [3:0]   lg_rp  = 4'd0;
   reg [3:0]   lg_hwm = 4'd0;
   reg [7:0]   fr_seq = 8'd0;
   reg [15:0]  ts_gap = 16'd0;

   // Per-slave history: sequence number of the last frame sent to a slave
   reg [7:0]   sl_seq [0:23];
   reg [23:0]  sl_seen = 24'd0;

   // Output stage between the record FIFO and the serializer
   reg         oh_vld = 1'b0;
   reg [4:0]   oh_slv = 5'd0;
   reg [2:0]   oh_pos = 3'd0;
   reg         oh_mrg = 1'b0;
   reg         oh_fst = 1'b0;
   reg [7:0]   oh_tsu = 8'd0;
   reg [7:0]   oh_prv = 8'd0;
   reg [7:0]   oh_seq = 8'd0;
   reg [15:0]  oh_ts  = 16'd0;
   reg [127:0] oh_dat = 128'd0;

   reg [1:0]   tx_st  = TX_IDLE;
   reg [7:0]   tx_cnt = 8'd0;
   reg [178:0] tx_sh  = 179'd0;
   reg [7:0]   tx_crc = 8'd0;
   reg         tx_out = 1'b0;
   reg         tx_frm = 1'b0;
   reg         tx_eor = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
           sl_seq[i] = 8'd0;
        end
       for (i = 0; i < 8; i = i + 1) begin
           lg_slv[i] = 5'd0;
           lg_pos[i] = 3'd0;
           lg_mrg[i] = 1'b0;
           lg_fst[i] = 1'b0;
           lg_tsu[i] = 8'd0;
           lg_prv[i] = 8'd0;
           lg_seq[i] = 8'd0;
           lg_ts[i]  = 16'd0;
           lg_dat[i] = 128'd0;
       end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

   wire [2:0]   lg_wi    = lg_wp[2:0];
   wire [2:0]   lg_ri    = lg_rp[2:0];
   wire [2:0]   lg_last  = lg_wi - 3'd1;
   wire [3:0]   lg_used  = lg_wp - lg_rp;
   wire         lg_empty = (lg_wp == lg_rp);
   wire         lg_full  = (lg_wp == {~lg_rp[3], lg_rp[2:0]});
   wire         lg_rdy   = !lg_full;
   wire         tx_take  = (tx_st == TX_IDLE) && oh_vld;
   wire         oh_load  = !lg_empty && (!oh_vld || tx_take);
   wire         tx_bit   = tx_sh[178];
   wire         tx_cnt_z = (tx_cnt == 8'd0);
   wire         crc_fb   = tx_crc[7] ^ tx_bit;
   wire [7:0]   crc_nx   = {tx_crc[6:0], 1'b0} ^ (crc_fb ? 8'h07 : 8'h00);
   wire [178:0] tx_rec   = {1'b1, oh_slv, oh_pos, oh_mrg, oh_fst, oh_tsu,
                            oh_prv, oh_seq, oh_ts, oh_dat};


   wire can_pop = (count != 5'd0) && lg_rdy &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
   wire [3:0] lg_used_nx = lg_used + {3'd0, can_pop} - {3'd0, oh_load};
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

   wire        hold_done = (st == ST_HOLD) && (dly == 8'd0);
   wire        gap_end   = (st == ST_GAP) && (dly == 8'd0);
   wire        cs_keep;
   wire        cs_merge;
   wire [23:0] cs_rel;
   wire        kp_held;
   wire [2:0]  kp_burst;
   wire [2:0]  kp_peak;
  wire [2:0]  kp_burst_nx;

   toast_spi_cs_keeper u_keeper (
       .clk           (clk),
       .rst           (rst),
       .en            (en),
       .hold_done     (hold_done),
       .gap_end       (gap_end),
       .launch        (can_pop),
       .q_empty       (count == 5'd0),
       .head_slv      (head_slv),
       .sel           (sel),
       .keep          (cs_keep),
       .merge         (cs_merge),
       .rel_mask      (cs_rel),
       .held_o        (kp_held),
       .burst_o       (kp_burst),
       .peak_o        (kp_peak),
       .merge_cnt_o   (cs_merge_count),
       .brk_cnt_o     (cs_break_count),
      .merged_mask_o (cs_merged_slaves),
      .burst_nx_o    (kp_burst_nx)
   );

   assign cs_held       = kp_held;
   assign cs_burst      = kp_burst;
   assign cs_peak_burst = kp_peak;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

   assign trc_d        = tx_out;
   assign trc_frm      = tx_frm;
   assign trc_eor      = tx_eor;
   assign trc_rdy      = lg_rdy;
   assign trc_busy     = !lg_empty || oh_vld || (tx_st != TX_IDLE);
   assign trc_level    = lg_used;
   assign trc_hwm      = lg_hwm;
   assign trc_last_slv = lg_slv[lg_last];
   assign trc_seq      = fr_seq;

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
           lg_wp   <= 4'd0;
           lg_rp   <= 4'd0;
           lg_hwm  <= 4'd0;
           fr_seq  <= 8'd0;
           ts_gap  <= 16'd0;
           sl_seen <= 24'd0;
           oh_vld  <= 1'b0;
           oh_slv  <= 5'd0;
           oh_pos  <= 3'd0;
           oh_mrg  <= 1'b0;
           oh_fst  <= 1'b0;
           oh_tsu  <= 8'd0;
           oh_prv  <= 8'd0;
           oh_seq  <= 8'd0;
           oh_ts   <= 16'd0;
           oh_dat  <= 128'd0;
           tx_st   <= TX_IDLE;
           tx_cnt  <= 8'd0;
           tx_sh   <= 179'd0;
           tx_crc  <= 8'd0;
           tx_out  <= 1'b0;
           tx_frm  <= 1'b0;
           tx_eor  <= 1'b0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

           // Trace capture: every launch posts one record. Launches are
           // held off by lg_rdy, so a record is never dropped.
           if (can_pop) begin
               lg_slv[lg_wi]    <= head_slv;
               lg_pos[lg_wi]    <= kp_burst_nx;
               lg_mrg[lg_wi]    <= cs_merge;
               lg_fst[lg_wi]    <= !sl_seen[head_slv];
               lg_tsu[lg_wi]    <= cs_merge ? 8'd0 : cfg_setup;
               lg_prv[lg_wi]    <= sl_seq[head_slv];
               lg_seq[lg_wi]    <= fr_seq;
               lg_ts[lg_wi]     <= ts_gap;
               lg_dat[lg_wi]    <= head_dat;
               lg_wp            <= lg_wp + 4'd1;
               fr_seq           <= fr_seq + 8'd1;
               sl_seq[head_slv] <= fr_seq;
               sl_seen          <= sl_seen | (24'd1 << head_slv);
               ts_gap           <= 16'd0;
           end else if (ts_gap != 16'hFFFF)
               ts_gap <= ts_gap + 16'd1;
           if (lg_used_nx > lg_hwm)
               lg_hwm <= lg_used_nx;

           // Output stage refills whenever empty or being handed over
           if (oh_load) begin
               oh_vld <= 1'b1;
               oh_slv <= lg_slv[lg_ri];
               oh_pos <= lg_pos[lg_ri];
               oh_mrg <= lg_mrg[lg_ri];
               oh_fst <= lg_fst[lg_ri];
               oh_tsu <= lg_tsu[lg_ri];
               oh_prv <= lg_prv[lg_ri];
               oh_seq <= lg_seq[lg_ri];
               oh_ts  <= lg_ts[lg_ri];
               oh_dat <= lg_dat[lg_ri];
               lg_rp  <= lg_rp + 4'd1;
           end else if (tx_take)
               oh_vld <= 1'b0;

           // Serializer: start bit + record body, then CRC-8, then a gap
           if ((tx_st != TX_IDLE) && !tx_cnt_z)
               tx_cnt <= tx_cnt - 8'd1;
           tx_eor <= 1'b0;
           case (tx_st)
               TX_IDLE: begin
                   if (tx_take) begin
                       tx_sh  <= tx_rec;
                       tx_cnt <= TX_LAST;
                       tx_crc <= 8'd0;
                       tx_st  <= TX_BODY;
                   end
               end
               TX_BODY: begin
                   tx_out <= tx_bit;
                   tx_frm <= 1'b1;
                   tx_crc <= crc_nx;
                   tx_sh  <= {tx_sh[177:0], 1'b0};
                   if (tx_cnt_z) begin
                       tx_cnt <= 8'd7;
                       tx_st  <= TX_CRC;
                   end
               end
               TX_CRC: begin
                   tx_out <= tx_crc[7];
                   tx_crc <= {tx_crc[6:0], 1'b0};
                   if (tx_cnt_z) begin
                       tx_cnt <= TX_IFG;
                       tx_eor <= 1'b1;
                       tx_st  <= TX_GAP;
                   end
               end
               default: begin
                   tx_out <= 1'b0;
                   tx_frm <= 1'b0;
                   if (tx_cnt_z)
                       tx_st <= TX_IDLE;
               end
           endcase

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                       if (!cs_keep)
                           cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                       cs_vec <= (cs_vec & ~cs_rel) | (24'd1 << head_slv);
                        shreg  <= head_dat;
                       dly    <= cs_merge ? 8'd0 : cfg_setup;
                        st     <= ST_SETUP;
                   end else begin
                       cs_vec <= cs_vec & ~cs_rel;
                       st     <= ST_IDLE;
                   end
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);

   // While a frame is on the wire, the newest trace record names the
   // asserted slave select and the keeper's burst position for it.
   always @(posedge clk)
       if (st == ST_SETUP || st == ST_XFER || st == ST_HOLD)
           assert (cs_vec == (24'd1 << lg_slv[lg_last]) &&
                   lg_pos[lg_last] == kp_burst);
endmodule

