module lookup_req_queue #(
   parameter DEPTH = 4,
   parameter AW    = 2
) (
   input  wire          clk,
   input  wire          rst,
   input  wire          ce,
   input  wire          push,
   input  wire [63:0]   push_key,
   input  wire [15:0]   push_len,
   input  wire          pop,
   input  wire          tbl_wr,
   input  wire [6:0]    tbl_idx,
   output wire          ready,
   output wire          avail,
   output wire [63:0]   head_key,
   output wire [15:0]   head_len,
   output reg  [AW:0]   count,
   output reg  [6:0]    hwm,
   output wire [6:0]    scan_lim
);
   reg [63:0]   key_q [0:DEPTH-1];
   reg [15:0]   len_q [0:DEPTH-1];
   reg [AW-1:0] wr_ptr;
   reg [AW-1:0] rd_ptr;

   integer n;
   initial begin
       for (n = 0; n < DEPTH; n = n + 1) begin
           key_q[n] = 64'd0;
           len_q[n] = 16'd0;
       end
       wr_ptr = {AW{1'b0}};
       rd_ptr = {AW{1'b0}};
       count  = {(AW+1){1'b0}};
       hwm    = 7'd0;
   end

   assign ready    = (count != DEPTH);
   assign avail    = (count != {(AW+1){1'b0}});
   assign head_key = key_q[rd_ptr];
   assign head_len = len_q[rd_ptr];
   // highest rule index that can hold a valid entry, including a write landing this cycle
   assign scan_lim = (tbl_wr && (tbl_idx > hwm)) ? tbl_idx : hwm;

   wire do_push = push && ready;
   wire do_pop  = pop && avail;

   always @(posedge clk) begin
       if (rst) begin
           wr_ptr <= {AW{1'b0}};
           rd_ptr <= {AW{1'b0}};
           count  <= {(AW+1){1'b0}};
           hwm    <= 7'd0;
       end else if (ce) begin
           if (do_push) begin
               key_q[wr_ptr] <= push_key;
               len_q[wr_ptr] <= push_len;
               wr_ptr        <= wr_ptr + 1'b1;
           end
           if (do_pop)
               rd_ptr <= rd_ptr + 1'b1;
           if (do_push && !do_pop)
               count <= count + 1'b1;
           else if (do_pop && !do_push)
               count <= count - 1'b1;
           if (tbl_wr)
               hwm <= scan_lim;
       end
   end
endmodule

module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
output reg  [6:0]  rsp_rule,
output wire        req_ready,
output wire [2:0]  req_pending,
output wire [6:0]  scan_limit
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;
reg [6:0]  q_lim;

wire        rq_ready;
wire        rq_avail;
wire [63:0] rq_key;
wire [15:0] rq_len;
wire [2:0]  rq_count;
wire [6:0]  rq_hwm;
wire [6:0]  rq_scan_lim;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
q_lim      = 7'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
wire last = (idx == q_lim);

lookup_req_queue #(.DEPTH(4), .AW(2)) u_req_q (
    .clk      (clk),
    .rst      (rst),
    .ce       (i_ce),
    .push     (req),
    .push_key (req_key),
    .push_len (req_len),
    .pop      (!busy),
    .tbl_wr   (wr_en && !busy),
    .tbl_idx  (wr_idx),
    .ready    (rq_ready),
    .avail    (rq_avail),
    .head_key (rq_key),
    .head_len (rq_len),
    .count    (rq_count),
    .hwm      (rq_hwm),
    .scan_lim (rq_scan_lim)
);

assign req_ready   = rq_ready;
assign req_pending = rq_count;
assign scan_limit  = rq_hwm;

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
q_lim     <= 7'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
if (rq_avail) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
timer <= {1'b0, rq_scan_lim} + 8'd1;
q_key <= rq_key;
q_len <= {48'd0, rq_len};
q_lim <= rq_scan_lim;
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
endmodule

