        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;
   lookup_scheduler #(
       .RQ_AW(2),
       .WQ_AW(2),
       .TAG_W(4)
   ) u_sched (
