       .in_key(req_key),
       .in_len(req_len),
       .in_ready(req_ready),
       .in_tag(req_tag),
       .in_wr(wr_en),
       .in_wr_idx(wr_idx),
       .in_wr_key(wr_key),
       .in_wr_action(wr_action),
       .wr_ready(wr_ready),
       .tb_rsp_valid(rsp_valid),
       .tb_rsp_hit(rsp_hit),
       .tb_req(s_req),
       .tb_key(s_key),
       .tb_len(s_len),
       .tb_wr(s_wr),
       .tb_wr_idx(s_wr_idx),
       .tb_wr_key(s_wr_key),
       .tb_wr_action(s_wr_action),
       .done_valid(lk_done),
       .done_hit(lk_hit),
       .done_tag(lk_tag),
       .pend_o(sch_pend),
       .rq_cnt_o(rq_cnt),
       .wq_cnt_o(wq_cnt),
       .rq_hwm_o(rq_hwm),
       .miss_cnt_o(miss_cnt_o)
   );
   assign sch_pend_o = sch_pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
