   output wire [31:0] o_hist_z,
   output wire        o_hist_md,
   output wire        o_hist_src,
   output wire [7:0]  o_hist_tag,
   output wire [7:0]  o_hist_lag,
   output wire [31:0] o_hist_sum,
   output wire [7:0]  o_job_seq,
   output wire [7:0]  o_n_qlaunch,
   output wire [7:0]  o_n_dbl,
   output wire [7:0]  o_n_add
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
   localparam [2:0]  JQ_DEPTH = 3'd4;
   reg        jq_mode [0:3];
   reg        jq_ld   [0:3];
   reg [31:0] jq_seed [0:3];
   reg [1:0]  jq_wp;
   reg [1:0]  jq_rp;
   reg [2:0]  jq_cnt;
   reg [2:0]  jq_hwm;
   reg        jq_ovf;
   reg [7:0]  jq_drop;
   reg [7:0]  n_qlaunch;
   reg [31:0] hist_x   [0:3];
   reg [31:0] hist_y   [0:3];
   reg [31:0] hist_z   [0:3];
   reg        hist_md  [0:3];
   reg        hist_src [0:3];
   reg [7:0]  hist_tag [0:3];
   reg [1:0]  hist_wp;
   reg        hist_wrap;
   reg [31:0] hist_sum;
   reg [7:0]  job_seq;
   reg        job_src;
   reg [7:0]  n_dbl;
   reg [7:0]  n_add;

    integer i;
   integer k;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
       jq_wp     = 2'd0;
       jq_rp     = 2'd0;
       jq_cnt    = 3'd0;
       jq_hwm    = 3'd0;
       jq_ovf    = 1'b0;
       jq_drop   = 8'd0;
       n_qlaunch = 8'd0;
       hist_wp   = 2'd0;
       hist_wrap = 1'b0;
       hist_sum  = 32'd0;
       job_seq   = 8'd0;
       job_src   = 1'b0;
       n_dbl     = 8'd0;
       n_add     = 8'd0;
       for (i = 0; i < 4; i = i + 1) begin
           jq_mode[i]  = 1'b0;
           jq_ld[i]    = 1'b0;
           jq_seed[i]  = 32'd0;
           hist_x[i]   = 32'd0;
           hist_y[i]   = 32'd0;
           hist_z[i]   = 32'd0;
           hist_md[i]  = 1'b0;
           hist_src[i] = 1'b0;
           hist_tag[i] = 8'd0;
       end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
   wire        idle       = (step == 32'd0);
   wire        jq_empty   = (jq_cnt == 3'd0);
   wire        jq_full    = (jq_cnt == JQ_DEPTH);
   wire        req_ok     = start && armed && !clr;
   wire        q_launch   = en && idle && !clr && !jq_empty;
   wire        d_launch   = en && idle && req_ok && jq_empty;
   wire        job_launch = q_launch || d_launch;
   wire        req_queue  = en && req_ok && (!idle || !jq_empty);
   wire        jq_pop     = q_launch;
   wire        jq_push    = req_queue && (!jq_full || jq_pop);
   wire        jq_reject  = req_queue && jq_full && !jq_pop;
   wire [2:0]  jq_nxt_cnt = jq_cnt + {2'd0, jq_push} - {2'd0, jq_pop};
   wire [1:0]  jq_tail    = jq_wp - 2'd1;
   wire        hd_mode    = jq_mode[jq_rp];
   wire        hd_ld      = jq_ld[jq_rp];
   wire [31:0] hd_seed    = jq_seed[jq_rp];
   wire        nxt_mode   = q_launch ? hd_mode : sel_add;
   wire        job_end    = en && (step == LAST);
   wire [31:0] hist_nsum  = fadd(hist_sum, y3);
   wire [1:0]  hist_ra    = hist_wp - 2'd1 - wr_addr[1:0];
   wire [2:0]  hist_cnt   = hist_wrap ? 3'd4 : {1'b0, hist_wp};
   wire        hist_hit   = ({1'b0, wr_addr[1:0]} < hist_cnt);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
           jq_wp     <= 2'd0;
           jq_rp     <= 2'd0;
           jq_cnt    <= 3'd0;
           jq_hwm    <= 3'd0;
           jq_ovf    <= 1'b0;
           jq_drop   <= 8'd0;
           n_qlaunch <= 8'd0;
           hist_wp   <= 2'd0;
           hist_wrap <= 1'b0;
           hist_sum  <= 32'd0;
           job_seq   <= 8'd0;
           job_src   <= 1'b0;
           n_dbl     <= 8'd0;
           n_add     <= 8'd0;
           for (k = 0; k < 4; k = k + 1) begin
               jq_mode[k]  <= 1'b0;
               jq_ld[k]    <= 1'b0;
               jq_seed[k]  <= 32'd0;
               hist_x[k]   <= 32'd0;
               hist_y[k]   <= 32'd0;
               hist_z[k]   <= 32'd0;
               hist_md[k]  <= 1'b0;
               hist_src[k] <= 1'b0;
               hist_tag[k] <= 8'd0;
           end
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
               if (job_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
               if (job_launch) begin
                    step <= 32'd1;
                   mode    <= nxt_mode;
                   job_seq <= job_seq + 8'd1;
                   job_src <= q_launch;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
           if (clr) begin
               jq_wp  <= 2'd0;
               jq_rp  <= 2'd0;
               jq_cnt <= 3'd0;
               jq_ovf <= 1'b0;
           end else begin
               if (jq_push) begin
                   jq_mode[jq_wp] <= sel_add;
                   jq_ld[jq_wp]   <= wr_en;
                   jq_seed[jq_wp] <= wr_data;
                   jq_wp          <= jq_wp + 2'd1;
               end
               if (jq_pop) begin
                   jq_rp     <= jq_rp + 2'd1;
                   n_qlaunch <= n_qlaunch + 8'd1;
               end
               jq_cnt <= jq_nxt_cnt;
               if (jq_reject) begin
                   jq_ovf <= 1'b1;
                   if (jq_drop != 8'hFF)
                       jq_drop <= jq_drop + 8'd1;
               end
           end
           if (jq_cnt > jq_hwm)
               jq_hwm <= jq_cnt;
           if (job_end) begin
               hist_x[hist_wp]   <= rf[12];
               hist_y[hist_wp]   <= y3;
               hist_z[hist_wp]   <= z3;
               hist_md[hist_wp]  <= mode;
               hist_src[hist_wp] <= job_src;
               hist_tag[hist_wp] <= job_seq;
               hist_wp           <= hist_wp + 2'd1;
               if (hist_wp == 2'd3)
                   hist_wrap <= 1'b1;
               hist_sum <= hist_nsum;
               if (mode)
                   n_add <= n_add + 8'd1;
               else
                   n_dbl <= n_dbl + 8'd1;
           end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
               if (q_launch && hd_ld)
                   rf[0] <= hd_seed;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];
   assign o_jq_cnt    = jq_cnt;
   assign o_jq_hwm    = jq_hwm;
   assign o_jq_full   = jq_full;
   assign o_jq_ovf    = jq_ovf;
   assign o_jq_drop   = jq_drop;
   assign o_jq_hmode  = jq_empty ? 1'b0 : hd_mode;
   assign o_jq_hseed  = (jq_empty || !hd_ld) ? 32'd0 : hd_seed;
   assign o_jq_tmode  = jq_empty ? 1'b0 : jq_mode[jq_tail];
   assign o_jq_tseed  = (jq_empty || !jq_ld[jq_tail]) ? 32'd0 : jq_seed[jq_tail];
   assign o_busy      = !idle || !jq_empty;
   assign o_hist_cnt  = hist_cnt;
   assign o_hist_hit  = hist_hit;
   assign o_hist_x    = hist_hit ? hist_x[hist_ra]   : 32'd0;
   assign o_hist_y    = hist_hit ? hist_y[hist_ra]   : 32'd0;
   assign o_hist_z    = hist_hit ? hist_z[hist_ra]   : 32'd0;
   assign o_hist_md   = hist_hit ? hist_md[hist_ra]  : 1'b0;
   assign o_hist_src  = hist_hit ? hist_src[hist_ra] : 1'b0;
   assign o_hist_tag  = hist_hit ? hist_tag[hist_ra] : 8'd0;
   assign o_hist_lag  = hist_hit ? (job_seq - hist_tag[hist_ra]) : 8'd0;
   assign o_hist_sum  = hist_sum;
   assign o_job_seq   = job_seq;
   assign o_n_qlaunch = n_qlaunch;
   assign o_n_dbl     = n_dbl;
   assign o_n_add     = n_add;

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

