                                   phase <= FIN;
                                   frame_cnt <= frame_cnt + 64'd1;
                               end else begin
                                   row_cnt <= row_cnt + 64'd1;
                               end
                           end else begin
                               col_cnt <= col_cnt + 64'd1;
                           end
                       end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
               if (scan_pop) begin
                   scan_pix <= head_pix;
                   scan_eof <= head_eof;
                   scan_eol <= scan_line_end || head_eof;
                   pixq_rd_ptr <= pixq_rd_ptr + 3'd1;
                   if (head_eof) begin
                       scan_col <= 5'd0;
                       scan_row <= 3'd0;
                       scan_frames <= scan_frames + 64'd1;
                       done <= 1'b1;
                   end else if (scan_line_end) begin
                       scan_col <= 5'd0;
                       scan_row <= scan_row + 3'd1;
