module fm_link_lock_ctl (
   input  wire       clk,
   input  wire       rst,
   input  wire       i_comma,
   input  wire       i_sof_req,
   input  wire       i_eof,
   input  wire       i_dsym,
   input  wire       i_in_pkt,
   input  wire [7:0] i_byte,
   output reg        o_sof_ok,
   output reg        o_locked,
   output reg  [1:0] o_comma_run,
   output reg  [3:0] o_idle_run,
   output reg  [7:0] o_pkt_len,
   output reg        o_len_err,
   output reg  [7:0] o_pkt_sum,
   output reg  [7:0] o_last_sum,
   output reg  [7:0] o_sof_rej,
   output reg  [7:0] o_lock_loss,
   output wire [3:0] o_status
);
   localparam [1:0] RUN_MAX  = 2'd3;
   localparam [3:0] IDLE_MAX = 4'd15;
   localparam [7:0] LEN_MAX  = 8'd192;
   localparam [7:0] CNT_MAX  = 8'hff;
   // lock is held once four back-to-back commas have been observed
   wire lock_next = o_locked || (o_comma_run == RUN_MAX);
   // start-of-frame admission: a request is only honoured while armed
   wire sof_take  = i_sof_req && o_sof_ok;
   wire sof_drop  = i_sof_req && !o_sof_ok;
   // data symbols seen outside a packet are treated as line noise
   wire idle_dat  = i_dsym && !i_in_pkt;
   wire pkt_dat   = i_dsym && i_in_pkt;
   wire idle_trip = idle_dat && (o_idle_run == IDLE_MAX);
   wire len_hit   = pkt_dat && (o_pkt_len == LEN_MAX);
   assign o_status = {o_len_err, (o_sof_rej != 8'd0), o_sof_ok, o_locked};
   initial begin
       o_sof_ok = 1'b0; o_locked = 1'b0; o_comma_run = 2'd0; o_idle_run = 4'd0;
       o_pkt_len = 8'd0; o_len_err = 1'b0; o_pkt_sum = 8'd0; o_last_sum = 8'd0;
       o_sof_rej = 8'd0; o_lock_loss = 8'd0;
   end
   // alignment tracking: acquire on a comma run, drop on a noise run
   always @(posedge clk) begin
       if (rst) begin
           o_locked    <= 1'b0;
           o_comma_run <= 2'd0;
           o_idle_run  <= 4'd0;
           o_lock_loss <= 8'd0;
       end else if (i_comma) begin
           o_locked    <= lock_next;
           o_idle_run  <= 4'd0;
           if (o_comma_run != RUN_MAX) o_comma_run <= o_comma_run + 2'd1;
       end else if (idle_trip) begin
           o_locked    <= 1'b0;
           o_comma_run <= 2'd0;
           o_idle_run  <= 4'd0;
           if (o_locked && (o_lock_loss != CNT_MAX)) o_lock_loss <= o_lock_loss + 8'd1;
       end else if (idle_dat) begin
           o_idle_run  <= o_idle_run + 4'd1;
           if (!o_locked) o_comma_run <= 2'd0;
       end
   end
   // start-of-frame arm flag and refused-request counter
   always @(posedge clk) begin
       if (rst) begin
           o_sof_ok  <= 1'b0;
           o_sof_rej <= 8'd0;
       end else if (i_comma) begin
           o_sof_ok  <= !i_in_pkt && lock_next;
       end else if (sof_take) begin
           o_sof_ok  <= 1'b0;
       end else if (sof_drop) begin
           if (o_sof_rej != CNT_MAX) o_sof_rej <= o_sof_rej + 8'd1;
       end else if (i_eof) begin
           o_sof_ok  <= o_locked;
       end else if (idle_trip) begin
           o_sof_ok  <= 1'b0;
       end
   end
   // in-packet length limit and running checksum
   always @(posedge clk) begin
       if (rst) begin
           o_pkt_len  <= 8'd0;
           o_len_err  <= 1'b0;
           o_pkt_sum  <= 8'd0;
           o_last_sum <= 8'd0;
       end else if (sof_take) begin
           o_pkt_len  <= 8'd0;
           o_len_err  <= 1'b0;
           o_pkt_sum  <= 8'd0;
       end else if (pkt_dat) begin
           if (o_pkt_len != CNT_MAX) o_pkt_len <= o_pkt_len + 8'd1;
           if (len_hit) o_len_err <= 1'b1;
           o_pkt_sum  <= o_pkt_sum + i_byte;
       end else if (i_eof) begin
           o_last_sum <= o_pkt_sum;
       end
   end
endmodule
