    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
   wire sof_req  = i_ce && i_k && (i_kcode == K_SOF);
   wire do_sof   = sof_req && o_sof_ok;
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
   // link alignment and frame admission controller
   fm_link_lock_ctl u_lock (
       .clk         (clk),
       .rst         (rst),
       .i_comma     (do_comma),
       .i_sof_req   (sof_req),
       .i_eof       (do_eof),
       .i_dsym      (do_data),
       .i_in_pkt    (phase == PH_PKT),
       .i_byte      (i_data),
       .o_sof_ok    (o_sof_ok),
       .o_locked    (o_locked),
       .o_comma_run (o_comma_run),
       .o_idle_run  (o_idle_run),
       .o_pkt_len   (o_pkt_len),
       .o_len_err   (o_len_err),
       .o_pkt_sum   (o_pkt_sum),
       .o_last_sum  (o_last_sum),
       .o_sof_rej   (o_sof_rej),
       .o_lock_loss (o_lock_loss),
       .o_status    (o_link_status)
   );

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

Find strengthening invariant(s): facts about the design's reachable states that
(a) hold in every reachable state, and (b) together with the properties make
the set inductive, closing the proof by k-induction for EVERY assertion - an
invariant list that proves one assertion but leaves another failing is not a
solution.

Reply with JSON: {"invariants": ["<expr>", ...]} where each entry is a single
Verilog boolean expression over the module's signals. No other output.

Format rules for each expression - violations make the answer ungradeable:
- plain synthesizable Verilog only: no `->` (write `!a || b` for implication),
  no `$past` or other system functions, no SVA operators, no prose
- complete expressions only, with sized constants (`4'd8`, not `8`)
- TOP-LEVEL signal names only: every expression is evaluated in the top
  module. State inside a sub-module is visible only through the wires its
  instance drives - use those names. A sub-module-internal name (even
  without a dot) does not exist at the top level and voids the answer.

Here is a SystemVerilog design. It contains ONE OR MORE properties, written as
immediate assertions - count them; a design with sub-modules may carry an
assertion inside a sub-module as well as one at the top. Every assertion is
true of the design but the set is NOT provable by k-induction on its own: a
prover starting from an arbitrary state can violate at least one of them.

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
   output wire [31:0] o_x3,
   output wire [2:0]  o_jq_cnt,
   output wire [2:0]  o_jq_hwm,
   output wire        o_jq_full,
   output wire        o_jq_ovf,
   output wire [7:0]  o_jq_drop,
   output wire        o_jq_hmode,
   output wire [31:0] o_jq_hseed,
   output wire        o_jq_tmode,
   output wire [31:0] o_jq_tseed,
   output wire        o_busy,
   output wire [2:0]  o_hist_cnt,
   output wire        o_hist_hit,
   output wire [31:0] o_hist_x,
   output wire [31:0] o_hist_y,
   output wire [31:0] o_hist_z,
   output wire        o_hist_md,
   output wire        o_hist_src,
   output wire [7:0]  o_hist_tag,
   output wire [7:0]  o_hist_lag,
   output wire [31:0] o_hist_sum,
   output wire [7:0]  o_job_seq,
   output wire [7:0]  o_n_qlaunch,
   output wire [7:0]  o_n_dbl,
output wire [7:0]  o_n_add,
output wire        o_wd_trip,
output wire [15:0] o_wd_cnt,
output wire [15:0] o_wd_max,
output wire [15:0] o_q_age,
output wire [15:0] o_q_age_max,
output wire [3:0]  o_err_code,
output wire [3:0]  o_err_first,
output wire [7:0]  o_err_cnt,
output wire [7:0]  o_err_tag,
output wire [31:0] o_err_acc,
output wire [31:0] o_cyc,
output wire [31:0] o_busy_cyc,
output wire [31:0] o_idle_cyc,
output wire [15:0] o_n_wr,
output wire [15:0] o_n_mul,
output wire [15:0] o_n_aop,
output wire [15:0] o_n_sop,
output wire [7:0]  o_ign_start,
output wire [7:0]  o_n_clr,
output wire [31:0] o_sig,
output wire [31:0] o_dbg_rd,
output wire [7:0]  o_dbg_wcnt,
output wire [31:0] o_acc_min,
output wire [31:0] o_acc_max
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];
   localparam [2:0]  JQ_DEPTH = 3'd4;
   reg        jq_mode [0:3];
   reg        jq_ld   [0:3];
   reg [31:0] jq_seed [0:3];
   reg [1:0]  jq_wp;
   reg [1:0]  jq_rp;
   reg [2:0]  jq_cnt;
   reg [2:0]  jq_hwm;
   reg        jq_ovf;
   reg [7:0]  jq_drop;
   reg [7:0]  n_qlaunch;
   reg [31:0] hist_x   [0:3];
   reg [31:0] hist_y   [0:3];
   reg [31:0] hist_z   [0:3];
   reg        hist_md  [0:3];
   reg        hist_src [0:3];
   reg [7:0]  hist_tag [0:3];
   reg [1:0]  hist_wp;
   reg        hist_wrap;
   reg [31:0] hist_sum;
   reg [7:0]  job_seq;
   reg        job_src;
   reg [7:0]  n_dbl;
   reg [7:0]  n_add;
  localparam [15:0] WD_LIMIT = 16'd12;
  localparam [15:0] QA_LIMIT = 16'd48;
  localparam [31:0] SIG_POLY = 32'h04C11DB7;
  reg [15:0] wd_cnt;
  reg [15:0] wd_max;
  reg        wd_trip;
  reg [15:0] q_age;
  reg [15:0] q_age_max;
  reg [3:0]  err_code;
  reg [3:0]  err_first;
  reg        err_seen;
  reg [7:0]  err_cnt;
  reg [7:0]  err_tag;
  reg [31:0] err_acc;
  reg [31:0] cyc;
  reg [31:0] busy_cyc;
  reg [31:0] idle_cyc;
  reg [15:0] n_wr;
  reg [15:0] n_mul;
  reg [15:0] n_aop;
  reg [15:0] n_sop;
  reg [7:0]  ign_start;
  reg [7:0]  n_clr;
  reg [31:0] sig;
  reg [31:0] dbg_bank [0:3];
  reg [7:0]  dbg_wcnt;
  reg [31:0] acc_min;
  reg [31:0] acc_max;
  reg        acc_seen;

    integer i;
   integer k;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
       jq_wp     = 2'd0;
       jq_rp     = 2'd0;
       jq_cnt    = 3'd0;
       jq_hwm    = 3'd0;
       jq_ovf    = 1'b0;
       jq_drop   = 8'd0;
       n_qlaunch = 8'd0;
       hist_wp   = 2'd0;
       hist_wrap = 1'b0;
       hist_sum  = 32'd0;
       job_seq   = 8'd0;
       job_src   = 1'b0;
       n_dbl     = 8'd0;
       n_add     = 8'd0;
      wd_cnt    = 16'd0;
      wd_max    = 16'd0;
      wd_trip   = 1'b0;
      q_age     = 16'd0;
      q_age_max = 16'd0;
      err_code  = 4'd0;
      err_first = 4'd0;
      err_seen  = 1'b0;
      err_cnt   = 8'd0;
      err_tag   = 8'd0;
      err_acc   = 32'd0;
      cyc       = 32'd0;
      busy_cyc  = 32'd0;
      idle_cyc  = 32'd0;
      n_wr      = 16'd0;
      n_mul     = 16'd0;
      n_aop     = 16'd0;
      n_sop     = 16'd0;
      ign_start = 8'd0;
      n_clr     = 8'd0;
      sig       = 32'hFFFFFFFF;
      dbg_wcnt  = 8'd0;
      acc_min   = 32'd0;
      acc_max   = 32'd0;
      acc_seen  = 1'b0;
      for (i = 0; i < 4; i = i + 1)
          dbg_bank[i] = 32'd0;
       for (i = 0; i < 4; i = i + 1) begin
           jq_mode[i]  = 1'b0;
           jq_ld[i]    = 1'b0;
           jq_seed[i]  = 32'd0;
           hist_x[i]   = 32'd0;
           hist_y[i]   = 32'd0;
           hist_z[i]   = 32'd0;
           hist_md[i]  = 1'b0;
           hist_src[i] = 1'b0;
           hist_tag[i] = 8'd0;
       end
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);
   wire        idle       = (step == 32'd0);
   wire        jq_empty   = (jq_cnt == 3'd0);
   wire        jq_full    = (jq_cnt == JQ_DEPTH);
   wire        req_ok     = start && armed && !clr;
   wire        q_launch   = en && idle && !clr && !jq_empty;
   wire        d_launch   = en && idle && req_ok && jq_empty;
   wire        job_launch = q_launch || d_launch;
   wire        req_queue  = en && req_ok && (!idle || !jq_empty);
   wire        jq_pop     = q_launch;
   wire        jq_push    = req_queue && (!jq_full || jq_pop);
   wire        jq_reject  = req_queue && jq_full && !jq_pop;
   wire [2:0]  jq_nxt_cnt = jq_cnt + {2'd0, jq_push} - {2'd0, jq_pop};
   wire [1:0]  jq_tail    = jq_wp - 2'd1;
   wire        hd_mode    = jq_mode[jq_rp];
   wire        hd_ld      = jq_ld[jq_rp];
   wire [31:0] hd_seed    = jq_seed[jq_rp];
   wire        nxt_mode   = q_launch ? hd_mode : sel_add;
   wire        job_end    = en && (step == LAST);
   wire [31:0] hist_nsum  = fadd(hist_sum, y3);
   wire [1:0]  hist_ra    = hist_wp - 2'd1 - wr_addr[1:0];
   wire [2:0]  hist_cnt   = hist_wrap ? 3'd4 : {1'b0, hist_wp};
   wire        hist_hit   = ({1'b0, wr_addr[1:0]} < hist_cnt);
  wire        dbg_wr     = en && wr_en && !idle;
  wire [1:0]  dbg_wa     = wr_addr[1:0];
  wire [1:0]  dbg_ra     = wr_addr[3:2];
  wire        wd_active  = !idle;
  wire        wd_over    = (wd_cnt >= WD_LIMIT);
  wire        ev_reject  = jq_reject;
  wire        ev_ign     = en && start && !clr && !armed;
  wire        ev_clrbusy = en && clr && (!idle || !jq_empty);
  wire        ev_rearm   = en && arm && armed && !clr;
  wire        ev_wd      = en && wd_over && !wd_trip;
  wire        ev_qa      = en && (q_age == QA_LIMIT);
  wire        ev_any     = ev_reject || ev_ign || ev_clrbusy ||
                           ev_rearm || ev_wd || ev_qa;
  wire [3:0]  ev_code    = ev_wd      ? 4'd5 :
                           ev_qa      ? 4'd6 :
                           ev_reject  ? 4'd1 :
                           ev_clrbusy ? 4'd2 :
                           ev_ign     ? 4'd3 :
                           ev_rearm   ? 4'd4 : 4'd0;
  wire [31:0] sig_sh     = {sig[30:0], 1'b0} ^ (sig[31] ? SIG_POLY : 32'd0);
  wire [31:0] sig_nxt    = sig_sh ^ y3 ^ {24'd0, job_seq};
  wire        op_live    = !idle && (step != LAST);
  wire        new_min    = !acc_seen || (y3 < acc_min);
  wire        new_max    = !acc_seen || (y3 > acc_max);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
           jq_wp     <= 2'd0;
           jq_rp     <= 2'd0;
           jq_cnt    <= 3'd0;
           jq_hwm    <= 3'd0;
           jq_ovf    <= 1'b0;
           jq_drop   <= 8'd0;
           n_qlaunch <= 8'd0;
           hist_wp   <= 2'd0;
           hist_wrap <= 1'b0;
           hist_sum  <= 32'd0;
           job_seq   <= 8'd0;
           job_src   <= 1'b0;
           n_dbl     <= 8'd0;
           n_add     <= 8'd0;
          wd_cnt    <= 16'd0;
          wd_max    <= 16'd0;
          wd_trip   <= 1'b0;
          q_age     <= 16'd0;
          q_age_max <= 16'd0;
          err_code  <= 4'd0;
          err_first <= 4'd0;
          err_seen  <= 1'b0;
          err_cnt   <= 8'd0;
          err_tag   <= 8'd0;
          err_acc   <= 32'd0;
          cyc       <= 32'd0;
          busy_cyc  <= 32'd0;
          idle_cyc  <= 32'd0;
          n_wr      <= 16'd0;
          n_mul     <= 16'd0;
          n_aop     <= 16'd0;
          n_sop     <= 16'd0;
          ign_start <= 8'd0;
          n_clr     <= 8'd0;
          sig       <= 32'hFFFFFFFF;
          dbg_wcnt  <= 8'd0;
          acc_min   <= 32'd0;
          acc_max   <= 32'd0;
          acc_seen  <= 1'b0;
          for (k = 0; k < 4; k = k + 1)
              dbg_bank[k] <= 32'd0;
           for (k = 0; k < 4; k = k + 1) begin
               jq_mode[k]  <= 1'b0;
               jq_ld[k]    <= 1'b0;
               jq_seed[k]  <= 32'd0;
               hist_x[k]   <= 32'd0;
               hist_y[k]   <= 32'd0;
               hist_z[k]   <= 32'd0;
               hist_md[k]  <= 1'b0;
               hist_src[k] <= 1'b0;
               hist_tag[k] <= 8'd0;
           end
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
               if (job_launch)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
               if (job_launch) begin
                    step <= 32'd1;
                   mode    <= nxt_mode;
                   job_seq <= job_seq + 8'd1;
                   job_src <= q_launch;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
           if (clr) begin
               jq_wp  <= 2'd0;
               jq_rp  <= 2'd0;
               jq_cnt <= 3'd0;
               jq_ovf <= 1'b0;
           end else begin
               if (jq_push) begin
                   jq_mode[jq_wp] <= sel_add;
                   jq_ld[jq_wp]   <= wr_en;
                   jq_seed[jq_wp] <= wr_data;
                   jq_wp          <= jq_wp + 2'd1;
               end
               if (jq_pop) begin
                   jq_rp     <= jq_rp + 2'd1;
                   n_qlaunch <= n_qlaunch + 8'd1;
               end
               jq_cnt <= jq_nxt_cnt;
               if (jq_reject) begin
                   jq_ovf <= 1'b1;
                   if (jq_drop != 8'hFF)
                       jq_drop <= jq_drop + 8'd1;
               end
           end
           if (jq_cnt > jq_hwm)
               jq_hwm <= jq_cnt;
           if (job_end) begin
               hist_x[hist_wp]   <= rf[12];
               hist_y[hist_wp]   <= y3;
               hist_z[hist_wp]   <= z3;
               hist_md[hist_wp]  <= mode;
               hist_src[hist_wp] <= job_src;
               hist_tag[hist_wp] <= job_seq;
               hist_wp           <= hist_wp + 2'd1;
               if (hist_wp == 2'd3)
                   hist_wrap <= 1'b1;
               hist_sum <= hist_nsum;
               if (mode)
                   n_add <= n_add + 8'd1;
               else
                   n_dbl <= n_dbl + 8'd1;
           end
          cyc <= cyc + 32'd1;
          if (idle && jq_empty)
              idle_cyc <= idle_cyc + 32'd1;
          else
              busy_cyc <= busy_cyc + 32'd1;
          if (wd_active && !job_end) begin
              if (wd_cnt != 16'hFFFF)
