          if (ev_any) begin
              err_code <= ev_code;
              err_tag  <= job_seq;
              err_acc  <= acc;
              if (!err_seen) begin
                  err_seen  <= 1'b1;
                  err_first <= ev_code;
              end
              if (err_cnt != 8'hFF)
                  err_cnt <= err_cnt + 8'd1;
          end
          if (op_live) begin
              case (opc)
                  OP_MUL: n_mul <= n_mul + 16'd1;
                  OP_ADD: n_aop <= n_aop + 16'd1;
                  OP_SUB: n_sop <= n_sop + 16'd1;
