   initial hist_wr_ptr = 2'd0;
   initial hist_rd_ptr = 2'd0;
   initial hist_cnt = 3'd0;
   initial hist_drop = 8'd0;
   initial abort_cnt = 8'd0;
   initial frame_sig = 16'd0;
   initial ret_stamp = 64'd0;
   initial ret_sum = 16'd0;
   initial ret_st = ST_FREE;
   initial ret_vld = 1'b0;
  initial begin
      for (k = 0; k < 8; k = k + 1) begin
          row_sig[k] = 16'd0;
          row_ink[k] = 8'h00;
          row_tag[k] = 64'd0;
          ref_sig[k] = 16'd0;
      end
  end
  initial ref_vld = 1'b0;
  initial ref_hold = 1'b0;
  initial row_chg = 8'h00;
  initial chg_prev = 8'h00;
  initial row_fill = 4'd0;
  initial line_sig = 16'd0;
  initial line_ink = 8'h00;
  initial cap_cut = 1'b0;
  initial cap_cut_row = 3'd0;
  initial cap_sel = 3'd0;
  initial cap_lock = 1'b0;
  initial cap_auto = 1'b0;
  initial cap_wait = 8'd0;
  initial cap_stb = 1'b0;
  initial cap_row_idx = 3'd0;
  initial col_ink = 24'd0;
  initial ext_top = 3'd0;
  initial ext_bot = 3'd0;
  initial ext_vld = 1'b0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
