           hist_wr_ptr <= 2'd0;
           hist_rd_ptr <= 2'd0;
           hist_cnt <= 3'd0;
           hist_drop <= 8'd0;
           abort_cnt <= 8'd0;
           frame_sig <= 16'd0;
           ret_stamp <= 64'd0;
           ret_sum <= 16'd0;
           ret_st <= ST_FREE;
           ret_vld <= 1'b0;
          for (k = 0; k < 8; k = k + 1) begin
