          ref_vld <= 1'b0;
          ref_hold <= 1'b0;
          row_chg <= 8'h00;
          chg_prev <= 8'h00;
          row_fill <= 4'd0;
          line_sig <= 16'd0;
          line_ink <= 8'h00;
          cap_cut <= 1'b0;
          cap_cut_row <= 3'd0;
          cap_sel <= 3'd0;
          cap_lock <= 1'b0;
          cap_auto <= 1'b0;
          cap_wait <= 8'd0;
          cap_stb <= 1'b0;
          cap_row_idx <= 3'd0;
          col_ink <= 24'd0;
          ext_top <= 3'd0;
          ext_bot <= 3'd0;
